namespace BandItPlus.Cultures
{
    // Wave 4.11-fix v43 (2026-05-08): per-vendor identity + voice. 14 cultures × 2 vendor
    // types (food + gear) = 28 unique vendor profiles. Each vendor has their own name,
    // title, 1–2 sentence backstory, and voice-specific gate speech (the "the chief
    // trusts you, I don't" line that fires on first-meet).
    //
    // Wave 4.12-fix v60 (2026-05-11): per-tier deepening — each vendor now also carries
    // T2CraftDetail (craft secret), T2CustomOrderTease (one-shot bespoke tease),
    // T3FamilyBeat (personal monologue), T3ContactName (one-shot cross-camp name-drop).
    //
    // Lookup pattern: HideoutVendorDialog calls VendorProfiles.GetFood(cultureId) /
    // GetGear(cultureId). Returns null for cultures without a profile (so the generic
    // shared dialog text falls through). Currently all 14 cultures have profiles.
    public static class VendorProfiles
    {
        public static VendorProfile GetFood(string cultureId)
        {
            if (string.IsNullOrEmpty(cultureId)) return null;
            switch (cultureId)
            {
                case "forest_bandits":          return _forestFood;
                case "bp_frost_reavers":        return _frostFood;
                case "bp_marsh_stalkers":       return _marshFood;
                case "bp_highwaymen":           return _highwaymenFood;
                case "bp_slaver_caravans":      return _slaverFood;
                case "bp_fallen_legionaries":   return _legionFood;
                case "bp_sky_raiders":          return _skyFood;
                case "bp_steppe_wolves":        return _wolvesFood;
                case "bp_pagan_cult":           return _cultFood;
                case "looters":                 return _lootersFood;
                case "mountain_bandits":        return _mountainFood;
                case "steppe_bandits":          return _steppeFood;
                case "sea_raiders":             return _seaFood;
                case "desert_bandits":          return _desertFood;
            }
            return null;
        }

        public static VendorProfile GetGear(string cultureId)
        {
            if (string.IsNullOrEmpty(cultureId)) return null;
            switch (cultureId)
            {
                case "forest_bandits":          return _forestGear;
                case "bp_frost_reavers":        return _frostGear;
                case "bp_marsh_stalkers":       return _marshGear;
                case "bp_highwaymen":           return _highwaymenGear;
                case "bp_slaver_caravans":      return _slaverGear;
                case "bp_fallen_legionaries":   return _legionGear;
                case "bp_sky_raiders":          return _skyGear;
                case "bp_steppe_wolves":        return _wolvesGear;
                case "bp_pagan_cult":           return _cultGear;
                case "looters":                 return _lootersGear;
                case "mountain_bandits":        return _mountainGear;
                case "steppe_bandits":          return _steppeGear;
                case "sea_raiders":             return _seaGear;
                case "desert_bandits":          return _desertGear;
            }
            return null;
        }

        // ===== FOREST BANDITS (Granny Hod's clan) =====
        private static readonly VendorProfile _forestFood = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_001", "Sit close. Lean in. The smoke hides the words from ears that don't pay for them. You've earned a whisper, traveler — last moon a salt-runner from the eastern roads stopped here with a split lip and a thirst, and what he poured out with the ale was worth more than the coin he left. He said <span style=\"BandItPlus.Name\">Lord Caladog</span> is broke. Broke as a cracked crock. His steward has been buying barley on tally-stick from three different millers in <span style=\"BandItPlus.Place\">Pen Cannoc</span>, and none of them know about the others. When that house of straw falls, every grain-price from here to the coast jumps a quarter. Buy now, hoard, or sell early — your choice, but choose this week.\n\nThe salt road through the gorge below <span style=\"BandItPlus.Place\">Dunglanys</span> is walking near-naked. Two escorts, both green, both drunk by midday — a goat-girl told a peddler told my smoke-boy. I don't tell you that so you'll rob it. I tell you so you'll know why salt prices here are about to climb to <span style=\"BandItPlus.Coin\">14 denars</span> a stone before harvest moon. The boys on the trees have already noticed. When the boys notice, the merchants stop coming, and when the merchants stop coming, even my pork goes hungry for brine.\n\nNow here's the bit that's worth your ear most. There's a fat little buyer up in <span style=\"BandItPlus.Place\">Marunath</span> — calls himself a quartermaster, dresses like a wedding — paying <span style=\"BandItPlus.Coin\">42 denars</span> a side for smoked pork. Forty-two. I sell the same side at the cookpot for sixteen. He's stockpiling for a march nobody's been told about yet, and he doesn't haggle. If you've a mule and three days, you can triple your purse and come back before the snow rots the last of the hams.\n\nOne last thing, and then I'll let you go. Don't take the high pass next moon. A spice caravan came through last week with a crate of pepper they couldn't sell in <span style=\"BandItPlus.Place\">Epicrotea</span> because some new law about foreign goods — and they swore they'd seen a banner camped in the saddle of the pass that wasn't anyone's banner they knew. Forest's full of strangers wearing colors that don't match their faces. Eat. Drink. Then ride the river road. That's a smoke-master's tip, and it costs you nothing but a nod when you pass back through."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_002", "You want the secret? Come closer. Smell that smoke — that's not oak. Oak's what amateurs use, and amateurs in <span style=\"BandItPlus.Place\">Pen Cannoc</span> charge two <span style=\"BandItPlus.Coin\">denars</span> a strip for pork that tastes like a tannery. Mine's beech, cut from the north slope where the lightning struck three summers back, dried two winters under tarp, and split thin as a blade's edge. Beech gives sweetness. But the trick — the real trick — is the apple wood I crumble in for the last six hours. Not chunks. Crumbs. Fine as snuff. The smoke goes from grey to gold and the fat on the pork turns the color of honey held to candle.\n\nThe brine, now — that's where a Smoke-Master earns her name. Salt, yes, but coarse rock salt from the licks east of the brook, never sea-salt; sea-salt makes the meat weep too fast and the smoke can't catch hold. Juniper berries, crushed but not powdered — eight to a shoulder. Two heads of wild garlic. And here's what nobody knows: a single spoon of pine-tar honey, the dark kind the foresters scrape from hollow trees in late autumn. The honey draws the smoke INTO the meat. Without it you're flavoring the rind only. With it, the cure goes clear to the bone.\n\nMy grandfather taught me this the winter I turned eleven. He was bleeding out in the snow — a forester's arrow, between the ribs — and he made me kneel and listen while he whispered the proportions. Said the smokehouse was older than our family and would outlast it, and somebody had to know. Said if I forgot the honey I'd be running a butcher-shed, not a smokehouse, and there's a difference. I have not forgotten the honey. Three winters past my death notice and I have not forgotten the honey.\n\nOne last thing, since you've shown yourself useful. The hams I sell to the caravans bound for <span style=\"BandItPlus.Place\">Marunath</span> — I hang those a hand's-breadth higher than the rest. Cooler smoke, slower cure, twenty-eight days instead of twenty-one. They keep eight months on the road and the merchants pay me triple. If you ever pass that way and a fat man named <span style=\"BandItPlus.Name\">Halmar of the Long Ledger</span> tries to haggle you down on cured pork — tell him Old Brae says the price is the price, and the honey costs what the honey costs."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_003", "Dead Three Winters, Still Curing"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_004", "Pays a man? Pays a woman, too, lad, and don't you forget it. I was born under the eaves of <span style=\"BandItPlus.Place\">Pen Cannoc</span> when it was still half a stockade, and my da kept the smokehouse for the timber-counts there. He died young of the coughing-sickness and left me the curing-shed, the salt-tubs, and a debt to a Battanian thane that I paid off in hams over six long winters. By the time I closed that ledger I knew the back of every alderwood fire and the front of every haggling jarl.\n\nThen the trouble came. A lord whose name I'll not speak — a southern man with a clean cloak and a dirty mouth — claimed my smokehouse stood on his cousin's grant. He sent men. I sent them back with knives in their belts and the wrong end of a hook through a thumb, and that night I walked out with what salt I could carry on a pony's back. The forest took me in because the forest takes everyone the towns spit out, and the chief here had a hundred raiders and not one soul who knew how to keep meat from going green by the third week.\n\nThree winters past my own death-notice, they tell me. Some clerk in <span style=\"BandItPlus.Place\">Pravend</span> wrote me down as drowned in the marsh-crossing — wrong river, wrong woman, but it suited me fine to be a ghost on the rolls. I built the curing-shed you see out yonder with my own hands and a borrowed adze. Salt I trade for in pinches off the <span style=\"BandItPlus.Place\">Quyaz</span> caravans when the boys bring me a wagon; alderwood I cut myself; the pork walks in on its own four feet from raids I do not ask after.\n\nHalf this camp eats off my hooks. The chief knows it, the boys know it, and that is why no man here lifts a hand to Old Brae no matter how black my mood. I sell a leg of smoked shoulder for forty <span style=\"BandItPlus.Coin\">denars</span> and a string of cured eels for fifteen, and if you think that's dear you can go gnaw a bowstring. The trade pays me in keeping warm, in being needed, in dying on my own schedule for a change.\n\nThat's what pays a body into this trade, lad. Not coin — coin is just the tally. It's the want of a place where no clerk can write you dead twice."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_005", "What the Smoke Hears"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_006", "Word on the deer-paths is <span style=\"BandItPlus.Place\">Pen Cannoc</span> burned through its winter salt stocks in a fortnight — some fool quartermaster up there is paying nine <span style=\"BandItPlus.Coin\">denars</span> the pound for grey salt and not asking where it came from. If you've got a mule and a quiet road, that's coin sitting in a barrel waiting to be hauled. I'd go myself if my knees still bent.\n\nThe Battanian drove a long herd of pigs east last moon toward <span style=\"BandItPlus.Place\">Marunath</span>, and half of them broke loose in the bracken north of here. <span style=\"BandItPlus.Name\">Wether-Ban the Drover</span> is offering finder's coin to any soul who pens the strays back — but between you and me, the boys upstream have been bringing me pork I didn't ask about, and I don't ask. Three winters I've been smoking that drove's loss into your suppers.\n\nBad news for the porridge bowl. The grain wagons out of <span style=\"BandItPlus.Place\">Dunglanys</span> won't move this season — the miller's wife took ill and the wheel's been still since the equinox. That means <span style=\"BandItPlus.Place\">Car Banseth</span> will be buying oats off any caravan that can reach them by hard frost, and the price will double before the snow does. Stock now or starve clever.\n\nThere's a sweetwine train coming up from <span style=\"BandItPlus.Place\">Epicrotea</span> under a Vlandian factor called <span style=\"BandItPlus.Name\">Sir Aldrec of Hateng</span> — three wagons, light guard, taking the southern track because the northern road washed out. Whether you mean to buy from him or relieve him of the burden is your business, but he'll be past the fording stones in eight days. The chief knows. The chief always knows.\n\nAnd one last thing, since you've stood here patient. A blight is creeping through the apple stands east of <span style=\"BandItPlus.Place\">Hertogea</span> — black-spot, the kind that ruins cider for three winters. If you've a friend with an orchard, tell them to burn the windfalls now. I lost my own grove to it once, long before this smokehouse. That's how I learned which trade keeps a body fed when the trees don't."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_007", "Old Brae of the Smokehouse"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_008", "Smoke-Master"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_009", "Cured venison for the Battanian wood-villages forty winters before a Vlandian tax-inspector burned his shed for \"unlicensed barter.\" Came to Hod with three salt-barrels and a missing tooth."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_079", "Old Brae here, traveler. Hod's boys say you walked in alone, and the chief's word's good enough to keep your skin. But Brae's smokehouse is Brae's, and your boots haven't earned a rasher of it yet. Bring me {BP_VENDOR_QUEST_DESC} — the wood-villages have been thin this winter — and I'll cut you the first slice off the rack."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_010", "Brae cures over alder-wood, traveler — not the green oak the lowland larders rush. Alder lets the salt walk in slow. Three weeks per haunch; the wood-villages knew the difference, before the lord forgot they existed."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_011", "Bring me three salt-sacks and a winter's notice, traveler — Brae'll cure you a haunch the Vlandian governor would have hanged his own steward for serving. A sample on the house. Walk back when you can."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_012", "Had a wife once — Mara of the upper birch-stand. Took the boys west when the gibbet-men came; never sent word after the first winter. Brae still sends a smoked haunch to the wood-villages every spring on her birth-month, in case the road runs both ways."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_013", "Aunt Lien runs a smokehouse-tavern at the Pravend crossroads — hidden under a butcher's awning. Tell her Old Brae cured the deer Hod's boys ate the night they hanged Brec. She'll seat you in the back room. Here's coin for the toll-clerk.")
        };
        private static readonly VendorProfile _forestGear = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_014", "Lean in, friend. You've earned an ear, and I've got two of them full this week. A tinker out of <span style=\"BandItPlus.Place\">Pen Cannoc</span> rolled through three nights back, axle squealing fit to wake the dead, and over a cup of my worst he let slip that <span style=\"BandItPlus.Name\">Lord Caradoc</span> is in arrears to half the smiths in the western glens. Boy can't pay for the swords he ordered last harvest. His levy's marching with rust on the rims and the master-at-arms is quietly putting the good kit out to pasture in the back of the armory. If you've a spare blade and a soft tongue, you could fleece that household for a fortnight's <span style=\"BandItPlus.Coin\">denars</span> easy.\n\nNow here's the prize cut. The Steelroad — the long stone track that runs from <span style=\"BandItPlus.Place\">Marunath</span> down toward the river fords — is carrying billet caravans this fortnight, and the escort has thinned to four lances on account of the muster up north. Four lances, friend. For wagons of half-finished steel. A smuggler I trust (and that's a short list) said the wheel-ruts are deep enough you can hear them coming from a ridge over. I'm not telling you to take it. I'm telling you what I heard. Do with it what your conscience can stomach.\n\nOn the trade side — leather is glutted something fierce. Every tanner from here to <span style=\"BandItPlus.Place\">Sanala</span> is sitting on hides because the southern caravans came in two months late and three months heavy at once. Prices are on their backs and won't roll over till midwinter. Don't sell your tack now if you can help it. Conversely, iron stock's gone scarce in the hills — there's a fool of a merchant in <span style=\"BandItPlus.Place\">Pravend</span> who's paying near sixty <span style=\"BandItPlus.Coin\">denars</span> the bar because his contracts run on and his suppliers walked. Sixty. For pig iron. I'd ride a week of bad weather for that ledger.\n\nThat's the cream of it. Mend your straps before you go — I'll do the buckles cheap for the man who brought my coopering kit back to me. And keep what I've told you between the two of us. A barrel-mender hears things because nobody bothers to lower their voice around the fellow with the mallet, and I'd like to keep it that way."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_015", "You want to know why my barrel-staves hold a war-axe haft better than most smith's iron-bands? It is the soak. Green oak, split along the grain — never sawn, never. The blade splits where the wood wants to part; the saw lies to you, cuts across the fibres, and the haft breaks on the third swing. I rive every stave with a froe my father willed me, and I quarter them by moonlight when the sap has drawn low into the roots. That is half the secret. The other half is what we soak them in.\n\nThree nights in a barrel of tannin-water — oak galls crushed, a fist of iron filings, a splash of vinegar I trade off the <span style=\"BandItPlus.Place\">Galend</span> road. The iron bites the tannin and turns it black as a crow's eye, and the wood drinks it deep. When it dries, the stave is half-stone. A haft made this way will not split when a shield rim catches it, and it does not rot in the rain. The bandits laugh because their axes outlast the smith-bought ones their fathers carried — and they paid me forty <span style=\"BandItPlus.Coin\">denars</span>, not four hundred.\n\nI learned the tannin trick from my father the morning <span style=\"BandItPlus.Name\">Lord Aerlon</span>'s reeve came to measure our shop for seizure. Father had a stave-blank curing in the corner barrel and he made me hide it under my cloak before they kicked the door in. On the road north he taught me the rest of it — the moon-cut, the iron, the count of nights — because he knew he would not see another winter and the knowledge had to live somewhere. So when I sell you a re-shafted axe, you are paying for three nights of a dead man's patience.\n\nOne more thing, since you have stood with us. The pitch I seal the binding with — that I will not tell. Not yet. But ask me again after another season on the road and I might let it slip over a cup."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_016", "My Father's Hoops And Staves"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_017", "My father kept a cooper's shop two streets back from the river-gate at <span style=\"BandItPlus.Place\">Pen Cannoc</span>. Barrels, buckets, butter-firkins — anything a man could hoop and bind, my father bent the staves for it. I was eight when he first put a draw-knife in my hand, and the smell of fresh oak shavings is still the only smell I trust.\n\nThen <span style=\"BandItPlus.Name\">Lord Ervil of the Crossing</span> decided the lane belonged to his wife's brother. No writ, no court-day, no warning — just three men with billhooks and a parchment nobody read aloud. They took the shop, the wood-yard, the iron hoops my father had paid <span style=\"BandItPlus.Coin\">forty denars</span> a bundle for, and when my father set his hand on the door-post they took his fingers too. He lived a winter after that. Not much of one.\n\nSo I walked. I had a draw-knife, a small adze, and a cooper's rasp — no forge, no anvil, no coin for either. The road took me past <span style=\"BandItPlus.Place\">Quyaz</span> and the cart-tracks the Battanian wood-runners use, and somewhere in the third week a man with a notched bow asked me whether I could put a new strap on a buckler. I could. I did. He fed me, and he brought me here.\n\nThat's why I mend. A forge wants charcoal and quench-water and a smith who learned at twelve, and I'm none of those. But I can rivet a split scabbard, re-strap a brigandine, re-haft an axe, re-stitch a saddle-skirt, and pull the rust off an edge that some fool let sit in the rain. The camp keeps me in oak and oil and a roof, and I keep their gear standing one more season.\n\nI don't forge new things. New things belong to men with shops on lanes that nobles haven't taken yet. I mend — because the world is full of broken iron, and somebody has to put the hoops back round it."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_018", "Word From The Cart-Roads"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_019", "Word from <span style=\"BandItPlus.Place\">Pen Cannoc</span> is the garrison's tightening fists around every iron ingot that comes off the western roads. Their reeve hung two tinkers last moon for \"unlicensed mending\" — meaning the smiths there want all the broken kit funneled through their forges at twice the honest price. Anything we mend here costs the bearer half what those gate-smiths charge, and no questions about where the rivets came from.\n\nA Battanian caravan slipped past the toll-ford ten days back hauling raw bog-iron south toward <span style=\"BandItPlus.Place\">Marunath</span> — six mules, no escort worth speaking of, drovers half-drunk on heather-beer. Word is they sold the lot to a merchant working for <span style=\"BandItPlus.Name\">Lord Caradros</span>, who's quietly stockpiling for shields he doesn't want the High King counting. If you're moving that road, the runoff scraps are still scattered along the verges where mules broke pack.\n\n<span style=\"BandItPlus.Place\">Dunglanys</span> is paying <span style=\"BandItPlus.Coin\">forty denars</span> a head for journeyman bowyers — their string-master died of the coughing-fever and the fian-bands are screaming for new staves before the autumn raid season. They're not asking where a man trained, which tells you how desperate the steward's gotten. A useful place to fence a bundle of yew or a stack of unfletched shafts, if you can stomach the road.\n\nLast bit, and this one's worth the listen — a <span style=\"BandItPlus.Name\">Sturgian</span> peddler came through three nights past, said the highland reaver-clans are buying every leather scrap and rivet they can find. Means a war-band's kitting up quiet, and means saddle-leather and harness-iron will fetch double their summer price by month's end. Mend what you've got now. Sell what you can't keep."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_020", "Halvar Cooper"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_021", "Wood-Cooper"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_022", "Carved staves for poachers in the deep oaks before the lord's gibbet-men hanged his brother Brec. Now he carves for Hod's boys; the bows are unmarked but they fly true."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_080", "Halvar Cooper, traveler. Name a stave and I'll tell you who it killed. The chief lets you walk — that's the chief. But the staves are mine, and a man earns them. Bring me {BP_VENDOR_QUEST_DESC} from the road, and you'll see what an unmarked Battanian bow flies like."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_023", "The staves come from a coppiced stand my grandfather worked, traveler. The wood remembers the cut — that's why the bows fly true. Imperial stockmen call it 'old-growth flutter' and don't know what they're saying."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_024", "Mark me a draw-weight and a wood, traveler. On your next pass I'll have a stave that drinks the wind. The unmarked ones I sell are good — the marked ones I keep for the boys. Here, a wax-pull off the spare to seal the deal."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_025", "Brec was my elder, traveler. The gibbet-men came at the high field — Vlandian law called it 'poaching' for three hares the lord hadn't named. I carved his name into the stave-stand the morning after. The grain's grown around it now."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_026", "Find Old Aengus at the Tinker's Bridge, traveler — carves cradles by day, arrow-shafts by lamp-night. He learned the unmarked-stave trick from my grandfather. Tell him you've sat at Hod's fire; he'll show you the lamp-night shelf. Coin for the road.")
        };

        // ===== FROST REAVERS (Vargolf's clan) =====
        private static readonly VendorProfile _frostFood = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_027", "Lean close, friend, and keep this between us — the salt knows what the snow hides. A driver came through three nights past, frost still on his beard, and he let slip that <span style=\"BandItPlus.Name\">Lord Vesimir Greycoat</span> is bleeding silver faster than a gutted herring bleeds brine. His men haven't been paid since the thaw, and his quartermaster has been buying salt-cod on credit from <span style=\"BandItPlus.Place\">Revyl</span> — the kind of credit nobody intends to honor. If you cross his banner on the road, his garrison's hungry, and hungry men sell their oaths cheap.\n\nThe southern grain road out of <span style=\"BandItPlus.Place\">Tyal</span> is thinner than a widow's stew this season. Two caravans came through and both said the same: escort of six, sometimes four, sometimes a single drunk huscarl who couldn't tell a wolf from his own shadow. The wheat barges are stacking up at the docks because the merchants are too frightened to move them inland, and the price of black bread in the up-country villages has doubled. Salt-cured grain, oats, anything that keeps — somebody clever could buy low at the docks and sell at the inland holds for thirty <span style=\"BandItPlus.Coin\">denars</span> a sack more than fair.\n\nAnd here's the morsel worth chewing on. There's a fat little spice-broker out of <span style=\"BandItPlus.Place\">Omor</span> — bald fellow, rings on every finger — who's overpaying like a fool for smoked fish. Sixty <span style=\"BandItPlus.Coin\">denars</span> a barrel, when the going rate on the coast is forty. Word is his wife's people are Sturgian and she'll only eat the proper smoked stuff from up north, and he can't stand to disappoint her. A man with a wagon and a nose for smokehouses could double his coin in a single run if he doesn't drink the profits along the way.\n\nLast thing, and then I'm done. The smokehouses east of <span style=\"BandItPlus.Place\">Varcheg</span> are short on alder wood — a fire took half their stock in spring — and they're paying near double for any cartload that arrives before the frost sets hard. My Sami used to cut alder in his younger years. He'd have known. But you didn't hear any of this from old Nikolai, you understand. The salt keeps its counsel, and so do I."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_028", "You ask the secret, eh? Sit closer. The wind takes words and I will only say this once. The salt-cod you bought last moon — that is not common salt. It is three-pull brine: first pull is sea-salt from the rocks below <span style=\"BandItPlus.Place\">Varcheg</span>, coarse, grey, full of iron. Second pull is rock-salt the reavers bring back from the eastern raids, sweeter, drier. Third pull — and this is the trick — is wood-ash from birch only, never pine. Pine ash makes the cod taste of resin and a man will spit it out by the second bite. Birch ash pulls the wet from the flesh slow, like a patient hand, and leaves the fish firm but never brittle.\n\nMy Pyotr taught me this on the day the ice broke early, the year before the frost took him. He said his father learned it from a Nordic trader at <span style=\"BandItPlus.Place\">Omor</span> who came down with two barrels of cod that did not rot through a whole winter march. The secret is not the salt — every fool has salt. The secret is the order. First, gut and split, never scale. Then bury in the coarse grey for two days. Then wash in sea-water — not fresh, never fresh, fresh water kills the flavor. Then the rock-salt for four days, weighted with stone. Then the birch ash rub, only the palms, never a cloth. A cloth steals the oil from your hand and the cod needs that oil to seal.\n\nSmoke I do not use. Smoke is for men who do not trust their salt. The reavers ride in winter and they cannot carry smoked fish — it sweats inside the leather and goes sour by the third night. Salt-cod cured my way will sit in a saddle-pouch for forty days and still feed a man on the forty-first. That is why they pay me what they pay me. Two hundred <span style=\"BandItPlus.Coin\">denars</span> for a sack that would fetch eighty in <span style=\"BandItPlus.Place\">Revyl</span>, and they do not haggle. They know.\n\nOne more thing, since you have shown yourself honest. If you ever try this yourself — and I doubt you will, the work is hard — do not let the cod freeze before the third pull. The grey salt has to draw, and a frozen fish draws nothing. I learned this the bad way, the first winter alone, when I lost a whole catch and ate cabbage for two months. Pyotr would have laughed at me. He laughed at everything. That is what I miss most."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_029", "The Salt Always Pays"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_030", "My man Yegor pulled cod from the Sturgian shallows out past <span style=\"BandItPlus.Place\">Revyl</span> for nineteen winters, and I salted every fish he ever brought home. We were not rich, but the smokehouse stayed lit and the barrels stayed full. Then the frost came down hard the year the ice ate the longboats, and Yegor went under with his net still in his hand. They never found him. Only his belt washed up on the gravel a week later, swollen and grey.\n\nThe boyars at <span style=\"BandItPlus.Place\">Revyl</span> took the boat for tax debts before the wake was finished. <span style=\"BandItPlus.Name\">Lord Vladic</span> wouldn't see me at his gate — said a fisher's widow had no claim on a vessel that owed the crown. I sold what I could carry and walked north with two barrels of salt-cod on a sled, looking for any roof that would have me. A widow without a hearth dies in three nights up here. Everyone knows it.\n\nThe reavers found me on the third night, half-frozen at the foot of a stone cairn. They could have taken the cod and left me. They didn't. The chief tasted my salt, looked at my hands, and said a woman who can cure fish that well is worth more breathing than buried. So I cure for them now. Cod, seal-meat, the river-pike when the lads bring them in, and I keep the salt-pans running in the lower cave where the air stays dry.\n\nI trade fair because cold trade IS honest trade — there is no room up here for sweet talk or short measure. A barrel of salt-cod costs you what a barrel of salt-cod costs. Sixty <span style=\"BandItPlus.Coin\">denars</span> for the cured, forty for the smoked, and the dried strips go by weight. The reavers eat first, you eat second, and what's left I'll send south with the next runner toward <span style=\"BandItPlus.Place\">Omor</span> if the passes are open.\n\nI don't miss Yegor every day anymore. I miss him when the wind comes off the ice and smells like his coat. The rest of the time I work, and the work pays, and that is enough for a woman who used to think the sea owed her something. It owed me nothing. The salt does. The salt always pays."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_031", "Word From The Salt-Runners"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_032", "The salt-runners came down from <span style=\"BandItPlus.Place\">Revyl</span> three nights past, and they tell me the smokehouses there will pay forty <span style=\"BandItPlus.Coin\">denars</span> a barrel for cod packed dry — twice last winter's price. The fjord catch failed, see. Every herring boat that limped home came back half-empty, and the jarls are buying anything that swims, salted or sour.\n\nGrain is the other tale. <span style=\"BandItPlus.Name\">Lord Olek of the Black Hand</span> bought out three caravans bound for <span style=\"BandItPlus.Place\">Tyal</span> — paid in coin, not promises — and now the village hearths north of the Sturgian woods are baking rye-husk bread thin as parchment. Famine's coming up the river road by the first thaw, mark me. The reavers will eat well; the cottars will not.\n\nThere's a Vlandian wine-train moving east out of <span style=\"BandItPlus.Place\">Pen Cannoc</span>, sweetwine in oak, bound for some lordling's wedding at <span style=\"BandItPlus.Place\">Pravend</span>. Three wagons, eight guards, slow because the road's still ice. My old salt-partner <span style=\"BandItPlus.Name\">Bjorn Greyhook</span> sent word — if a certain camp were to hear of it, certain barrels might find their way to certain cellars. I sell salt. I do not sell the location of wagons. But I do not forget who pays in good silver, either.\n\nLast word — the eel-ponds at <span style=\"BandItPlus.Place\">Quyaz</span> froze through, bottom to top. Whole season's catch lost. Khuzait merchants are riding west looking for smoked fish at any price, and they carry <span style=\"BandItPlus.Coin\">dinars</span> heavier than our coin. A clever man with a sled of cod could ride back rich, or ride back dead. The steppe doesn't care which.\n\nSo that's the road, as I have it. Three markets hungry, one wagon fat, one famine creeping. Buy what you can carry. Spring is a thief and winter is worse."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_033", "Nikolai Salt-Hand"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_034", "Salt-Master"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_035", "Worked the Pravend salt-pans before his guildhouse cut his ration for refusing a foreign trade-deal. Came north with three barrels and a vendetta — the Reavers ate well that first winter."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_081", "Nikolai Salt-Hand, traveler. Vargolf says you walked the snow without leaving a body — that's no small mark. But the salt's mine, and I sold my last share to a guild that betrayed me. Bring me {BP_VENDOR_QUEST_DESC} and I'll season your fire the way the Pravend lords used to be served."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_036", "Pravend salt isn't the white-flake the imperials sell, traveler — it's grey-grain, three-times-washed, draws the marrow up through bone. Lordly cooks would pay an outrider's wage for a barrel. I haven't sold them one yet. The vendetta keeps."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_037", "Tell me the meat and the man, traveler, and I'll season a feast the Pravend high-table used to call winter's-keep. Six denars upfront, a barrel on your saddle next pass. Here, a pinch for your road-stew tonight."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_038", "Had a daughter — Anya. Her hand was the payment for the trade-deal I refused. The guildhouse took her north as a 'ward'; she'd be twenty winters now, if winters kept her. I salt her name into every barrel I open. The grey draws the count up out of nothing."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_039", "Old Yevgen pickles fish at the Sturgian dock-quarter under a fishmonger's sign — same grey salt, half the price. Tell him Nikolai's barrel still waits for the guild that broke us. He'll fill your sack twice. Coin for the ferry-toll.")
        };
        private static readonly VendorProfile _frostGear = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_040", "Lean close, friend, the bellows drown the words and that suits me fine. A salt-runner out of <span style=\"BandItPlus.Place\">Omor</span> bought a horseshoe off me last week and paid in coin and tongue both. He says <span style=\"BandItPlus.Name\">Lord Vagas</span> hasn't paid his garrison in two moons — sold his second-best stallion to a Vlandian factor for half its worth. A lord short on <span style=\"BandItPlus.Coin\">denars</span> sells his swords cheap and his secrets cheaper. Mark that.\n\nThe Sturgian iron road from <span style=\"BandItPlus.Place\">Revyl</span> down through the pine cuts — escort's thin. Used to ride forty spears, now it's twelve drunk huscarls and a wagon-master who can't tell north from his own arse. Three billet-trains have come through in a month and not one with a proper screen. If a man wanted Sturgian steel at Battanian prices, that road's bleeding it. I'm not saying. I'm just saying.\n\nHere's the one worth your ear. A fat little fence in <span style=\"BandItPlus.Place\">Tyal</span> — calls himself a tanner, isn't — is paying double on cured boar-hide. Double. Some northern lord's outfitting a hunt-company in secret and the leather glut up here means I can buy hides for next to nothing and sell them to him at his price. I won't be the only one onto it long, so if you're riding that way and your saddlebags have room, we can split the freight and the take.\n\nAnd mind — none of this came from me. The forge is loud and old Magnus is half-deaf in his bad ear. Whatever you heard, you heard from the wind."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_041", "You want the secret? Lean close, southerner. Half the smiths in <span style=\"BandItPlus.Place\">Sibir</span> will tell you the cold makes the steel brittle. They are fools who learned their trade in a heated shop and never left it. The cold is the second hammer. When I draw a blade glowing yellow from the coals and the wind off the ice is on my back, the surface skin of the steel sets harder than the core in the same breath. That is the secret — a differential temper without clay, without the painted lines the Vlandians use. Just the wind. Just the dark. I forge with the forge door open to the snow, and I time the strikes between gusts.\n\nThe grandfather of my grandfather was a shield-wright at <span style=\"BandItPlus.Place\">Revyl</span>, and he taught my father, and my father taught me before the Sturgian iron took my eye at the wall. There is a thing he showed me with the seax-spine. You fold the high-carbon billet seven times — never eight, eight is the Vlandian count and it leaves the steel tired — and on the final fold you quench in seal oil, not water. Seal oil holds the heat slower, draws the carbon to the edge without warping the back. The blade comes out with a spine soft enough to bend against your knee and an edge that will shave the hair off your forearm a year later. I sell those for eighty <span style=\"BandItPlus.Coin\">denars</span> apiece and lose money on every one, but a man should leave good work behind him.\n\nThe leather is the other half nobody asks about. I cure the scabbard hides in brine and birch-tar smoke for a full moon before I cut a single strap. Most of the leatherwrights you'll meet south of the <span style=\"BandItPlus.Place\">Hrustgar</span> ridge soak their hides three days and call it done — and three winters later their scabbards are rotted and their grips are loose. Mine outlast the man who buys them. <span style=\"BandItPlus.Name\">Old Yarrick</span>, who runs the tannery at the edge of camp, keeps a barrel of the brine going year-round just for my orders. He is missing two fingers from the same shield-wall that took my eye, so he understands why the work has to be slow.\n\nOne more thing, since you have earned it. If you ever buy a blade from a smith and he will not let you see it quenched, walk away. The quench is where the lie lives. A coward smith hides the quench because his steel hisses wrong, or his oil is cut with tallow, or the blade twists and he straightens it cold afterward — which any man with one eye can feel in the balance. I quench in the open. You can stand at the door and watch the steam rise off the seal oil if you like. That is how my father did it, and his father, and that is why the men of <span style=\"BandItPlus.Place\">Sibir</span> still come to me when the southern jarls have ruined their armouries."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_042", "Iron Remembers The Cold"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_043", "You ask what pays a man into this trade. The honest answer is a Sturgian shield-rim and a winter that wouldn't end. I stood in the third rank at the wall outside <span style=\"BandItPlus.Place\">Revyl</span>, axe in my off-hand, when a boss-spike came over the top and took my right eye clean as a butcher's hook. The surgeon wanted twenty <span style=\"BandItPlus.Coin\">denars</span> to sew the lid shut. I gave him fifteen and the broken axe, and he called it square.\n\nCouldn't soldier after that. Depth-vision's a fine thing to lose for a man who swings sharp things at moving targets. So I went back to what my father taught me before the levies came calling, only now I had the shake in my off-hand and one good eye for the glow of the bloom. Spent two winters in a smithy outside <span style=\"BandItPlus.Place\">Sibir</span> hammering nails for fishing-sleds. Nails. After the shield-wall. The shame of it kept me warm when the bellows didn't.\n\nWhat I learned in those two winters is the cold loves a forge more than any southern sun. Steel quenched in <span style=\"BandItPlus.Place\">Revyl</span> river-ice holds an edge a <span style=\"BandItPlus.Place\">Pravend</span> smith would weep for. The grain tightens. The temper goes deep instead of glassy. <span style=\"BandItPlus.Name\">Bergthor of the Lake</span> tried to buy my whole shop for sixty <span style=\"BandItPlus.Coin\">denars</span> a month and a roof; I told him my anvil don't travel south of the snowline, and he called me a fool.\n\nReavers found me when the Sturgian tax-collectors did, and one was friendlier than the other. They wanted helms reshaped, mail re-ringed, axe-eyes re-hafted — honest work, paid in coin or in the warlord's silence, depending on the week. I keep my forge under their roof now. The cold helps the temper, the camp keeps the tax-men south of the ridge, and a one-eyed smith with a steady left hand turns out gear that holds against any shield-wall I ever stood in.\n\nThat's the trade. Cold steel, cold price, cold truth. The eye was the down-payment. The rest of me's been paying interest ever since."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_044", "Cold Anvils, Colder Coin"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_045", "Word from <span style=\"BandItPlus.Place\">Revyl</span> is the garrison is taking on smiths — three, maybe four, paid in salt and silver both. <span style=\"BandItPlus.Name\">Lord Bulgnak</span> wants two hundred round-shields banded in iron before the thaw, and he is not haggling. If a man still had two good eyes and a whole back, that contract would be worth the ride.\n\nA caravan out of <span style=\"BandItPlus.Place\">Sibir</span> is moving steel-stock south along the frozen river road — Battanian billets, the dark grey kind that takes a long edge. They lost two guards to wolves last week, so the captain is hiring spears at <span style=\"BandItPlus.Coin\">forty denars</span> a day. The stock itself? He will sell short bars to anyone with coin and no questions. I bought what I could carry.\n\n<span style=\"BandItPlus.Name\">Jarl Yrsa</span> at <span style=\"BandItPlus.Place\">Omor</span> paid out for a full set of lamellar last moon — twelve hundred <span style=\"BandItPlus.Coin\">denars</span>, they say, and the smith who took the work has not been seen since. Make of that what you will. Up here, a man finishes a commission and then he disappears, and the jarl's hall has new armor on the wall. I do my work in the open, where the camp can see.\n\nThe Sturgian shield-wall took my eye but it taught me the trade — every dent in those wall-shields was a lesson. So when I tell you the southern leather coming up through <span style=\"BandItPlus.Place\">Tyal</span> is too soft for our winter, believe me. Use it for grips, not for facings. The cold finds the weak stitch, same as the spear does.\n\nLast thing. There is a Vlandian factor riding the back tracks asking who supplies blades to the reavers. Offers <span style=\"BandItPlus.Coin\">two hundred denars</span> for a name. Nobody has sold mine yet — but if you hear it whispered, you tell me before you tell him. Cold steel. Cold price. Cold truth."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_046", "Magnus One-Eye"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_047", "Iron-Hand"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_048", "Lost his eye to a Vlandian outrider who took his daughter's hand in payment for a debt the Yulskaya didn't owe. Forges now under Vargolf's banner; the blade he made for that outrider is still spoken of in the high passes."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_082", "Magnus One-Eye, traveler. The chief takes your measure with axe-eyes; I take it with the empty one. Bring me {BP_VENDOR_QUEST_DESC} from the snow-road, and I'll forge you what no Vlandian outrider would dare carry. That's a long story — the empty eye keeps it for another fire."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_049", "Vlandian outriders forge their plate at noon-heat, full-charcoal — quick to make, brittle by the third campaign. I bank the fire down to ember-glow for the last temper. Three more strokes a blade and the steel sings instead of cracks."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_050", "Bring me an iron-bar and your name, traveler, and I'll bank the next pull just for you. Long blade, axe-head, hammer — your hand on it before it cools. A token from the spare-stock to mark the deal."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_051", "Lost the eye to a Vlandian outrider in payment for a debt the Yulskaya didn't owe. He took my daughter's hand the same hour — that part of the night the empty eye keeps for itself. The blade I made for him is still spoken of in the high passes. He doesn't tell it as praise."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_052", "Find Hjalmar Ember-Hand in the Nevyansk forges — he learned his last temper from me before I came north. Tell him One-Eye still banks low; he'll know I sent you. He charges fair if you bring the iron yourself. Take this for the iron.")
        };

        // ===== MARSH STALKERS (Mireborn's clan) =====
        private static readonly VendorProfile _marshFood = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_053", "Lean close, friend. The reeds whisper, aye, but so do the bargemen who tie up past the bend, and I've been listening to both. Word from a salt-hauler out of <span style=\"BandItPlus.Place\">Pen Cannoc</span> is that <span style=\"BandItPlus.Name\">Lord Caradoc</span> has gone quiet on his debts — three smokehouses up the coast won't take his promissory marks anymore, and his steward was seen begging credit for two barrels of brined trout. Man's purse is thinner than a heron's leg. If you owe him favor, collect now in <span style=\"BandItPlus.Coin\">denars</span>, not next moon.\n\nThe grain road through the lower fens — the one that hugs <span style=\"BandItPlus.Place\">Marunath</span> — is walking with only four spears these past ten days. Four. For a six-cart train of barley and smoked carp. The merchant's a Vlandian fellow, name of <span style=\"BandItPlus.Name\">Renier of Galend</span>, and he's cheap as a clipped coin. Bargemen reckon he'll lose the lot before the next half-moon. I don't say what a man should do with that knowing — only that I know it, and now you do.\n\nHere's the one worth the eel-grease: there's a butter-and-cheese factor out of <span style=\"BandItPlus.Place\">Sibir</span> overpaying — I mean truly overpaying, twelve <span style=\"BandItPlus.Coin\">denars</span> the pound for smoked eel, when the going rate's seven at any market between here and the salt-flats. Some Nord lordling's hosting a feast and his cook went mad with the menu. The factor's at the crossroads tavern by <span style=\"BandItPlus.Place\">Car Banseth</span> till the new moon. Take him your smoked stock; don't haggle soft, the man's desperate and won't blink.\n\nOne last thing, and I'd not say it to a stranger. Salt's drying up north — the brine pans at <span style=\"BandItPlus.Place\">Omor</span> took a flood and won't yield till midsummer. Anyone holding salt now sells it for triple by harvest. The reeds didn't tell me that one. A drunken salter did, two nights past, before his cousin clouted him quiet. So you heard it from the eels, understand? Not from me."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_054", "You want the secret? Lean close. It is not the catching — any drunk with a spear can stab an eel in clear water. It is the curing. Most folk gut their eels, salt them flat, hang them in smoke for three days, and end up with leather you could resole a boot with. Mine come off the rack soft as river-clay and sweet as a young wife's first bread. The trick is the reeds. Not just any reeds — the black-tipped ones that grow downstream of where the bitterns nest, where the water turns the colour of strong tea.\n\nI cut a bundle thick as my wrist, bruise them with a mallet until the green smell comes out, then layer them between the split eels in a clay crock. Coarse salt on top, a fistful of crushed juniper berries I gather from the dry hummocks, and one — only one — pinch of the brown sugar I trade for at <span style=\"BandItPlus.Place\">Sanala</span> when the caravans pass. Press it with a flat stone the weight of a newborn. Three days in the crock, then two more in cold smoke from alder wood. Never oak. Oak makes them bitter. Never pine. Pine makes them taste of a man's piss.\n\nMy grandfather showed me this the winter my mother died. I was nine. He sat me on his knee in the smoke-shed and said, \"Tomas, the marsh feeds the man who listens to it. The reeds tell the eels where to hide. They tell us how to keep them.\" He had no teeth left, only gums hard as boot-soles, and he ate three of these eels every morning until the day he walked into the fog and did not walk back. I think the reeds called him too. I do not mind. I will go the same way one day.\n\nTell no one the alder. I have killed two men who tried to sell my eels in <span style=\"BandItPlus.Place\">Pravend</span> as their own work, and both times the buyers came back asking why the new batch tasted of pine. Word of the alder gets out, and any fool with a smoke-shed can undercut me at four <span style=\"BandItPlus.Coin\">denars</span> the brace. Keep it behind your teeth, friend, and I will keep a crock aside for you when the season turns."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_055", "The Reeds Told Me Where"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_056", "Sit. Mind the slat — it sinks. My da was a reed-cutter near <span style=\"BandItPlus.Place\">Pen Cannoc</span>, sold bundles to the thatchers for half-copper a stack. I learned the marsh before I learned my letters, which I never did learn. The reeds breathe different over an eel-hole. Slow. Heavy. Like a sleeping dog.\n\nTook an arrow in the eye at twelve, working a fen for a Vlandian tax-man who called my da a poacher. Da bled out in the punt; I crawled home blind on the left. The lord — some cousin of <span style=\"BandItPlus.Name\">Lord Caladog</span>, name not worth keeping — paid us four <span style=\"BandItPlus.Coin\">denars</span> in settlement and called the matter closed. Four. For a man and an eye. I learned a useful number that day.\n\nAfter that I worked the smokehouses up at <span style=\"BandItPlus.Place\">Jaculan</span> — gutting, salting, hanging eel over alder coals till the flesh went amber. Good trade, honest trade, until the steward cut wages and the guild blamed the marsh-folk for the shortage. I walked out with a barrel of brine and a smoker's grate strapped to my back. The reeds were waiting where I'd left them.\n\nFound this camp by following a heron three days west. The captain tried the eel-stew, paid me in salt and a dry corner, said stay. So I stay. I pull eels blind — proper blind, the good eye's near gone too — and the reeds tell me where. They lean toward the holes. They whisper at the fat ones. You think I'm soft in the head; that's fine. The pot's full and the boys eat.\n\nPays a man into this trade? Four <span style=\"BandItPlus.Coin\">denars</span> and a dead father. Everything since has been the marsh keeping me, and me keeping the marsh. Take the smoked eel — it's good. Salt's from <span style=\"BandItPlus.Place\">Ortongard</span>, paid honest."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_057", "Reeds Whisper, Roads Talk"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_058", "Sit. Mud's warm enough. Word travels slow through the fens, but it travels — boatmen pass it bowl to bowl, and I keep my ears open while I'm gutting. Three things worth your while, maybe four. Listen as slow as I talk.\n\n<span style=\"BandItPlus.Place\">Pen Cannoc</span> is short on salt. Two of the upland smokehouses lost their winter stock to damp rot, and the steward's quartermaster has been paying fourteen <span style=\"BandItPlus.Coin\">denars</span> a sack — fourteen, for grey salt that's half marsh-grit. If you've got clean stone-salt and a strong back, the road north pays better than the road south right now.\n\nA grain caravan out of <span style=\"BandItPlus.Place\">Druimmor</span> went into the bogs two weeks back and hasn't come out. <span style=\"BandItPlus.Name\">Lord Caradoc</span>'s reeve has been riding the causeway every dawn looking for it, which means his garrison's ration is thinning. Hearth-bread will spike by the next moon. I'd hold any barley you've got — sell it after the frost, not before.\n\nThe sweetwine boats from <span style=\"BandItPlus.Place\">Epicrotea</span> are coming up through the delta again, late but coming. <span style=\"BandItPlus.Name\">Old Halvar</span> at the lower jetty already bought out two casks for resale — he'll mark them triple by midsummer. Buy direct off the boat or don't buy at all.\n\nLast thing, and you didn't hear it from me. The eels are running wrong this year. Reeds bend south when they shouldn't, and the females are coming up thin. That means a lean smokehouse autumn from <span style=\"BandItPlus.Place\">Pen Cannoc</span> clear down to <span style=\"BandItPlus.Place\">Quyaz</span> — dried meat will be the only winter trade worth carrying. Mark it. The marsh is patient, but it isn't generous twice."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_059", "Tomas Eel-Bone"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_060", "Reed-Master"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_061", "Wove fish-traps and dried eels for the swamp villages until the Vlandian crown reassigned his fishing-rights to a southern viscount. Stayed in the reeds; the viscount's tax-clerks never came back twice."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_083", "Tomas Eel-Bone, traveler. The reeds let you in — that's the marsh's saying, not mine. Mine is: bring me {BP_VENDOR_QUEST_DESC}, and I'll dry you the kind of fish the southern viscount fenced me out of."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_062", "Marsh-eel takes the smoke different from river-fish, traveler — three days hanging in reed-smoke, not the half-day the southern fishermen rush. The flesh turns a colour they don't know how to name in Vlandia. They've stopped trying."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_063", "Tell me the size, the catch-week, the man it's for, traveler. I'll dry you a string the southern viscount's tax-clerks would have priced as 'wartime contraband.' Two denars on the reed, a sample for your pack tonight."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_064", "Wife went under to the marsh during the spring overflow — Brenwyn, of the reed-cutters. The marsh kept her; the marsh keeps everyone, eventually. I dry one extra string each season and leave it on the bank where she went under. Sometimes the next morning it's gone."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_065", "Old Lir keeps a fish-stall at the southern viscounty market — same reed-smoke trick, half the price. He's my wife's brother. Tell him Tomas still dries on the bank; he'll seat you in the back of the stall. Coin for his market-toll.")
        };
        private static readonly VendorProfile _marshGear = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_066", "Lean close, friend. Mud-Hand don't share this with every boot that comes squelching through the reeds, but you earned an ear-bend. There's a leather-buyer up in <span style=\"BandItPlus.Place\">Pen Cannoc</span> what's gone soft in the head — paying nine <span style=\"BandItPlus.Coin\">denars</span> a hide for cured deer when it ought to fetch five at most. Word from a smuggler what passed through three nights back is, the man's got a contract with some southern armorer and he's panicking. If you've got hides or know a hunter who does, that's where the gold's pooling this fortnight.\n\nNow here's the better bit. <span style=\"BandItPlus.Name\">Lord Caradoc</span>'s purse is light — light as a starveling's pot. His tax-man came through pale and apologizing, which means the levy's late and the garrison's eating salt-pork older'n the keep. Lords short on coin sell things cheap, see. Armor, harness, sometimes a horse if you catch the steward in his cups. And his castle road? Thin escort. Two riders, maybe three, and one of 'em half-drunk by midday. A merchant friend told me he hauled a wagon of billets straight through and didn't see a banner.\n\nThe steel itself's the trouble though. Northern caravans are bottle-necked at <span style=\"BandItPlus.Place\">Varnovapol</span> — some quarrel with the harbor-master, ships sitting fat in the bay. So billet-prices are creeping. If you're laying up war-gear, do it now before the marsh-merchants catch wind. Won't be more than a week before every smith from here to the coast is bidding double.\n\nAnd one last whisper — there's a glut of cheap leather coming out of <span style=\"BandItPlus.Place\">Sibir</span>, hides so thin you could read scripture through 'em. Don't buy any boots stamped with the lily mark this season. They'll rot before the first frost. Mud-Hand tells you true: out here everything rots eventually, but some things rot before they're sold."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_067", "You want to know why my boots last when others rot off the foot in a fortnight? It's the bark. Not oak — every fool uses oak. I use bog-myrtle and alder catkins, pounded into a paste and packed against the flesh side of the hide while it's still wet from the lime-pit. Three turns of the moon it sits in a covered jar buried in cool peat. The tannins go in slow, deep, and they bring the marsh-smell with them. Leeches won't touch a boot cured that way. Neither will the rot-fly maggots that get into a man's seams in <span style=\"BandItPlus.Place\">Pen Cannoc</span> garrison stores.\n\nThe second trick is the fat. Marsh-deer fat won't do alone — too soft, weeps out in the heat. I render it down with a half-measure of beeswax I trade off a hedge-priest near <span style=\"BandItPlus.Place\">Epicrotea</span>, and a thumb of pine-pitch for the bite. Worked warm into the grain with a smooth river-stone, pressed and pressed until the leather drinks no more. Then it goes by the fire — not in the flame, a hand's breadth back — and turns the colour of wet bracken. That's when you know it's sealed.\n\nMy grandfather showed me the bark-paste the day his own boots gave out crossing the Drowned Causeway. He sat on a tussock and laughed, said even his soles had decided to retire before he did. Pulled the rotted things off, walked home barefoot through three leagues of leech-water, and didn't take a sore. The hide on a man's feet, he told me, is the only hide that learns. Everything else you have to teach.\n\nLast thing — and I'll only say it once because I don't want to see it on every cobbler's bench from here to <span style=\"BandItPlus.Place\">Tyal</span> — the harness-stitching. I use sinew from the hind-leg, never the back, and I wax it with the same myrtle-and-fat mix instead of pitch. Doesn't show black against the leather. A horse-thief glancing at the harness sees a peasant rig, not the kind that holds a charging man in his seat. Cost you four hundred <span style=\"BandItPlus.Coin\">denars</span> the full set, and I'll throw in a spare bark-jar so you can patch it yourself when the rot finally tries."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_068", "Wax The Thread, Friend"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_069", "My father stitched harness for the militia at <span style=\"BandItPlus.Place\">Pen Cannoc</span> — clean shop, good awls, a window that faced the square. I learned the trade with my hands clean and my thread waxed proper. Then a tax-man with a writ I couldn't read took the shop for back-coin we never owed, and Father walked into the fen one morning and never walked back out. That was twenty winters past. The awls I carry now were his.\n\nI drifted south stitching what folk would pay for. Bridle-loops for a horse-thief outside <span style=\"BandItPlus.Place\">Quyaz</span>, boot-soles for a peat-cutter who paid me in salt-fish, a quiver for a girl who couldn't string her own bow. None of them asked where I learned my stitches and I stopped asking where they got their hides. A man with a curved knife and no questions eats more regular than a man with a clean ledger.\n\nThe marsh found me the way it finds everyone — slow, then all at once. I was sleeping under a fallen alder with a fever in me when the stalkers pulled me out by the collar. They had a stack of green deer-hides nobody knew how to cure and a captain whose boots had come apart at the welt. I fixed the boots. I cured the hides. I have been fixing things here ever since, and nobody has come looking for the tax owed on me.\n\nWhat pays a man into this trade, you ask. Hunger pays first. Then habit. Then the quiet knowing that a good seam outlasts the man who wore it, and the hide outlasts the seam, and the bog outlasts the hide. Everything rots out here, friend, but it rots SLOWER if you waxed your thread. That is the only honest sermon I have left in me.\n\nSo here I sit, cobbling marsh-deer into something that will keep your feet dry for a season, maybe two. Pay me in <span style=\"BandItPlus.Coin\">denars</span> if you have them, or in salt, or in a flask of something that burns. I don't ask where the coin came from. Nobody asked me, when I started taking it."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_070", "Word From The Bog-Road"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_071", "Word travels slow through the reeds, but it travels. Caravan out of <span style=\"BandItPlus.Place\">Pen Cannoc</span> dragged a wagon of Vlandian steel-stock through the fen-road last fortnight, axle-deep in mud and screaming about it. Driver swore he'd never come south of the bog again — meaning his master will pay double next season to find someone who will. I bought three bar-ends off him for sixty <span style=\"BandItPlus.Coin\">denars</span> and a dry pair of boots. Honest trade.\n\n<span style=\"BandItPlus.Name\">Lord Caradac</span> up at <span style=\"BandItPlus.Place\">Ocs Hall</span> is buying shields again. Third order this year. Either his levies keep losing them in the marsh or he's stockpiling for something the heralds aren't shouting yet. My cousin's boy works the tannery there — says the order is for round-shields, marsh-pattern, not the kite-shape the knights favor. Tells you who they expect to fight.\n\nSmiths are moving east. <span style=\"BandItPlus.Place\">Quyaz</span> is paying journeymen four <span style=\"BandItPlus.Coin\">dinars</span> a day to come work the desert forges, and two out of every three apprentices at <span style=\"BandItPlus.Place\">Pravend</span> have packed their hammers. Good for me — leather work stays here in the wet, where iron won't. Bad for any lord hoping to re-helm his guard before snowmelt.\n\nBattanian bowyer came through last week, name of <span style=\"BandItPlus.Name\">Eithne the Splinter</span>, hauling yew staves she'd cut north of <span style=\"BandItPlus.Place\">Pen Cannoc</span>. Said the deer up there are thinning, hunters pushing further into the highlands, harness wearing out faster than the cobblers can patch it. She left me a stave for the boots I made her. Fair trade is fair trade.\n\nLast thing — a saddler out of <span style=\"BandItPlus.Place\">Revyl</span> was murdered on the bog-road, throat opened, pack untouched. Untouched, mind. That's not a robber's work, that's a message. Whoever's sending it hasn't said to who. Watch your harness-straps, friend, and don't ride alone past the dead willow."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_072", "Cael Mud-Hand"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_073", "Hide-Cobbler"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_074", "Tans pelts the marsh leaves on its bank — adder-skin, fen-otter, drowned-deer. His leather doesn't rot in wet country; the fen people say he learned the trick from the marsh itself."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_084", "Cael Mud-Hand, traveler. The chief lets you walk — Mireborn's eye is good. Mine's narrower. Bring me {BP_VENDOR_QUEST_DESC} and we'll see whether your steel deserves leather the marsh hasn't claimed back yet."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_075", "Marsh hide tans different, traveler — you let the fen do the first work, three days under reed-water before the oak-bark. The leather doesn't rot in wet country. Vlandian tanners can't replicate it; they've stopped trying."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_076", "Bring me a beast you've taken yourself, traveler — adder, fen-otter, drowned-deer — and I'll cobble you a piece the marsh hasn't claimed back. Half the denar on the hide, the rest on the fit. A swatch for your pack tonight."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_077", "My boys learned the tan from me, traveler. The marsh took the youngest the year of the long flood — Bren, eight winters then. The middle one walked out to imperial recruiters at fourteen; I don't say his name now. The eldest's still here, somewhere in the reeds; I see his snare-marks on the deer."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_078", "Find Old Garrick at the Battanian forest-edge — he learned reed-water tanning from my father before the family split. Tell him Cael still works the fen; he'll show you the inner stretch-rack. Coin for the long road.")
        };

        // ===== HIGHWAYMEN (The Reeve's company) =====
        private static readonly VendorProfile _highwaymenFood = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_085", "Lean close, friend, and keep your voice low — I tally every grain twice but I tally rumors thrice, and what I'm about to spill is worth more than the salt in my pouch. Word from a Battanian drover three nights past: <span style=\"BandItPlus.Name\">Lord Caladog</span> has been paying his garrison in promises and stale bread for two whole weeks. His steward came through <span style=\"BandItPlus.Place\">Pen Cannoc</span> trying to buy two hundred bushels of barley on credit, and the miller laughed him out of the yard. A man who can't feed his own walls won't be marching anywhere soon — and his caravans up the western fork are riding with four guards where they used to ride with twelve.\n\nNow here's the morsel I've been chewing on. The smokehouse at <span style=\"BandItPlus.Place\">Marunath</span> burned to the studs a fortnight back — lightning, they say, but I've heard whispers it was a jealous cousin with a torch. Either way, smoked ham is scarce from the Hercotid all the way to the Bartin, and there's a Vlandian quartermaster in <span style=\"BandItPlus.Place\">Galend</span> paying <span style=\"BandItPlus.Coin\">forty-two denars</span> a side when the going rate's twenty-eight. Run a string of pack-mules up that road and you'll come back with your saddlebags clinking. Just don't take the river road — the bridge-toll man's gone greedy and his cousins in the reeds are greedier still.\n\nAnd the salt — gods, the salt. The Aserai caravans coming up from <span style=\"BandItPlus.Place\">Husn Fulq</span> have been thin all spring because the southern pans are flooded, so the brine boilers at <span style=\"BandItPlus.Place\">Sanala</span> are charging double and the inland towns are screaming. I had a Sturgian cheese-monger sit on that crate yonder and weep into his beer — said he'd pay <span style=\"BandItPlus.Coin\">eighteen dinars</span> a sack to anyone who could get him three. So if you happen across a wagon that smells of brine and looks lightly guarded, well. I'm not telling you what to do. I'm just saying the man weeps real tears and his purse is real heavy.\n\nOne last thing, and then I'll let you go. <span style=\"BandItPlus.Name\">Lord Rhagaea</span>'s grain reserves at <span style=\"BandItPlus.Place\">Pravend</span> are bigger than she's letting on — I had a granary-boy through here last week who'd skimmed off the count-books before he ran, and the empire's sitting on enough wheat to feed an army twice over. Means prices in the south are going to crash by harvest, and any sack of flour you're holding past midsummer will be worth half what it is today. Sell early, sell hot, and don't tell anyone where you heard it. Roger Tally-Sack counts twice, but he only whispers once."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_086", "You want my secret? Lean close, friend, and keep your voice low — this one cost me three winters to perfect. It's the double-tally brine, and no other quarter-master on the road keeps it. I take coarse rock-salt from the <span style=\"BandItPlus.Place\">Sargot</span> pans — never the sea-salt, too bitter — and I measure it twice: once by weight, once by handfuls. Three handfuls to the pound, then I weigh again to be sure no clerk's thumb tipped the scale. Into the brine goes crushed juniper, two cloves of wild garlic per gallon, and one spoon of honey for every five of salt. The honey is the trick — it draws the salt deeper into the meat without souring the cure.\n\nThe meat itself — pork shoulder, venison haunch, whatever the boys drag in — gets pricked all over with a darning needle before it goes in the crock. Twenty-four punctures, I count them, every time. Then it sits eleven days in the cold cellar, turned every dawn and every dusk. Not ten days, not twelve — eleven. I learned that from an old curing-woman near <span style=\"BandItPlus.Place\">Galend</span> who used to supply <span style=\"BandItPlus.Name\">Lord Derthert's</span> own larder before the war scattered her village. She said ten leaves the centre raw, twelve turns the edges to leather.\n\nAfter the brine, I smoke it cold over apple-wood and a single handful of dried thyme. Cold smoke, mind — never hot. A hot smoke cooks the meat and locks the salt where it landed; a cold smoke lets the flavour breathe through the whole cut. Three days in the smokehouse, then a fortnight hanging in the rafters wrapped in linen. The boys think I'm mad when I make them wait that long, but I've sold a single cured ham to a passing caravan-master for forty <span style=\"BandItPlus.Coin\">denars</span>, and he came back six months later asking for two more.\n\nMy grandfather taught me to count grain in the Vlandian granaries, but it was my old aunt who taught me the brine, on the morning my mother died of fever. She said: \"Roger, the dead we cannot save, but the meat we can — and a man who feeds the living honours both.\" I tally every grain twice because she taught me grief makes a man careless, and a careless quarter-master starves his own brothers. Don't pass that secret to the next traveller through. It's yours now."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_087", "A Clerk's Long Road Down"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_088", "Twice. Every sack, every measure, every fist of grain — twice. That is the only honest thing a man can do with another man's stores, and I learned it at a counting-desk in <span style=\"BandItPlus.Place\">Pravend</span> before I learned anything about this road. My father was clerk to a wool-factor, his father before him, and by the time I had whiskers I could tally a season's fleeces faster than the scribe could wet his quill. I thought I would die at that desk with ink on my cuffs and a pension of forty <span style=\"BandItPlus.Coin\">denars</span> a year. Gods laugh at clerks who plan.\n\nIt was a grain ledger that finished me. Lord <span style=\"BandItPlus.Name\">Derthert</span>'s steward wanted three hundred measures hidden from the tithe-men, and my master signed his name to the lie. When the crown's auditor came, the master pointed at the junior clerk — me — and the rope was already being measured. I went out the cellar window with a satchel of dried apples and the ledger itself, because a man with proof of a lord's theft has either a long life or a short one, and I meant to pick which. I sold the ledger to a smuggler outside <span style=\"BandItPlus.Place\">Galend</span> for twelve <span style=\"BandItPlus.Coin\">denars</span> and a head start.\n\nThe road teaches you faster than any abacus. I ran salt out of the Mire for a winter, drove dates up from the south for a season, and lost two fingers to a frostbite that taught me to respect a smokehouse the way townsmen respect a chapel. I came to this camp three winters back with a broken cart and four barrels of eels nobody else would buy. The boss tasted one, grunted, and pointed at the storehouse. I have been counting it ever since.\n\nNow I keep the larders the way I kept my master's books — twice, and honest within the four walls of this stockade. Grain in the dry crocks, smoked meat hung above the hearth-stones, hard bread for the long rides, salt-pork for the rougher work. The lads bring in what the road provides; I weigh it, mark it, and feed them out of it. They grumble that I shave the loaves thin. They are correct. A camp that eats fat in autumn starves in spring, and I have buried enough men to know the difference.\n\nSo that is what pays a man into this trade — a steward's lie, a window in a cellar, and a learned dread of empty crocks. No credit, friend. No promises. Coin or grain, weighed in front of you, written down twice. It is the only kindness an honest quarter-master can offer."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_089", "Tallies From The Tollway"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_090", "The word, you say. Sit then, but don't lean on the salt-sack — I've counted it twice and I'll count it a third before sundown. The road's been chattering, and a clerk's ear never stops, even when the clerk's wearing road-leather instead of guild-grey.\n\n<span style=\"BandItPlus.Place\">Pravend</span> is starving for grain — not loud-starving, the quiet kind, where the granary-master smiles and quotes you sixty <span style=\"BandItPlus.Coin\">denars</span> the bushel and pretends his ledger isn't shaking. Word from a peddler who came through at dawn: <span style=\"BandItPlus.Name\">Lord Aldric of Galend</span> paid out of his own purse to refill the castle bins after the spring rains rotted half the stores. Any sack we can spare west goes for double what it fetches here. I've already set aside four for the next runner.\n\nThe salt road south is the prize, though. <span style=\"BandItPlus.Place\">Jaculan</span> caravans are moving sweetwine and dates up the coast — the Aserai pay fair coin for hard cheese and smoked river-eel, and they'll trade barrel-for-barrel if your wine-keeper knows how to haggle. Don't send a fool. They count grains the way I count grains, and they smile while they do it.\n\nFamine word from the north: <span style=\"BandItPlus.Place\">Revyl</span> lost two villages' worth of barley to a Sturgian frost that came a fortnight late. By midsummer their hearth-bread will be half sawdust and the garrison will be buying anything that doesn't crawl. If you're riding that way, take dried meat — not grain, the grain'll spoil before you cross the passes. Take meat and take twice what you think you need.\n\nLast bit, and mark it: a Vlandian merchant train out of <span style=\"BandItPlus.Place\">Pen Cannoc</span> is moving south next week with sixteen wagons of smokehouse stock — bacon, hard sausage, the good stuff. <span style=\"BandItPlus.Name\">Tomas the Hook</span> on the eastern road heard it from a guard who drinks too much. I'm not telling you to do anything about it. I'm telling you the wagons exist, and that the camp's larder is light. Coin or grain — those are the prices. The rest is the road's business."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_091", "Roger Tally-Sack"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_092", "Quarter-Master"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_093", "A Vlandian quartermaster's clerk who learned to skim until the audit caught him. The Reeve hired him the morning his sentence was read; the company's larder has been twice as full ever since."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_094", "Roger Tally-Sack — the Reeve's columns include me, two pages back. Welcome to my line of the ledger, traveler. The chief's good for letting you walk; I'm not. Bring me {BP_VENDOR_QUEST_DESC} and I'll record you as 'paid in full' — that's how the company books work."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_095", "Quartermaster's trick, traveler — the column eats off the third pannier first, the spoils off the first. Fresh on the bottom, cleared on the top. Vlandian audit-clerks never knew which row to inspect. Still don't. The Reeve eats well because of it."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_096", "Name a banquet, traveler — wedding feast, victory dinner, governor's welcome. Six denars on my ledger and the next pass through, I'll have it packed and stamped 'requisitioned.' A sample on the line tonight, no charge."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_097", "Wife stayed in Pravend when the audit caught me. Two boys — they'd be journeymen now, if Vlandian guilds still seat audit-men's sons. I send a portion of my book each season through a mendicant friar; he tells me they got it once. Not twice. The ledger keeps the rest."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_098", "Magister Bardolph keeps the wine-list at the Galician staging-house — same crooked column-trick I taught him in the audit-office. Tell him Roger's still got the third-pannier rule running; he'll uncork the Vlandian red. Coin for his discretion.")
        };
        private static readonly VendorProfile _highwaymenGear = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_099", "Lean in, friend, and keep your voice low. A muleteer came through three nights past with a tongue loose from too much sour wine, and he let slip that <span style=\"BandItPlus.Name\">Lord Caelin of the Hearth-Vale</span> has been paying his garrison in promises and stale bread for near two months. His treasury's hollow as a rotted log. Now why does that matter to a strap-cutter like me? Because a lord short on <span style=\"BandItPlus.Coin\">denars</span> sells off his armory in quiet lots, and quiet lots mean buckle-fittings and harness-rings going cheap to anyone with a wagon and no questions. Watch the back gates of <span style=\"BandItPlus.Place\">Ortongard</span> at dusk on market-days. You didn't hear it from me.\n\nThe Iron Road south of <span style=\"BandItPlus.Place\">Varnovapol</span> has gone soft, too. Used to be three patrols a day, sometimes a knight's banner riding with them. Now? One patrol at sunrise and a pair of drunk levies after. Two steel-billet caravans rolled through last week with nothing but a hired guard apiece — and one of those guards was a boy of fifteen with a borrowed spear. The chief's already eyeing the third run. If you've a mind for honest work, the gang could use a sword on that road; if you've a mind for dishonest work, well, the prices we'll be charging on cut billets next month will tell you everything.\n\nHere's the real gift, though, the one I'd not tell a stranger. There's a fool of a merchant in <span style=\"BandItPlus.Place\">Sanala</span> — fat fellow, smells of clove — who's paying near triple market rate for tanned ox-hide because his contract with the southern saddlers is due and his usual supplier got pinched at a ford. He's burning through <span style=\"BandItPlus.Coin\">denars</span> like a man with a sister to marry off. I've a stack of forty hides in the back cellar, lifted off a Battanian wagon two moons ago. You ride them to him with a straight face and a half-believable story, I take seven parts in ten, you take three. Quill says yes or no by sundown — the gossip won't keep, and neither will the hides."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_100", "Pull up that stool. Aye, you've earned a sit-down — most who ask my craft get the lecture about oak-bark tannin and bee-grease, but you've ridden with us once now, so I'll tell you the real of it. The secret isn't in the leather. It's in WHERE on the strap you cut. Every caravan saddle has a sweet band — three fingers wide, running just behind the cantle skirt — where the rider's weight has worked the fibers a thousand leagues without ever soaking sweat through. That band, that's gold. The rest is rind.\n\nMost strap-cutters slice lengthwise down the whole skirt and wonder why their reins snap in the cold. I cut ACROSS the grain at a twelve-degree slant, follow the worked band edge-to-edge, and I get four reins from one skirt where a greedy man gets two cracked ones. Then I rub them — and listen close, this part I learned from an old harness-Jew in <span style=\"BandItPlus.Place\">Amitatys</span> the winter I nearly lost my fingers — I rub them with rendered horse-marrow mixed one-to-three with pine pitch warmed over ember, not flame. Flame ruins the pitch. Ember keeps it sticky. Strap drinks it slow over two nights wrapped in oilcloth.\n\nThe trick after that is the salt-cure. Aye, salt — on leather. Sounds mad. A pinch of grey rock-salt worked into the flesh side BEFORE the marrow goes on draws the last caravan-sweat out and leaves the strap supple in summer and unbrittled in frost. Most tanners would call me a liar. Let 'em. My straps don't snap when a man's hanging off a galloping horse, and theirs do. That's the only proof that matters out here. Two hundred <span style=\"BandItPlus.Coin\">denars</span> a set, and I sleep easy knowing they hold.\n\nMy grandfather kept ledgers same as I do — he was a tax-clerk for some forgotten count, scratched his quill till his fingers bent. The day they hanged him for skimming, he passed me his knife and said the only honest trade is the one you can weigh on a scale. I weigh every strap before it leaves this stall. You ever bring me a saddle off some lord's caravan, I'll cut you the sweet band and pay fair for the rest. That's between us."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_101", "A Clerk's Hands, A Cutter's Knife"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_102", "Strap or buckle, you asked, and that's the whole of my trade — but you want the long road that brought me to it. Sit a moment. I was a clerk's apprentice in <span style=\"BandItPlus.Place\">Pravend</span>, scratching tallies for a saddler who supplied half the city's caravan-yards. My quill ran sharper than his awl, and he resented me for it. When his books showed forty <span style=\"BandItPlus.Coin\">denars</span> short he blamed the lettered boy, not the wine he drank with the tax-man.\n\nThey drove me out in winter with ink-stained hands and no trade-mark to my name. I worked a tannery in <span style=\"BandItPlus.Place\">Galend</span> until the lye-pits ate the skin off my fingers — that's where I learned hide from rind, kid from cow, strap-grain from belly-cut. A wagon-master named <span style=\"BandItPlus.Name\">Halmar of the Long Reach</span> took me on as his strap-mender, and for two seasons I rode his caravans south, sewing harness by lantern-light while his outriders watched the treelines.\n\nThen the boys hit us. Six of them on the <span style=\"BandItPlus.Place\">Pravend</span>-to-<span style=\"BandItPlus.Place\">Quyaz</span> road, and they knew their work. They took the oxen, the bolts of cloth, the strongbox, and Halmar's throat. I sat in the wreckage waiting for a knife and instead got a question — could I cut a saddle off a dead horse without ruining the tree. I could. I did. I cut nine that afternoon while the crows watched, and the chief said come along, scribbler, we've need of a man who knows leather from lining.\n\nNow I sit in this camp with my thick ledger and my curved knife, and every caravan the lads bring in pays me twice. First in straps — I cut them clean from the saddle-skirts before the hides go stiff, sort them by width, oil them, hang them on the rack you're standing by. Second in tally — I write down what I keep and what I sell, because a man who doesn't count his stock gets robbed by his own pockets. The chief gets his cut in <span style=\"BandItPlus.Coin\">denars</span>, the boys get rebuckled before the next ride, and I get a roof that doesn't smell of lye.\n\nSo that's what pays a man into this trade — a lying saddler, a lye-pit, and a dead wagon-master who taught me to keep my stitches tight. Strap or buckle, friend. Pick one. The ledger waits."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_103", "Strap, Buckle, And Ledger"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_104", "The word, you say. Word's cheap, but I keep mine in ink — flip to whatever page suits you. The big one: a steel-stock train rolled out of <span style=\"BandItPlus.Place\">Pravend</span> bound for the southern garrisons, twenty mules deep, and the lead driver's been drinking too loud about which fords they cross. Boys took a peek at the route last market-day. If the gang rides on that one, I'll be cutting straps for a fortnight straight and sleeping on a mattress of new buckles.\n\n<span style=\"BandItPlus.Name\">Lord Caladog</span> paid one hundred fresh <span style=\"BandItPlus.Coin\">denars</span> a piece for round shields in <span style=\"BandItPlus.Place\">Pen Cannoc</span> — bossed iron, ash-plank, the works. Means every smith from there to the coast is hammering shield-rims and ignoring the small commissions. Saddle-leather's piling up untanned because the tanners can't get the smiths to barter for the lime-pits anymore. Glut's coming. Prices'll drop. Buy your strapping now or pay me twice in a month.\n\nCaravan out of <span style=\"BandItPlus.Place\">Quyaz</span> is moving bow-stave yew, the good seasoned stuff, and they're stupid enough to take the river road. Two guards, one drunk wagoner, a merchant who thinks his ledger-name buys him safe passage. I've already promised <span style=\"BandItPlus.Name\">Old Hella</span> at the bowyer-bench in the back tent her pick of the first ten staves. Don't tell her I told you — she charges me double when she knows I'm waiting.\n\nHeard a Vlandian armorer up in <span style=\"BandItPlus.Place\">Revyl</span> is recruiting — paying ninety <span style=\"BandItPlus.Coin\">denars</span> a season for any journeyman who can pattern-weld. Half the forge-rats from here to the Battanian border are walking that road right now, hammers slung on their backs. Means the country smithies between here and there are short-handed. Lord's spare lance-points, broken vambraces, dented helms — nobody's repairing them. They sell cheap, by weight. If a caravan moves scrap south, that's our scrap now.\n\nLast bit, and then you state your need or move on. Word from the eastern ridges is a relief column's coming through with new-forged kite shields — Imperial pattern, leather facing, the lot. I'll want the leather more than the wood. You see boys riding that direction, tell <span style=\"BandItPlus.Name\">Branoc</span> to cut the facings clean off and leave the planks. Straps, buckles, facings. The rest is firewood."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_105", "Edmund Grease-Quill"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_106", "Strap-Master"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_107", "Bookbinder by trade, harness-maker by necessity. Stitches a saddle the same way he used to stitch a ledger — straight, flat, and uncomplaining. The Reeve pays him in book-paper, which Edmund hoards."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_108", "Edmund Grease-Quill, harness-maker. The Reeve's accounting passes you in; my stitching does not. Bring me {BP_VENDOR_QUEST_DESC} and the saddle I make will outlast three of your horses — and the company will note the entry."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_109", "A bookbinder's stitch lays flat, traveler — flat stitch, knot at every fourth point, waxed not greased. The Reeve's columns stay where I sew them. Imperial saddlers cross-stitch and call it strength; the cross opens at the gallop."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_110", "Bring me your saddle, your draw-weight, your gallop-distance, traveler. I'll bind you a tack that survives three of your horses. Three denars on the wax, two on the time. Here, a wax-string to mend your current rein."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_111", "Daughter apprenticed to a Pravend bookbinder; never wrote back after I joined the Reeve's column. Three years, no letter. I bind a blank book every winter and send it to the master's house — Magister Halver, third-floor shop. He doesn't return them. I take that to mean she opens one."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_112", "Halver of the Pravend Book-Quarter rebinds for the Vlandian magistrates and keeps a stitch-room for the Reeve's company. Tell him Edmund still sews flat; he'll show you the lower shelf. Coin for the door-clerk.")
        };

        // ===== SLAVER CARAVANS (Khalid the Chain) =====
        private static readonly VendorProfile _slaverFood = new VendorProfile {
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_113", "Salt Keeps Longer Than Coin"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_114", "My father drove dates from <span style=\"BandItPlus.Place\">Quyaz</span> to <span style=\"BandItPlus.Place\">Iqbayl</span> when the southern road was still safe, and he taught me to read a well by the scum on its rope before he taught me my letters. We were honest grain-haulers then — sacks weighed twice, salt measured in flat palms, no man's child rode in the wagon-back. Then a tax-farmer of <span style=\"BandItPlus.Name\">Lord Unqid</span> took our caravan for a debt that wasn't ours and left my father in a ditch outside <span style=\"BandItPlus.Place\">Husn Fulq</span> with his throat opened over forty <span style=\"BandItPlus.Coin\">dinars</span>.\n\nI walked the dunes alone for a season, eating lizard and chewing acacia gum, and I learned which wells run sweet and which run salt the way a beaten dog learns doorways. A slaver-train found me at the cistern below the Black Crag — they had bread, I had the map in my head, and we struck a bargain that didn't need writing. I cook for them now because the desert killed the man who wouldn't, and the man who would is still breathing.\n\nDon't mistake me — I'm no whip-hand. I keep the camp fed. I know where the date-palms near <span style=\"BandItPlus.Place\">Razih</span> still bear in a dry year, which Aserai widow at <span style=\"BandItPlus.Place\">Durrin</span> sells smoke-cured goat under the table, which spring north of <span style=\"BandItPlus.Place\">Onica</span> tastes of iron but won't kill a horse. The captains pay me in <span style=\"BandItPlus.Coin\">dinars</span> and salt, and salt keeps longer than coin out here.\n\nThe chained ones get the same flatbread I eat, same dates, same brackish tea. That's not kindness — a thirsty man fetches a poor price at <span style=\"BandItPlus.Place\">Quyaz</span>, and a starved one fetches none. I told myself that the first year. I tell myself other things now.\n\nYou want bread? Sit by the fire-pit and don't haggle. Sand teaches a man what loaves are worth, and I've been taught hard."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_115", "Salt, Grain, And Sweetwine"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_116", "The word on the road? Sit. Eat a date first — you look like a man who's been chewing dust since <span style=\"BandItPlus.Place\">Quyaz</span>. The southern wells are running salt this season, all of them past the third dune-line. Caravans pushing for <span style=\"BandItPlus.Place\">Iqbayl</span> are paying double for sweetwater skins, and a clever cook can buy a barrel of brine in Quyaz for a copper and sell the same brine as salt-cure in <span style=\"BandItPlus.Place\">Husn Fulq</span> for forty <span style=\"BandItPlus.Coin\">dinars</span>. Salt is the new gold, friend. Always was, but folks forget between droughts.\n\nGrain's the other half of the story. <span style=\"BandItPlus.Name\">Emir Unqid</span>'s steward came through last moon buying every sack of millet from here to the coast — the garrisons at <span style=\"BandItPlus.Place\">Durrhd</span> are stockpiling, which means he's expecting a siege or a famine, and a steward like me doesn't much care which. I sold him eighteen sacks at three times market and he kissed my hand for it. That's what fear does to a price.\n\nThe sweetwine caravans out of <span style=\"BandItPlus.Place\">Husn Fulq</span> are running thin this year — the date harvest came in light, and the vintners are watering the press. Anyone selling you Husn red for under sixty <span style=\"BandItPlus.Coin\">dinars</span> a jug is selling you vinegar with a story. The Vlandian merchants up north don't know the difference yet, so a sharp tongue can still turn a profit moving \"vintage\" jugs to <span style=\"BandItPlus.Place\">Pen Cannoc</span>. Don't tell them I said so.\n\nDried meat's moving slow but steady. The smokehouses at <span style=\"BandItPlus.Place\">Quyaz</span> are buying lamb-shoulder by the wagon, paying in Aserai script that's actually worth something for once. And there's a famine sniffing around the Khuzait steppe — <span style=\"BandItPlus.Name\">Monchug</span>'s herds took a winter-cull, and any caravan willing to push grain east through the passes will come home with a saddlebag of <span style=\"BandItPlus.Coin\">denars</span> and a story about wolves. I won't go myself. I've buried two cousins in those passes.\n\nLast thing, and listen close — <span style=\"BandItPlus.Name\">Jala the Spice-Wife</span> at the <span style=\"BandItPlus.Place\">Pravend</span> bazaar is buying cardamom and dates at any price, paying upfront. Either she's stockpiling for a wedding feast or she knows something the rest of us don't. Me, I'm packing a cart for her next week. A steward eats by reading other people's hunger, and hers is loud."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_117", "Tariq Date-Tongue"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_118", "Caravan-Steward"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_119", "Once supplied imperial banquets in Quyaz; was caught skimming the dried-fruit stocks and sold his way out by joining Khalid's chain. Wears the same brass anklet the slaves do — by choice, he says."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_120", "Tariq Date-Tongue. Khalid's chain is thin around your wrists, traveler — that's a privilege. My larder isn't. Bring me {BP_VENDOR_QUEST_DESC} and I'll feed you the dates I used to feed the imperial governor of Quyaz before they caught me."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_121", "Imperial banquet dates aren't dried, traveler — they're sun-cured under a cotton tent, four days per layer, three layers per crate. The skin keeps the sugar tight; the flesh doesn't turn. Quyaz tax-stewards used to inspect every crate. Now they don't ask."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_122", "Bring me a feast-night and three denars, traveler. I'll cure you a crate the imperial governor's table would have demanded by name. Sample in the bowl for your road-ration. The anklet's just metal — the trade's the real chain."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_123", "Wife and son sold off ahead of me — Layla and Hamzah. Khalid's chain holds them too, in another caravan, three days east. I send word through the chain-clerks every new moon. Some moons it gets through. Most don't. The anklet's a choice because the choice is what I have left."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_124", "Salim Pomegranate-Hand keeps a date-stall in Quyaz under the date-merchants' guild seal — Khalid's brother by chain, not blood. Tell him Tariq's still under the tent; he'll seat you near the chilled-water jug. Coin for the toll-clerk.")
        };
        private static readonly VendorProfile _slaverGear = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_125", "Sit. Drink. You want news, you came to the right anvil — every chain I forge gets carried somewhere, and the men who carry them talk. A driver from the <span style=\"BandItPlus.Place\">Battanian downs</span> told me three days back that <span style=\"BandItPlus.Name\">Lord Caradros</span> is short — really short. He pawned a saddle for thirty <span style=\"BandItPlus.Coin\">denars</span> at a wayside post, and a man who pawns saddles is a man who can't pay his garrison. His patrols on the south road have thinned to four spears. Four. You could roll a salt-wagon through that gap with a blindfold on.\n\nSpeaking of salt — the <span style=\"BandItPlus.Place\">Vlandian coast road</span> is choked. Three smokehouses in <span style=\"BandItPlus.Place\">Sargot</span> burned in the spring rains and never rebuilt, so the brine-fish pile up unsmoked and the inland markets are screaming. A grain factor named <span style=\"BandItPlus.Name\">Tobias of Praven</span> is paying eighty <span style=\"BandItPlus.Coin\">denars</span> a barrel — eighty, for fish that used to move at twelve. Whoever runs salt out of <span style=\"BandItPlus.Place\">Ortongard</span> next month writes their own price. The mule-drivers know it. The mule-drivers always know it first.\n\nFor my own trade — iron's tight. The Sturgian billet-caravans got hit twice on the <span style=\"BandItPlus.Place\">Varcheg pass</span> and the third one turned back at the snowline rather than chance a third. Steel's gone to a hundred and ten <span style=\"BandItPlus.Coin\">denars</span> the bar and climbing. But leather — gods, leather is drowning. The Khuzait herds had a good cull and the tanners in <span style=\"BandItPlus.Place\">Makeb</span> are sitting on stacks they can't move. <span style=\"BandItPlus.Name\">Old Marrec</span> the saddler told me he's selling cured hide at forty <span style=\"BandItPlus.Coin\">denars</span> the bundle, half what it cost him. A man with a cart and a nose for routes could buy low in Makeb and sell high anywhere west of the <span style=\"BandItPlus.Place\">Sanala river</span>.\n\nThat's the shape of it this month. I don't ask what you carry, and you don't ask what my chains hold. But if you ride the south road past Caradros's thin patrols, with leather under the tarp and a route toward Tobias's eighty-denar barrels — well. A smith hears things. A smith forgets things too, for the right price."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_126", "There is a trick to the cuff that the <span style=\"BandItPlus.Place\">Aserai</span> smiths up the coast will not teach you, and the Imperial guildsmen would call heresy if they ever set foot in my shed. You do not forge the iron hot and bend it cold like a horseshoe. You quench the half-finished hoop in old goat's-milk whey — week-soured, skimmed of the fat, kept in a clay jar buried under the floor where the desert sun cannot find it. The whey eats into the skin of the iron and leaves a thin grey crust that looks like nothing. But that crust is the whole secret. It will not hold rust for a full season of caravan sweat, and a man chained in it cannot fray it through with patient rubbing the way he can a clean-forged link. I learned it from my master in <span style=\"BandItPlus.Place\">Quyaz</span> when I was nine years old and too small to swing the heavy hammer.\n\nThe yokes are simpler but the geometry is mine. Most smiths cut the neck-curve to a circle because a compass draws a circle and an apprentice can copy a compass. I cut mine to an oval, slightly flattened where the throat sits, deeper where the collarbones ride. It does not choke a man when the cart jolts, which means he arrives in <span style=\"BandItPlus.Place\">Razih</span> walking and not coughing blood, which means <span style=\"BandItPlus.Name\">Hakim al-Sarrad</span> pays the full eighty <span style=\"BandItPlus.Coin\">denars</span> per head instead of forty for a half-dead one. The slavers do not know why my yokes fetch a better price at the block. They think it is the polish. Let them think so.\n\nThe leather for the wrist-cinches I cure myself in the sumac pit behind the forge, sixteen days, turned every dawn. Cheaper hands use oak-bark from the north and the cinches go stiff in a month of sea-spray. Mine flex for a year. A flexing cinch chafes a wrist raw, you understand, where a stiff one only bruises. Raw means infection, infection means a dead chattel, a dead chattel means nobody buys from the man who delivered him. So my customers come back to me, and I do not ask them where they go next, and they do not ask me why a man who works iron lives in a tent and not a stone house.\n\nMy master in <span style=\"BandItPlus.Place\">Quyaz</span> wore a cuff of his own forging for the last twelve years of his life. He told me once, while we were drinking palm-wine and he thought I was too young to remember, that he had hammered the lock himself when he was thirteen, and that the key had been lost in a sandstorm before he ever turned twenty. I asked him why he did not break it off. He said the iron was too good. I make my iron the same way he taught me. I do not wear any of it. That is the only difference between us, and some nights I am not sure it is enough of one."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_127", "Iron Asks No Questions"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_128", "My father kept a forge under the south wall of Quyaz, and he taught me that iron has only two honest answers: it holds, or it breaks. He sold nails to roofers and hinges to the caravanserai and a good edge to any man who came with <span style=\"BandItPlus.Coin\">dinars</span> warm in his fist. When the plague-summer came he broke before the iron did, and I buried him in a shroud I had to barter a pair of shears for.\n\nI tried to keep the shop. I tried, by every god a smith knows. But a boy of seventeen with a dead master's anvil is a creditor's feast, and within a season <span style=\"BandItPlus.Name\">Lord Sayyid al-Ghassan</span> owned the deed and the bellows and the rights to the well behind it. I walked east with nothing but the small hammer and the apron my father wore the day he taught me to draw a point.\n\nI forged for caravans after that — proper ones, with bolts of silk and bricks of salt — out of <span style=\"BandItPlus.Place\">Quyaz</span> down through the dunes toward <span style=\"BandItPlus.Place\">Iqbayl</span>. A wheel ring here, a re-bitted axle there. The pay was thin and the road was thinner. One winter a buyer met me at a waystation and asked if I could shape collars instead of cart-rings. He paid in <span style=\"BandItPlus.Coin\">dinars</span> stacked, not counted. I have not asked his name since, and he has not offered it.\n\nSo now I bend the bar and I rivet the link and I temper the pin so it will not shear when a man pulls against it. The camp eats because of my work. The camp moves because of my work. What the work carries when it leaves my anvil is between the buyer and whatever god still listens to him. I work iron. I do not judge what iron does.\n\nIf you have come for a blade or a buckle or a length of chain measured by the cubit, I will sell you honest goods at an honest weight. If you have come to ask me a harder question than that, friend, you have mistaken the smith for the priest, and there is no priest in this camp."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_129", "Word From The Anvils"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_130", "The road tells me what hands need iron, and right now half the south is reaching. A caravan out of <span style=\"BandItPlus.Place\">Quyaz</span> moved through last quarter-moon hauling pig-iron stock under salt-sacks — three wagons deep, axles groaning. The drover would not name his buyer, but the seal on his writ was Aserai script burned into oak. Steel-stock that heavy does not travel for plough-shares.\n\n<span style=\"BandItPlus.Name\">Emir Tulga al-Hizar</span> is paying three hundred <span style=\"BandItPlus.Coin\">dinars</span> a head for any smith who can hammer a curved blade without folding it twice. His fortress walls south of <span style=\"BandItPlus.Place\">Quyaz</span> are short of men since the last siege, and he has more recruits than scabbards. I had the offer myself. I work for the camp. I do not work for emirs.\n\nThe yoke-makers in <span style=\"BandItPlus.Place\">Pen Cannoc</span> have raised their price on hardwood blanks — twice what they asked last winter. That tells me someone north is buying more yokes than oxen, which means the yokes are for other necks. I do not ask whose. I only note the rope-chandlers there have raised theirs to match.\n\nWord from a Vlandian tinker who passed through three nights back — <span style=\"BandItPlus.Name\">Lord Rainard de Bonchamps</span> commissioned four hundred shields in pale-pine and rawhide, paid up front in silver. Pale-pine splinters bad on a real swing, so those shields are for parade or for arming men who will not live to swing them twice. Either way, the lumber-haulers between <span style=\"BandItPlus.Place\">Pravend</span> and <span style=\"BandItPlus.Place\">Jaculan</span> are running double-shift.\n\nLast bit, and the one worth the most to anyone passing through: there is a Battanian forge-master gone missing off the road from <span style=\"BandItPlus.Place\">Marunath</span>. Skilled hand, knew pattern-welding. Two parties are hunting him — one says to ransom him home, the other does not say. Smiths who travel alone these months are a kind of currency. I keep my hammer in sight and my mouth on the iron."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_131", "Yusuf Iron-Tongue"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_132", "Coin-Smith"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_133", "Forges shackles for Khalid and good steel for those who can pay extra. His prices reflect both lines of work; nobody complains, because the shackles are an option too."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_134", "Yusuf Iron-Tongue. Khalid sells the chains; I forge them. Sometimes I forge other things, for those who can pay the second price. Bring me {BP_VENDOR_QUEST_DESC} and we'll see which side of my anvil you walk away from."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_135", "Imperial smiths quench in oil — fast, clean, sells well at the inspections. Shackle-iron quenches in brine three breaths longer than free-iron. The brine bites the grain; that's why a shackle holds where a sword would shatter. Same metal. Different soak."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_136", "Tell me what you want made, traveler, and which side of my anvil you stand on. Six denars on the bar, three on the heat. A token from the spare-stock for your belt — that's the side I'd rather you stood on."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_137", "Two daughters. One's a slaver's wife in Quyaz, by choice she says, and I take her word for it. The other ran north at fifteen — the Sturgian wolves took her in, last I heard. I forge her a knife each winter from the brine-batch. I don't send them. She knows where the forge is."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_138", "Find Old Ibrahim at the Razih smithy — chain-forge by trade, free-forge by lamp. He's my cousin twice over. Tell him Yusuf still brines three breaths longer; he'll show you the back-anvil. Coin for the desert crossing.")
        };

        // ===== FALLEN LEGIONARIES (Aurelius's cohort) =====
        private static readonly VendorProfile _legionFood = new VendorProfile {
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_139", "Twenty Years At The Salt"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_140", "Twenty years I ran the cohort's rations. Twenty winters of counting loaves at dawn, weighing the salt, tasting the brine before a single legionary touched his portion. They called me Plinius the Tight-Fist because I'd dock a man a heel of bread for a missing strap, but every soldier under my count went into battle fed, and that is a debt no Senate ever paid me back for.\n\nI served under the Eagle when the cohort drew its bread from <span style=\"BandItPlus.Place\">Lycaron</span> and our salt came up the road from the southern pans in oxcarts I had to sign for in triplicate. I knew the weight of a grain-sack by sight, the smell of bad smoke in a ham, the precise number of dried eels that made a marching ration for forty men. When discharge came they gave me a copper plaque, a handshake, and seventy-two <span style=\"BandItPlus.Coin\">denars</span> for two decades of standing between hungry soldiers and starvation.\n\nSeventy-two denars buys you a winter in <span style=\"BandItPlus.Place\">Pravend</span> if you eat once a day and sleep on stone. I sold the plaque for soup. I tried hiring on with a grain factor — he laughed and said an old quartermaster knows too much about skimming to trust around a granary. The temples wouldn't have me. The legion forgets you the day the eagle stops needing your count.\n\nSo when the cohort that wasn't a cohort anymore came down out of the hills and asked who could keep a smokehouse running, I raised my hand before the question finished. These men were oath-broken, some of them deserters I'd have flogged in another life, but they understood ration discipline the way no caravan-master ever will. <span style=\"BandItPlus.Name\">The Old Tribune</span> told me to count what I counted before, and answer to him instead of Rome. The bread is the same shape. The salt is the same weight.\n\nI don't ask where the grain comes from anymore. I weigh it, I smoke it, I salt it down, and I serve it out by the proper measure to men who fight on what I issue. That is the trade. That has always been the trade. Discipline at the salt — speak your need."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_141", "Word From The Salt-Road"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_142", "The salt-runners came in from <span style=\"BandItPlus.Place\">Lageta</span> three nights back, and their barrels rang half-empty. Garrison quartermasters there are buying every grain of preserving-salt at fourteen <span style=\"BandItPlus.Coin\">denars</span> the measure — twice what the muster paid last winter. If you've a mule and a stomach for legion roads, ride south before the snow closes the pass. The price will not hold past first thaw.\n\nGrain is the other story. <span style=\"BandItPlus.Name\">Lord Lucon</span> emptied three granaries at <span style=\"BandItPlus.Place\">Epicrotea</span> to feed his levy, and now the town bakers are paying eleven <span style=\"BandItPlus.Coin\">denars</span> the sack for plain barley. A wise carter loads at <span style=\"BandItPlus.Place\">Amitatys</span> and walks the western trace — the toll-men there still count by the old eagle-scale, and they don't know the market has moved.\n\nA Vlandian caravan limped past the marker-stone last week carrying sweetwine from <span style=\"BandItPlus.Place\">Pravend</span>. Their guards looked thin and their amphorae rattled loose in the straw, which tells me half their stock cracked at the river-ford. Whoever meets them at <span style=\"BandItPlus.Place\">Jaculan</span> will name his own price for what survives. I'd take dates over wine for the carry — they don't weep when you drop them.\n\nNow hear the bad word. The smokehouses at <span style=\"BandItPlus.Place\">Ortongard</span> shut their doors a fortnight past — murrain in the swine, and the herders burned what they couldn't bury. That means dried meat will scarce up by midsummer all along the northern reach. Buy your hard sausage now while the southern hams still come through, or eat hearth-bread and regret.\n\nOne last count for you. There's a famine waking in the steppe — riders from <span style=\"BandItPlus.Place\">Quyaz</span> traded a saddle for a half-sack of millet, and a Khuzait does not part with a saddle for nothing. When the grasslands hunger, they ride west. Lay in your stores and bar your salt-cellar. The cohort taught me that — count twice, hoard once, and never trust a thin month to feed a fat one."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_143", "Quartermaster Plinius"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_144", "Cohort-Steward"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_145", "Served the Sphendos legion's commissary for thirty years before the Empire forgot his cohort even existed. Brought half the larder out with him; the other half went to a Vlandian outrider's stewpot."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_146", "Quartermaster Plinius, traveler. Aurelius vouches for you — the cohort's word, and the cohort's word still stands. The commissary, however, is mine. Requisition's {BP_VENDOR_QUEST_DESC} from the field. Bring it, and you'll eat off the same plate the legion did when it still remembered itself."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_147", "Cohort ration was three-grain bread, salt-pork, and pickled lentil — held a campaign through three rivers. The trick's the lentil brining; vinegar, not water. Vlandian quartermasters use water and wonder why the meal goes off. I'd forgotten the brining for a year before the cohort remembered me."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_148", "Bring me the cohort-count, traveler — how many you'll feed, how many days marched. I'll requisition you a column-ration the empire stopped issuing forty years back. Four denars on the ledger, sample loaf for tonight. Aurelius's seal at no charge."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_149", "Wife in Sphendos, two daughters — haven't sent word since the cohort burned its standard. Forty years gone; they'd be grandmothers now, if Sphendos still kept their ledger. I salt the senior daughter's name into every barrel of pickled-pork. The empire doesn't read its own salt."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_150", "Centurion-Quartermaster Druso runs the staging-larder at the Imperial Galician border-post — three cohorts removed from us, but Sphendos blood. Tell him Plinius still brines in vinegar; he'll seat you at the requisition table. Coin for the seal.")
        };
        private static readonly VendorProfile _legionGear = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_151", "Caravan out of <span style=\"BandItPlus.Place\">Pravend</span> rolled through three nights back, hauling steel billets stamped with the imperial eagle - half-rate quality, the kind they used to reject at the cohort forge before the discharge. Driver was sweating coin he didn't have, said the buyer in <span style=\"BandItPlus.Place\">Lageta</span> stiffed him on the last run and now he's moving south with no escort past the second milestone. Two outriders, both green. You want billets cheap, that's where billets are cheap.\n\nThere's a <span style=\"BandItPlus.Name\">Lord Lucon</span> burning through his treasury keeping mercenaries on retainer - word from a smuggler who drinks with his quartermaster is he's down to under three thousand <span style=\"BandItPlus.Coin\">denars</span> in the strongroom and selling off his armory piecemeal to keep the spears fed. Lamellar, mail shirts, a few good helms. He's pricing them like a man who needs the coin yesterday. If you've got a runner who can move quiet through <span style=\"BandItPlus.Place\">Amitatys</span>, that's a buyer's market dressed up as a fire sale.\n\nLeather's the real story though. Glut out of the eastern tanneries - some fool overbought hides on a bad harvest gamble and now every caravan east of <span style=\"BandItPlus.Place\">Ortysia</span> is dragging stacks they can't shift. Saw a merchant named <span style=\"BandItPlus.Name\">Vlachos</span> offering tanned cowhide at sixty percent below what I paid last winter, and he was practically begging. Buy now, sit on it through the spring campaigns, sell it back to the same idiots at three times the price when their straps start rotting.\n\nIron's tighter. The <span style=\"BandItPlus.Place\">Battania</span> mines slowed their shipments after that flooding business, so anyone moving raw stock north is asking nine hundred <span style=\"BandItPlus.Coin\">denars</span> a load and getting it. A smuggler I trust says a Sturgian buyer in <span style=\"BandItPlus.Place\">Revyl</span> is overpaying - twelve hundred, no questions on the stamp. If a caravan happened to lose its way between here and there, well. Iron doesn't remember whose hand it passed through."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_152", "There's a thing the legion taught us that no smith outside the cohorts knows. When you fold the billet for a spatha, you don't fold it odd. You fold it even — fourteen times, never thirteen, never fifteen. Thirteen leaves a soft seam down the spine. Fifteen burns the carbon out and leaves you a pretty blade that snaps on the second parry. Fourteen is the number <span style=\"BandItPlus.Name\">Master Quintus</span> beat into me at the <span style=\"BandItPlus.Place\">Pravend</span> forges when I was a boy of twelve, and fourteen is the number I still count under my breath every time the hammer comes down.\n\nThe temper is the other half. Most smiths quench in oil or in plain water and call it done. We quenched in brine — sea salt boiled down with a fistful of crushed oak gall, the same gall the tanners use. The gall draws the heat out uneven, harder at the edge, softer at the spine, and you get a blade that bends before it breaks. A legionary who breaks his sword in the first hour of a hold dies in the second. A legionary whose sword bends gets to walk home. That mattered, once. Cost extra, too — the quartermaster paid me an extra forty <span style=\"BandItPlus.Coin\">denars</span> a blade for the brine work, and I never saw a copper of it after the discharge.\n\nThe legion mark goes on last. Two crossed sticks inside a circle, stamped cold into the ricasso with a punch I cut myself the week I made centurion-smith. Cohort marks underneath — mine was the Ninth, three dots in a triangle. I still stamp it. I know I shouldn't. There's an edict somewhere in <span style=\"BandItPlus.Place\">Lycaron</span> that says any man stamping legion marks on private work eats six months in a salt pit. Let them come find me. They already took the pension, the pay, and the wall to put my name on. The stamp is mine. They can have it back when they pry the punch out of the coffin.\n\nI'll sell you a blade with the mark or without. Without is twenty <span style=\"BandItPlus.Coin\">denars</span> cheaper because it's faster, and because a man who wants the mark is buying a story, not a sword. Tell me which kind you are and I'll know what to charge you."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_153", "The Stamp I Kept"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_154", "They mustered us out at <span style=\"BandItPlus.Place\">Lageta</span> with a clap on the shoulder and three months' arrears in <span style=\"BandItPlus.Coin\">denars</span> that never came. Twenty-two years I'd kept the cohort's iron honest — wedged loose lorica plates back into their straps before dawn marches, re-cuffed pilum sockets after every skirmish on the <span style=\"BandItPlus.Place\">Pravend</span> road. A legion armorer doesn't get a pension. He gets a hammer he's allowed to keep, and a stamp die the quartermaster forgot to ask back.\n\nI tried civilian work first. Set up a stall outside <span style=\"BandItPlus.Place\">Amitatys</span> reforging plow-shares and shoeing mules, and the guild men came round inside a fortnight to break my anvil and explain who paid the magistrate. <span style=\"BandItPlus.Name\">Centurion Aurelius</span> — what was left of him — sent a rider out to find me with word the old cohort was reforming under no banner anyone would name aloud. I came because the alternative was begging at a temple gate, and because my hands don't know any other shape than tang and rivet.\n\nSo now I work at the camp forge with the same die I carried out of <span style=\"BandItPlus.Place\">Lageta</span>. Every helmet that leaves this anvil gets the legion mark stamped behind the brow-band — small, where the strap covers it — and I sleep better for putting it there. The leather is local and the buckles are whatever the scavengers bring in off the <span style=\"BandItPlus.Place\">Quyaz</span> caravans, but the edge geometry is regulation. I won't sell a man a blade that fails him at the shoulder roll. I've buried too many who trusted bad steel.\n\nThe lads call me Smith because they think it's a name. It isn't. It's what I am, and what I was before the discharge papers said otherwise. You want a mail shirt that'll turn a horse-archer's bodkin at thirty paces, I have one. You want a gambeson stitched the way the legion stitched them, three layers and the cross-quilt, I have that too. You want it cheap — go find a tinker. Legion standards cost what they cost."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_155", "Iron Moves Where Wars Wait"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_156", "The word? The word is iron, friend, and there's not enough of it moving south. A Sturgian convoy out of <span style=\"BandItPlus.Place\">Revyl</span> got hit twice on the Tyal road — second time the drivers walked away and left forty bars of bog-steel sitting in a ditch for the crows. Whoever scavenged that haul is sitting on a year's worth of spearheads. If you hear of a smith suddenly flush with stock and no foundry receipts, that's where it came from.\n\n<span style=\"BandItPlus.Name\">Lord Lucon</span> out of <span style=\"BandItPlus.Place\">Lageta</span> is paying eighteen <span style=\"BandItPlus.Coin\">denars</span> a shield, no questions about the maker's stamp. He lost half his garrison kit when the Khuzaits torched his outer wall, and he wants the racks full before the thaw. Plain oak rim, iron boss, leather face — quantity over craft. Any journeyman with two apprentices and a willing arm can clear three months' rent inside a fortnight if he can haul the load up that hill road.\n\nThe proper news, though, is <span style=\"BandItPlus.Place\">Pravend</span>. The Emperor's quartermasters are buying every scrap of legion-pattern plate they can find — buying back the discharge gear, mind you, the kit men like me carried out the gate on our last day. Twenty-two <span style=\"BandItPlus.Coin\">denars</span> a cuirass if the cohort mark is still legible. Word in the cohort houses is they're standing up two new legions before the campaigning season and don't have the forges to outfit them honest.\n\nA Vlandian caravan moved through the hill passes last week pushing crucible-steel ingots toward <span style=\"BandItPlus.Place\">Ortongard</span> — eight mules, four guards, no banner. That's the third such run this season. Somebody in the west is stockpiling, and stockpiling means a war contract that hasn't been announced yet. Mark the route. When the contract drops, the price doubles.\n\nLast bit, and you didn't hear it from me. <span style=\"BandItPlus.Name\">Mestonios the Tanner</span> down at the smokehouse end of camp gets his hide-stock from a driver who runs the <span style=\"BandItPlus.Place\">Epicrotea</span> road. Driver told him the Aserai are buying mail by the cartload through <span style=\"BandItPlus.Place\">Quyaz</span> middlemen — paying in <span style=\"BandItPlus.Coin\">dinars</span>, no haggling. That's not garrison restock. That's somebody fitting out a desert column. Keep your ear on that one."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_157", "Smith Galvius"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_158", "Armorer"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_159", "Repaired imperial mail at three cohort-forges and three forgotten campaigns. Knows every weakness of every plate the Empire still issues — which is why his repairs hold longer than the originals."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_160", "Smith Galvius, traveler. Aurelius lets you walk among the cohort; my forge sets a higher bar than the centurion. Bring me {BP_VENDOR_QUEST_DESC} from the road, and I'll repair your mail the way the Empire stopped doing thirty campaigns back."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_161", "Imperial mail thins at the third-link, every fifth row, traveler — that's the rivet-pattern. Repair the thin link, not the broken one; the breakage points to the next failure. Empire stopped teaching the inspection thirty campaigns back. The cohort forges still know."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_162", "Bring me your mail, your draw-weight, your campaign-count, traveler. I'll re-rivet you a coat the cohort would have called 'standard.' Five denars on the ring-stock, the rivets at no charge. Here — a spare ring for your belt-tool."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_163", "Son served the same cohort. Took an arrow at the second river — third-link weakness in his own coat, the rivet I'd set the year before. I keep the coat in the forge-rafters now. Every campaign I look at the link. The grain still tells me where the next one'll go."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_164", "Smith Cassius works the Vermouth border-forge — same cohort, lost his eye on the same march. Tell him Galvius still reads the third-link; he'll bring out the cohort's old standard from the back-room. Coin for the road north.")
        };

        // ===== SKY RAIDERS (Aerlin Cliffborn's clan) =====
        private static readonly VendorProfile _skyFood = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_165", "A snare lives or dies by what walks past it, and the same's true of a man with ears. I sit on the ledge above the goat-track most mornings, gutting hares, and the muleteers from <span style=\"BandItPlus.Place\">Zeonica</span> don't think a barefoot trapper understands their tongue. They say <span style=\"BandItPlus.Name\">Lord Stenmar</span> has pawned his wife's brooch to a Sturgian factor — three lean caravans rolled south last week with nothing but tally-sticks and promises. A lord short on coin is a lord whose tax-wagons ride with two spears instead of six. Worth knowing, if a man were thinking of being somewhere along that road.\n\nThe grain's the real talk, though. <span style=\"BandItPlus.Place\">Pen Cannoc</span>'s smokehouses went cold a month past — no salt. Battanian salt-trains used to come up the Ostican fords, but the fords flooded and the new road through <span style=\"BandItPlus.Place\">Galend</span> takes twice as long with half the guard. A barrel of coarse salt that fetched twelve <span style=\"BandItPlus.Coin\">denars</span> in spring is going for forty in the lowland markets, and the smoker-wives are weeping. I've been salting my hare-meat in ash and birch-bark like my grandmother did. Tastes of nothing, keeps a fortnight, and the raiders won't touch it — which suits me, since it means I eat.\n\nGrain's the other tooth in the same jaw. The Vlandian merchant <span style=\"BandItPlus.Name\">Joffroi the Stout</span> came through three nights ago, fat-faced, fat-pursed, paying sixty <span style=\"BandItPlus.Coin\">denars</span> a sack for any rye he can find. Sixty. The market price is twenty-two. He's buying for someone — a siege-stock, I'd wager, or a quartermaster skimming. He travels with four guards and a cook. The cook drinks. I mention this only as a fact about the world, the way a man mentions which way the wind blows when he's setting a snare.\n\nAnd the rock-grouse don't lie either. They've been thick on the south crag this season because nobody's been firing the heather — too few shepherds, the boys all gone south chasing mercenary coin from a Northern lord who'll be bankrupt by Tenmoot. Grouse stew tonight, if the chief'll trade me a sack of barley for the brace I've got hanging. He won't. He never does. So I eat what the raiders will not pay for, and I listen, and one day the listening will be worth more than the meat."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_166", "You want to know why my jerky doesn't crack your teeth like the raiders' salt-pork does? It's the brine. Most folk salt their meat in barrels of seawater hauled up from the coast, but I climb down to the wind-caves below the <span style=\"BandItPlus.Place\">Crag</span> and scrape the white crust off the walls where the spray dries. It's saltier than ocean, sharper, and it carries something of the cliff in it — a mineral bite that pulls the water out without turning the flesh to leather. Three days in a clay jar with that scraping, a handful of crushed juniper berries, and the bruised seedheads of the bitter grass that grows where the goats won't graze. Then I hang the strips in the smoke-hole over green pine.\n\nGreen pine, mind you. Everyone else uses dry oak because that's what the books say if you can read books, which I can't. Dry oak gives you a clean smoke and a pretty colour. Green pine gives you a resin that seals the outside of the hare-meat against the wet sea-fog up here. A strip of my jerky will keep a year in a man's pouch on the cliffs without going soft. The raiders sneer because it tastes of sap. The raiders also throw three-quarters of their plunder-salted pork into the gulls' mouths when it weeps black in the rains.\n\nThe grouse I do different. The grouse I don't smoke at all — I pack them whole in the rendered fat off their own breasts, with a sprig of the sour cliff-thyme tucked under each wing. Sealed in a crock and buried in the cold scree behind my hut, they'll come out at midwinter tasting better than the day I caught them. I learned this from my mother, who learned it from hers. We were never raiders, my people. We were cliff-folk. The raiders took the high holds two generations back and we just — stayed. Cooked for them. Took their <span style=\"BandItPlus.Coin\">denars</span> when they remembered to pay.\n\nI'll sell you a strip for a copper and a crock for forty. Don't tell <span style=\"BandItPlus.Name\">Vagh the Reaver</span> what's in it. He thinks I just have a knack. Let him think that. A man who eats well and doesn't ask questions is a man who keeps paying."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_167", "Cliffs Feed the Patient"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_168", "High air, aye, and a long way down for them that step wrong. I was born in a herder's hut clinging to the slopes above <span style=\"BandItPlus.Place\">Pen Cannoc</span>, eldest of six and the only one with patience for snare-work. My father taught me the cliff paths before he taught me my letters, which is to say he never taught me letters at all. Hares, rock-grouse, the fat little marmots that whistle from the scree — I learned which trails they wore smooth, and which knots would hold a kicking leg without snapping it.\n\nThe herd died in the long winter, two seasons running. My brothers went down to <span style=\"BandItPlus.Place\">Car Banseth</span> to swing pikes for whoever paid, and most of them did not come back. I climbed higher instead. Up where the raiders nested, where a man with a sack of snared grouse could trade for salt and rough flour and the odd handful of <span style=\"BandItPlus.Coin\">denars</span> when a sea-prize came in. The boss took one look at my callused hands and said the camp had bellies enough to feed, if I could keep feeding them.\n\nSo I bring in what the raiders won't trouble with. They want salted beef from coastal hauls, smoked pork off the <span style=\"BandItPlus.Place\">Ostican</span> traders, fat rounds of hearth-bread when the dough-women of <span style=\"BandItPlus.Place\">Marunath</span> are bribed quiet. Me, I bring grouse and hare and the dried strips of marmot that nobody else will chew. Salt I have to buy down-mountain — there's a man in <span style=\"BandItPlus.Place\">Pen Cannoc</span>, calls himself <span style=\"BandItPlus.Name\">Old Gwynn</span>, who'll cut me a block for half what the lowland merchants ask, so long as I bring him a hare-pelt in trade.\n\nIt pays. Not in gold, mostly. In a roof when the wind comes off the crag like a knife, in stew that's hot whether I caught the meat in it or not, in nobody asking where I sleep. <span style=\"BandItPlus.Name\">Lord Caolan</span> tried to recruit me once when his riders passed the lower pass — said a snare-man's eye for ground was wasted on grouse. I told him my eye for ground was the only reason I was still alive, and I meant to keep it.\n\nThat's the trade, friend. Cliffs feed the patient. Camp feeds the rest of it. And if the wind shifts wrong while we're talking, you'll learn the first lesson up here faster than I can teach you the second — so be quick with your coin, and quicker with your feet."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_169", "Word From The Crags"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_170", "The wind carries more than dust up here, friend. A trapper on the cliffs hears every caravan-bell three valleys before it crests the ridge. So yes — I have a word or two for the road, if you'll trade me a moment of breath.\n\n<span style=\"BandItPlus.Place\">Pen Cannoc</span> is buying salted meat at near double the spring price. Their smokehouses burned in a careless feast-night, and the cottars are paying eighteen <span style=\"BandItPlus.Coin\">denars</span> the brace for any rock-grouse a man can drag down off the crags. If you've a strong arm and a quiet foot, that's where the coin is sleeping.\n\nA sweetwine caravan out of <span style=\"BandItPlus.Place\">Car Banseth</span> took the lower pass three days back — fat barrels, thin guards. <span style=\"BandItPlus.Name\">Caladog</span>'s warband sniffed it, but the rains washed their tracks before they could move. The barrels are still rolling. Someone will eat well, or someone will bleed well. Maybe both.\n\nThere's a hunger coming to the eastern moors — the hare-runs are empty this season, and the wolves have moved down from the heights. I've seen it twice in my life and both times the cottars came begging up the cliff-tracks before the second frost. Lay in dried meat now, and you'll be a rich man by midwinter. Wait, and you'll be a thin one.\n\nLast thing, and then you go. <span style=\"BandItPlus.Name\">Penn the Larder</span> at the lower camp is short on hearth-bread flour — the mill at <span style=\"BandItPlus.Place\">Dunglanys</span> cracked its wheel and won't grind till the snows. Bring him a sack of barley meal, he'll pay you better than the markets will. Now — high air, low patience. Off with you."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_171", "Bran of the Crag"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_172", "Snare-Master"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_173", "Trapped high-pass red-grouse for Battanian lords until one lord fed him to dogs as sport. Bran climbed back up the cliff, came back with steel a year later, and never went down again."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_174", "Bran of the Crag, traveler. Aerlin's wind likes you; my snares are pickier. Bring me {BP_VENDOR_QUEST_DESC} from the lowlands — the high passes have stopped giving them up — and I'll feed you what the cliff-clans still eat when the snow comes."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_175", "Crag-grouse only eats the high pine, traveler — that's the resin in the flesh, the bitter under the salt. The trick's the pluck, not the cure: thirty feathers at the breastbone, never the back. Battanian wood-lords used to feed the rest to dogs. Now we eat the bird; the dogs eat memory."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_176", "Name a banquet, traveler — high feast, name-day, mourner's table. Three pairs at the snare and a fortnight's notice. Five denars on the trap-line, sample bird tonight at no charge. The cliff'll furnish the rest."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_177", "Wife was Battanian — Maire of the lower oak-stand. They fed me to the dogs as sport; they fed her to nothing. She'd be grandmother age now, if the lord hadn't taken her hand for shielding me. I climb the cliff every winter solstice and leave a grouse on the high ledge. The wind takes it before morning."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_178", "Old Findlay traps high-pass red-grouse at the Battanian crag-line — learned the resin-cure from me before the dogs came. Tell him Bran still climbs; he'll show you the high-ledge cache. Coin for the climb-rope and the inn at the foot.")
        };
        private static readonly VendorProfile _skyGear = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_179", "Aye, sit down by the grindstone. You want gossip, I trade it cheaper than the iron — and lately iron's the word on every tongue that passes this hideout. A Battanian charcoaler limped through three nights back, axle split, and he sang for his repair. Said the steel-billet caravan out of <span style=\"BandItPlus.Place\">Pen Cannoc</span> rolls south next waxing moon with just six spears for escort — six! — because <span style=\"BandItPlus.Name\">Lord Caradog</span> pulled half his retinue to chase a rent-dodger near the coast. Six spears guarding a wagon worth four hundred <span style=\"BandItPlus.Coin\">denars</span> in raw billet alone. I'd call that an invitation, not an escort.\n\nSmuggler woman, calls herself <span style=\"BandItPlus.Name\">Mira of the Crooked Tooth</span>, came up to barter a bundle of seal-hide for two of my throwing-axes. She drinks loud, that one. Told me the Vlandian armorers at <span style=\"BandItPlus.Place\">Galend</span> are paying near double for any iron stock that walks in the gate — their last shipment got snowed under in a pass and the smiths are screaming. Anyone holding pig-iron right now is sitting on a vein. Meanwhile there's a glut of cheap boiled-leather flooding the <span style=\"BandItPlus.Place\">Ortongard</span> markets because a Sturgian tanner's widow dumped her whole stock to settle a debt — so don't raid wagons for hides this season, you'll lift a ton and sell it for nothing.\n\nGrain's where the real bite is. The smokehouse at <span style=\"BandItPlus.Place\">Hringgard</span> burnt to a black ring two weeks gone, and now every village from the firth to the foothills is short on salt-fish for winter. That means the salt road from the coast is moving four times the usual carts, and they're undermanned — <span style=\"BandItPlus.Name\">Reeve Hagen</span> can't conscript fast enough. Grain prices in the lowlands jumped from eight to fifteen <span style=\"BandItPlus.Coin\">denars</span> a sack, and a sack of millet from a raided granary will feed this hideout a fortnight or buy two good axe-heads.\n\nOne last whisper — and this one I'd believe if I were you. A Khuzait factor passed through with a string of remounts, and he was nervous. <span style=\"BandItPlus.Name\">Lord Berrun</span> of the southern marches is short coin again, third time this year. He's quietly selling off captured mail-shirts at half-price through a fence in <span style=\"BandItPlus.Place\">Sargot</span> to make his retinue payroll. Half-price mail, friend. If you've got a man who can pass for a merchant and a purse of <span style=\"BandItPlus.Coin\">denars</span>, you walk out of Sargot kitted like a count's huscarl. Now — you want that axe sharpened, or are you just here for the talk?"),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_180", "Most smiths will tell you the secret of a good axe is in the steel. They're wrong. The secret is in the eye — the hole where the haft seats. I drift mine cold after the first forge-weld, with a tapered punch I cut from a wagon-axle I pulled off a caravan from <span style=\"BandItPlus.Place\">Pen Cannoc</span> nine winters back. Cold-drifting work-hardens the cheek walls so they grip the haft like teeth. A hot-drifted eye loosens after a season of swinging. Mine don't. Ask any raider who's carried one through three campaigns.\n\nThe bit is my own twist. I forge-weld a strip of high-carbon down the cutting edge — old file steel, mostly, broken rasps the smugglers bring up from the lowland forges for twelve <span style=\"BandItPlus.Coin\">denars</span> a bundle. The body stays soft wrought iron so the head won't shatter on a shield-rim, but the edge holds a shaving angle for weeks. The trick is the quench. Water hisses the carbon out and makes the edge brittle. I use whey — sour goat-whey, two days old, from <span style=\"BandItPlus.Name\">Old Mev's</span> herd up the ridge. The fats and salts slow the cool just enough. Comes out the colour of a wet stone and twice as mean.\n\nWhen the iron runs thin — and it does, every spring before the caravans climb again — I knap arrowheads from the black flint that outcrops a half-day east, past the <span style=\"BandItPlus.Place\">Crow Notch</span>. My da taught me before he taught me the bellows. He said a man who can only work one stone is half a smith. Flint's faster than forging, sharper than steel for the first shot, and the lads can fletch a hundred shafts in an evening. They don't fly true past forty paces, but most of our work isn't done past forty paces.\n\nI won't sell the cold-drift punch. I've been offered eighty <span style=\"BandItPlus.Coin\">denars</span> for it twice, once by a caravan-master who thought I was simple. The punch came from my da's anvil, and his da before him, back when our line still had a hall down on the plain. Lost the hall. Kept the punch. Tells you everything you need to know about what matters."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_181", "Ten Winters At This Anvil"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_182", "My father knapped flint in a glen below <span style=\"BandItPlus.Place\">Pen Cannoc</span>, back when the lowland smiths still came up to barter for our hill-iron. He taught me the trick of reading a stone before you strike it — the grain tells you where it wants to break, and a wise man does not argue. I was twelve when the Sturgian raiders burned the glen for being too close to the road, and I walked north with nothing but my father's striker and a half-finished hand-axe in my belt.\n\nI came to the Sky Raiders by way of <span style=\"BandItPlus.Place\">Revyl</span>, where I hammered cheap helmet-rims for a merchant who paid in spoiled grain and excuses. <span style=\"BandItPlus.Name\">Old Kaerl Blackthumb</span> ran the forge here before me, and when his lungs gave out from the bellows-smoke he passed me the tongs without ceremony. Ten winters I have stood at this anvil since. Ten winters of axe-bits and arrow-points and the smell of quenched steel rising into the rafters.\n\nWhen the iron caravan from <span style=\"BandItPlus.Place\">Quyaz</span> is late — and it is always late — I go back to my father's craft. Flint heads bite as deep as steel into a man not wearing mail, and the raiders do not often fight men in mail. I knap until my thumbs bleed, then I wrap them in leather and knap some more. The boys laugh until they see a flint head split a shield-rim, then they stop laughing.\n\nWhat pays a man into this trade? <span style=\"BandItPlus.Coin\">Denars</span>, sometimes. A warm corner of the camp, always. The right to refuse the work that bores you. Down in <span style=\"BandItPlus.Place\">Pravend</span> I would be shoeing horses for a fat reeve who never said my name. Up here they call me Axe-Master, and they mean it. That is worth a lowland winter and then some.\n\nSo pay for the edge. The edge is what keeps you breathing past the next ridge, and I do not waste my striking-arm on men who think craft is haggled like turnips."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_183", "Word From the High Passes"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_184", "Word from the high passes — <span style=\"BandItPlus.Place\">Omor</span>'s castellan is buying every spear-tip the smiths can hammer out. Some Sturgian thane down-mountain promised him three hundred <span style=\"BandItPlus.Coin\">denars</span> a bundle and the forges are running hot through the night. If you've got iron stock to move, that's the road. Don't take the southern fork — wolves and worse.\n\nA caravan out of <span style=\"BandItPlus.Place\">Revyl</span> is hauling Nord steel-billets west, escorted by <span style=\"BandItPlus.Name\">Lord Tagvirr</span>'s house-guard. Twelve wagons, mailed riders, the works. The raiders below have eyes on it, but I'd not be the one swinging the axe — Tagvirr's men fight like the cliffs themselves. If you ARE that one, mind: the billets are crude, need a forge to make them anything. Raw weight, no edge.\n\n<span style=\"BandItPlus.Name\">Hrothgar Anvil-Hand</span> down at <span style=\"BandItPlus.Place\">Tyal</span> is taking on three new apprentices — old fool's hands are giving out and he wants the craft passed on before the frost takes him. Pays in food and a roof, not coin. I trained under him forty winters back. If you know a lad with steady arms and no kingdom, send him.\n\nThe leather-cutters at <span style=\"BandItPlus.Place\">Pen Cannoc</span> ran short on hide last moon — some Vlandian count bought the whole season's run for his garrison kit. Means raw skins are fetching double in the lowland markets, and any saddle-stock moving north is gold on the hoof. Keep your knife sharp if you ride that way.\n\nOne more — flint. The seam I knap from is thinning, third winter running. If you pass an old riverbed with good black stone, mark it for me. Two <span style=\"BandItPlus.Coin\">denars</span> a fist if it strikes clean. Edge is everything up here, and the iron's only as honest as what backs it."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_185", "Tregar Stone-Knapper"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_186", "Axe-Master"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_187", "Knapped flint for the last of the high-pass mining gangs before the gangs were taxed into nothing. Now flakes steel the same way; the wind whistles through his blades the way it used to whistle through his pit-shafts."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_188", "Tregar Stone-Knapper. The bird trusted you — that's Aerlin's measure. Mine's flint, traveler, and steel after that. Bring me {BP_VENDOR_QUEST_DESC} and I'll knap you an axe-edge that holds longer than any imperial-issued blade you've carried."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_189", "Flint flakes along the grain; steel flakes against it, traveler. Imperial smiths grind the edge; I knap it — three taps on the spine, one on the bevel. The blade holds a cut where the imperial issue rolls. The high-pass mining gangs taught me before the tax-men taught them silence."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_190", "Bring me a steel-bar and your draw, traveler. I'll knap you an edge that holds three campaigns; flake the bevel to your hand. Six denars on the heat, three on the tap-pattern. Here, a knapped spike to mark the deal."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_191", "Had a son in the last pit-gang — Cailean, fifteen winters when the taxmen sealed the shaft. The empire called it 'flooding'; the mountain called it murder. I knap a small flint each year on his name-day and leave it at the sealed shaft. Sometimes it's gone the next month. Sometimes the mountain returns it polished."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_192", "Old Maeve at the Pictish stone-village still knaps the way her mother did — flint, not steel. She remembers the mining-gangs. Tell her Tregar walks the high passes; she'll show you the inner knapping-yard. Coin for the long climb.")
        };

        // ===== STEPPE WOLVES (Khan Borchu's clan) =====
        private static readonly VendorProfile _wolvesFood = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_193", "Caravan came down the <span style=\"BandItPlus.Place\">Bulugur Pass</span> last moon and the drover wouldn't shut his mouth once I poured him fermented mare's milk. Says grain out of <span style=\"BandItPlus.Place\">Makeb</span> is moving at near <span style=\"BandItPlus.Coin\">42 denars</span> the sack now, on account of the southern harvest going to weevils. Khuzait stewards in <span style=\"BandItPlus.Place\">Ortongard</span> are paying double for any sack that doesn't smell of mold. Khan-herd boy I was, but I know a desperate price when I hear one.\n\nThe interesting word, though, is on <span style=\"BandItPlus.Name\">Lord Khasar</span> — yes, that Khasar, the one who used to ride down our cousins. His coffers are dry. Drover swore he saw the lord's quartermaster haggling over a wheel of cheese at the <span style=\"BandItPlus.Place\">Iadgar</span> market like a widow at dusk. Three of his retainers haven't been paid since the last full moon. His column down the <span style=\"BandItPlus.Place\">Quyaz Steppe road</span> rides with maybe twelve spears now, and half are conscripts who'd rather be home shearing.\n\nSalt's the other thing worth your ear. The smokehouses in <span style=\"BandItPlus.Place\">Akkalat</span> shut down — the salt-train out of <span style=\"BandItPlus.Place\">Odokh</span> got hit twice this season, not by us, by somebody sloppy, and now the saltmen ride with the empire patrols and won't take the steppe shortcut at all. That means every herder from here to the <span style=\"BandItPlus.Place\">Tsagaan flats</span> is sitting on meat he can't cure. I've got two riders trading our reserve at <span style=\"BandItPlus.Coin\">9 denars</span> the brick to villages that were paying three a season ago. Whole flocks of mutton coming our way for it, cheap.\n\nOne more, and then I'll let you eat. There's a Vlandian factor — <span style=\"BandItPlus.Name\">Gisbert of Jaculan</span> the drover named him — buying steppe cheese and fermented curd at city prices, no questions on where it came from. Pays in clipped <span style=\"BandItPlus.Coin\">denars</span> but pays fast. He's camped near <span style=\"BandItPlus.Place\">Zeonica</span> for another fortnight. If the boys come back with a wagon out of any caravan we don't want to keep, tell them: cheese to Gisbert, grain to Ortongard, and don't, by the long sky, try to sell salt anywhere within a week's ride of the empire roads."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_194", "Want to know why my dried meat keeps when the southern caravans turn green by the second moon? Salt alone won't do it on the steppe — too dear, and the air's too dry to draw the juice clean. So I do it the old khan-herder way: I bury the strips in a pit lined with last winter's <span style=\"BandItPlus.Place\">Khurel Salt Flats</span> crust, but I mix that crust one-to-three with crushed wild onion, sour-grass seed, and a fistful of ash from burnt birch — never pine, pine sweetens the fat and the wolves can smell sweet meat from a day's ride.\n\nThe trick the caravans miss is the second pit. After eight days under the salt-ash, I dig it up, rinse it in mare's milk gone half-sour, and re-bury it in cold yurt-shadow for another four. The sour milk eats whatever bitterness the ash left and puts back the tang a wolf-rider expects on his tongue. Stranger asked me once why I bother with two pits. I told him: one pit feeds a man. Two pits feed a man riding three days from camp with nothing on his belt but a knife.\n\nI learned it from my grandmother when I was small enough to ride behind her on the herd-pony. <span style=\"BandItPlus.Name\">Old Naran</span>, they called her — she'd cured meat for the khan's outriders before the southern lords ever knew our name. She told me the salt-flat crust is half the secret; the patience is the other half. Most camps eat their meat before it's done. That's why most camps starve in the third moon and we don't.\n\nI'll sell you a finished strip for eight <span style=\"BandItPlus.Coin\">denars</span> the bundle, or I'll sell you the salt-blend recipe for forty and you can ruin your own meat learning it. Either way, don't tell the khan's quartermaster I told you about the second pit. He thinks I do it with prayer."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_195", "Salt, Smoke, And Steppe"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_196", "A boy on the long grass learns the herd before he learns his own name. I rode behind the khan's mares before I could grip a bow, counting foals at dawn, salting hides at dusk. My father was no warrior — he was the man who knew which spring still ran in the dry month, and which marmot warren had grown fat. He taught me that a camp dies of empty bellies long before it dies of empty quivers, and that lesson has fed me every winter since.\n\nWhen the old khan fell on the road below <span style=\"BandItPlus.Place\">Quyaz</span>, the herd scattered and the clansmen scattered with it. I drove what mares I could north, traded the lame ones for salt at a Sturgian post, and salt for smoked river-eel from a fenman who owed my father a favor. I have been moving food along that crooked line ever since — grain from <span style=\"BandItPlus.Place\">Pen Cannoc</span> when the borderlords are sleeping, hard cheese off the Khergit shepherds, dried mutton I cure myself in a pit behind the wolves' tents.\n\n<span style=\"BandItPlus.Name\">Khan Bayanchur</span> took me in the year the spring rains failed. He had wolves enough; what he wanted was a man who could keep them fed without dragging a caravan of scribes behind him. I told him I'd feed his camp on what the steppe gave, and what the steppe forgot to give I'd find on the merchant tracks between <span style=\"BandItPlus.Place\">Pravend</span> and the Khuzait pickets. He paid me eighty <span style=\"BandItPlus.Coin\">denars</span> the first month and a wolfskin cloak the second. I have not asked for coin since — the camp eats, and I eat with the camp.\n\nNow I keep the smokehouse pit, the salt-jars, the dough-trough, and the cold cellar we dug under the rocks where the wind never reaches. I trade with whoever comes up the gully — a Vlandian deserter with stolen flour, a Khuzait widow with mare's milk to barter, an Aserai spice-runner who lost his caravan to <span style=\"BandItPlus.Name\">Lord Tagaday</span> and would rather sell to wolves than walk home empty. They all pay in something the camp can chew.\n\nSo that is what pays a man into this trade, traveler. Not gold. Not glory. A boy who counted foals becomes an old man who counts loaves, and somewhere in between he learns that the steppe feeds those who watch — and starves the ones who don't."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_197", "Word From The Long Grass"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_198", "Sit down then, traveler. The kettle's hot and my ears are older than the khan's grandsire's bones, so I hear things before the grass does. Eat first, then I'll tell you what the wind brought in.\n\nThe salt-runners out of <span style=\"BandItPlus.Place\">Quyaz</span> are paying near double what they did last moon — <span style=\"BandItPlus.Name\">Monchug Khan</span>'s outriders are burning anything that moves north of the river, and the merchants daren't run the short road. A clever soul with a string of pack-mules and a quiet tongue could clear sixty <span style=\"BandItPlus.Coin\">denars</span> the sack going east, more if the buyer's a sworn man.\n\nWord from a goat-driver three nights past: <span style=\"BandItPlus.Place\">Makeb</span>'s smokehouses are choking on more mutton than they can cure, and the steward there will take dried curd, hard cheese, anything that keeps. They're buying ahead because the elders smell the bad winter coming — late frost, no fat on the marmots, the old signs.\n\nThe sweetwine caravan from <span style=\"BandItPlus.Place\">Odokh</span> hasn't shown in two turns of the moon, and that's never happened in my life. Either the southern lords have taxed it dead, or <span style=\"BandItPlus.Name\">Urkhun the Lame</span> got tired of waiting and took it himself. If you cross a wagon of amber jars on the south track with no driver — you didn't see anything, eh? You didn't see anything.\n\nLast thing, and listen close: grain is dear, dearer than honey, and getting worse. The Khuzait towns hold their granaries shut, the imperial ones west of <span style=\"BandItPlus.Place\">Akkalat</span> are feeding garrisons that never go home. A man who brings a wagon of barley to this camp before the snows — Old Otchigin will remember his name, and so will the chief. That's worth more than the <span style=\"BandItPlus.Coin\">denars</span>, friend. Out here, being remembered is the whole game."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_199", "Old Otchigin"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_200", "Camp-Steward"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_201", "Khan Borchu's herd-cousin since both were boys riding the same pony. Drives the spare horses, dries the meat, brews the airag. Knows Borchu's silences as well as his words."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_202", "Old Otchigin, herd-cousin to the Khan since we were boys riding the same pony. Borchu lets you walk, traveler — Otchigin's yurt is harder to enter. Bring me {BP_VENDOR_QUEST_DESC} from your road, and I'll dry you meat the way the Khan still eats it."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_203", "Khuzait dried meat takes the wind not the smoke, traveler — racks under the steppe sky, four winds per day, never the lowland fires. The flesh holds through three campaigns. Imperial cooks smoke their stock and call it 'preservation.' The Khan would laugh, if the Khan laughed at imperial things."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_204", "Tell me the camp and the count, traveler — how many you'll feed, how far you'll ride. Three sacks of dried mare-meat, four winds, a fortnight's notice. Six denars on the rack. Here, a strip for your saddle-bag tonight."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_205", "Borchu's herd-cousin since both were boys — never had wife, never had child. Borchu's children are mine by oath; his daughter Sechen calls me 'old uncle' and her son rides my second pony. That's family enough. The steppe doesn't ask for more."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_206", "Tegus Wind-Reader at the Khuzait main-camp keeps the Khan's drying-rack — Borchu's cousin twice over. Tell him Otchigin still racks four winds; he'll seat you at the Khan's own fire. Coin for the long ride east.")
        };
        private static readonly VendorProfile _wolvesGear = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_207", "Saddle's done. Sit. You want to know whose pommel-leather I'm cutting next, you sit through the gossip first — that's the toll. A Vlandian quartermaster came through three sunsets back, riding a mule because his lord pawned the courser. <span style=\"BandItPlus.Name\">Lord Caradoc</span> of the western marches is down to scraping the bottom of his treasury — the man owes his garrison eleven weeks' wages and they're walking off in twos and threes. His tax-wagon out of <span style=\"BandItPlus.Place\">Jaculan</span> rolled past with four guards. Four. For a strongbox the driver bragged held nine hundred <span style=\"BandItPlus.Coin\">denars</span>. I almost laughed in the man's face.\n\nLeather glut, too — and that's the part you'll care about if you're stitching anything wider than a girth-strap. The Aserai broke a contract with two Imperial tanneries and dumped their winter cattle-hide on the <span style=\"BandItPlus.Place\">Quyaz</span> road. Whole caravan of cured cowhide, escort of six, sleeping in shifts. The wolf-cousins out east already clipped one wagon from it last moon — the rest is moving slow because the drovers know it. You hit them, you'll be tripping over leather for a season. I'll buy whatever you don't want — I pay fair, you know I pay fair.\n\nNow the iron, that's where it gets interesting. <span style=\"BandItPlus.Name\">Hakim the Steelmonger</span> out of <span style=\"BandItPlus.Place\">Husn Fulq</span> is panic-buying steel billets at near double the going rate — some southern smith-guild promised him a contract he can't fill, and he's bleeding <span style=\"BandItPlus.Coin\">denars</span> trying to source enough stock before the snow turns the passes. Every billet-cart out of the Battanian hills is being routed past <span style=\"BandItPlus.Place\">Pen Cannoc</span> on the eastern fork now because the main road's got Imperial patrols. Eastern fork's got nothing but a couple of crossbowmen and a dog. You do the arithmetic.\n\nOne more thing, then I'm back to my awl. The salt-caravans out of the steppe lakes are running thin — smokehouse town up by <span style=\"BandItPlus.Place\">Rovalt</span> is screaming for salt at any price, and a merchant calling himself <span style=\"BandItPlus.Name\">Ostavi</span> is paying eighty <span style=\"BandItPlus.Coin\">denars</span> a sack when the honest rate's twenty-eight. He's desperate, which means he's careless, which means his outbound silver-purse rides back south with maybe two riders. Anyway. The saddle's yours. Don't bleed on it before you've paid."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_208", "You want to know why a Wolf saddle does not split when a rider takes a fall from a galloping horse? It is the soak. Three weeks in mare's milk gone sour, then two more in a brine of ash-lye and crushed juniper berries from the slopes above <span style=\"BandItPlus.Place\">Black Pine Ridge</span>. Cow leather rots in that bath. Horse hide drinks it and comes out the color of old blood, supple as a lover's hand, tough as oath-iron. Every saddler in the steppe knows the sour-milk step. Not one of them knows the juniper.\n\nThe cantle, now — that is where the bridle-makers down in <span style=\"BandItPlus.Place\">Sanala</span> get it wrong. They cut the tree from green birch and let it warp around the rider. I split mine from a single block of dead steppe-pine, the kind that has stood twenty winters with its roots in the wind, and I shape it WET to the curve of the specific horse it will ride. Each saddle remembers its mare. Put it on a different horse and it galls inside a day. The wolves pay me eighty <span style=\"BandItPlus.Coin\">denars</span> for one. They would pay two hundred if I asked. I do not ask.\n\nThe stitching is sinew from the back-strap, never the leg. Back-strap pulls evenly when wet and dry. Leg-sinew shrinks one way and slacks the other, and a saddle that breathes uneven will saw a horse raw inside a month. I learned this from my mother, who learned it from her father, who stitched bridles for the khan's own outriders in the years before the clan went bandit. We were saddlers before we were wolves. The horses came first. The blades after.\n\nI will tell you one more thing, and then no more. The pommel knob — the little bone cap most riders never notice — I carve from the kneebone of the horse the saddle is FOR. When that horse falls in battle, the rider keeps a piece of her under his hand for the rest of his life. <span style=\"BandItPlus.Name\">Khasar</span> the chief has three such pommels on his wall now. He does not speak of them. Neither do I. But that is why the wolves ride the way they ride, and why no man who has owned a Bayar saddle ever buys another."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_209", "Why I Cut The Contract"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_210", "My father stitched saddles for the khan's outriders out of <span style=\"BandItPlus.Place\">Quyaz</span>, and his father before him cut bridles from the same horse-leather. I learned the awl before I learned the bow. A good saddle holds a man through three days of riding and a fourth of fighting; a bad one breaks his back before the enemy does. I have made both, and only the first lets you sleep at night.\n\nThe breaking came when a Vlandian buyer rode in from <span style=\"BandItPlus.Place\">Pravend</span> with a fat purse of <span style=\"BandItPlus.Coin\">denars</span> and a contract for forty cavalry rigs. My master took the coin. The leather we were given was thin, splitting stuff — dyed pretty, weak at the cantle. I told the old man it would kill riders. He told me the <span style=\"BandItPlus.Coin\">denars</span> were already spent. So I cut the contract loose with my own knife, and the master cut me loose with his.\n\nThe wolf-clan found me sleeping under a wagon-axle near the salt-trail with my awls in a roll and nothing else. <span style=\"BandItPlus.Name\">Khasar</span> looked at my hands, looked at the stitch on my own belt, and said the camp had been riding on saddles that bled the horses. I have been stitching for them since. No middleman, no Vlandian buyer, no thin leather — just the hide I cure myself and the riders who come back from each raid to tell me where the girth chafed.\n\nThat is what pays a man into this trade. Not the coin. The coin is just what keeps the awls sharp and the tallow stocked. What pays me is knowing the rider who left this morning sits a rig I built, and the rig will not be the thing that drops him. Saddle holds the rider. Coin holds the bargain. Both must fit, or both come apart at the worst hour."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_211", "Word From The Saddle-Routes"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_212", "Sit. Mind the awl. Word travels the saddle-routes faster than any rider, and a man stitching girths hears it twice — once from the courier coming in, once from the courier going out. You asked, so I will tell, but the price of the bridle stays the same either way.\n\n<span style=\"BandItPlus.Place\">Quyaz</span> is buying horse-leather at near double last winter's price. Their khan's brother lost three remounts to a Vlandian raid and now every saddler from the salt-flats to the river-bend is being courted with <span style=\"BandItPlus.Coin\">dinars</span> upfront. If you ride east with cured hide rolled tight, you will not haggle long — but watch the southern track, the toll-riders have grown bold and they take the best skin off the top of the bundle.\n\nA Khuzait caravan out of <span style=\"BandItPlus.Place\">Makeb</span> is moving steel-stock west, bar-iron and rough billets, bound for a smith-house in <span style=\"BandItPlus.Place\">Ortongard</span>. Twelve wagons, light escort, the wagon-master is a one-eyed Sturgian called <span style=\"BandItPlus.Name\">Ulvar Hookhand</span> who drinks too early in the day. I do not say what you should do with that knowing. I only stitch saddles.\n\n<span style=\"BandItPlus.Name\">Lord Monchug</span> has paid out near four thousand <span style=\"BandItPlus.Coin\">dinars</span> for fresh kite-shields and lance-tips, calling every smith in his banner to forge through harvest. That means the small fortresses around him cannot keep an armourer for love nor coin — their best men have ridden to his hearth. If you have a brother who swings a hammer, send him to <span style=\"BandItPlus.Place\">Odokh</span>; they will hire him before he washes the road off his hands.\n\nAnd one last thing, since you have been patient. A Battanian peddler came through last moon with a bundle of yew-staves — proper yew, not the sapling rubbish — claiming a bow-yard near <span style=\"BandItPlus.Place\">Pen Cannoc</span> burned down and the cut wood is loose on the road. If your eye is on bows, ride west soon. The forest does not stay generous long."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_213", "Bayar Saddle-Master"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_214", "Saddle-Master"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_215", "Stitched the Khuzait camp-saddles for the Khan's rival branch before that branch sold him out to imperial recruiters. Borchu rode out alone, took him back unbroken, and burned the rival's gēr for the insult."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_216", "Bayar Saddle-Master. Borchu took me back unbroken; the Khan's word is good. My stitching is better. Bring me {BP_VENDOR_QUEST_DESC} and I'll make you a saddle the imperial recruiters never knew how to copy."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_217", "Camp-saddle takes the stitch flat at the cantle, raised at the pommel — the imperial cross-stitch reverses it and the rider's seat wears wrong. Khuzait stitch is one continuous line, knot at every horse-length. Imperial recruiters never knew how to copy it. Still don't."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_218", "Bring me your horse, your draw, your gallop-mark, traveler. Three denars on the leather, two on the stitch. A spare strap for your current saddle while the new one cures. Borchu's own horse rode three campaigns on my stitch."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_219", "Wife — Khatun — sold out with me to the recruiters; Borchu took us both back. She rides at the Khan's right hand now. We never had children; the rival branch took our youngest before either of us learned his name. Burned the gēr the same night. The fire's still talked about."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_220", "Find Mengetü at the Salp dock-camp — saddle-master for the eastern Khuzait branch, my apprentice before the recruiter trouble. Tell him Bayar still stitches Khuzait-line; he'll show you the inner saddle-rack. Coin for the river crossing.")
        };

        // ===== PAGAN CULT (Crone Vael's cult) =====
        private static readonly VendorProfile _cultFood = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_221", "Sit, sit — eat first, then we trade what we know. The stew is barley and root and the last of the smoked goat. Stir it widdershins for me, will you, so the steam rises toward the rafters where the hearth-spirits listen. Good. Now — three nights past, a salt-cart came up from the marshes, and the carter wept into his bowl. <span style=\"BandItPlus.Place\">Aserai Salt Road</span> is choked again. Bandits, weather, a broken bridge at the seventh ford — pick your story. The flake is up to two hundred <span style=\"BandItPlus.Coin\">denars</span> the brick in <span style=\"BandItPlus.Place\">Pen Cannoc</span>, and the smokehouses from here to <span style=\"BandItPlus.Place\">Marunath</span> are dark for want of it. No salt, no cure. No cure, no winter meat. I read it in the ash three dawns running — a long, thin streak pointing south, broken at the middle. The fire does not lie about salt.\n\nGrain is the gentler omen this moon. The threshers in <span style=\"BandItPlus.Place\">Galend</span> overshot — a fat harvest and nowhere to send it, because <span style=\"BandItPlus.Name\">Lord Caelan</span>'s steward stopped paying caravan-escorts in Bloomtide. The man is bone-dry of coin, my child, dry as a summer trough. Three of his sergeants slipped their oath last fortnight and rode west looking for warmer hearths. So the grain sits in his silos and rots, and the carters who used to haul it now move in twos and threes, unarmed, praying. A wise eye on the <span style=\"BandItPlus.Place\">Galend road</span> between matins and the noon-bell would find wheat going for half-price to anyone with steel enough to ask politely. I do not say what I do not say. The ash only whispers; you hear what you hear.\n\nNow — the smuggler who came in last sennight, the one with the missing ear — he was nervy, and a nervy smuggler tells true. <span style=\"BandItPlus.Name\">Master Doryn</span> the spice-factor out of <span style=\"BandItPlus.Place\">Sanala</span> is overpaying for saffron and pepper both, twice the autumn rate. His patron's daughter is to wed a Vlandian, and the feast must shame the southern courts. He buys blind, asks no questions of provenance. If a brother of ours had, say, recovered a chest of southron spice from a poorly-guarded mule-train on the <span style=\"BandItPlus.Place\">Quyaz pass</span> — Doryn would meet him in <span style=\"BandItPlus.Place\">Razih</span> with a smile and an open purse. Three hundred <span style=\"BandItPlus.Coin\">denars</span> the pound, the smuggler swore on his missing ear. The hearth-fire popped twice when he said it. Two pops is yes.\n\nOne more, and then I must tend the embers. The grain barges at <span style=\"BandItPlus.Place\">Amitatys</span> are running a week behind because the river-warden is sick and his deputy is a fool. Caravan-masters out of the city are paying premium for overland hauliers and asking few questions about the cut they take on the way. <span style=\"BandItPlus.Name\">Old Heldar</span> who minds the <span style=\"BandItPlus.Place\">Khuzait grain-gate</span> drinks in the third hour after sunset, dependably, and his under-clerk goes home to a wife who hates him at the same bell. The ash drew a long curling line tonight — a road, and at the end of it, a door left open. That is what I saw. Eat your stew while it is warm, child. We do not waste meat in the cult of the hearth."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_222", "Lean close, and mind your sleeve don't sweep the embers. The secret isn't in the pot, it's in the hearth itself. Three days before I ladle a single bowl, I bank the fire with applewood from <span style=\"BandItPlus.Place\">Old Brenna's Copse</span>, then layer juniper green on top, then a fistful of dried mugwort the widow <span style=\"BandItPlus.Name\">Maire</span> taught me to braid backwards. The smoke that rises is sweet on the throat but it settles in the iron of the cauldron, and every bone broth I brew after sits steeped in that perfume for a moon-cycle. The stew tastes like it was cooked yesterday and last winter both. That's why the warriors pay fourteen <span style=\"BandItPlus.Coin\">denars</span> a bowl without flinching, where any common cook charges three.\n\nThe meat is the next trick, and here I'll wager you've never heard it. Lamb shoulder, never mutton, rubbed dry with hearth-ash sifted through a horsehair sieve. Hearth-ash, mind, not woodash from a clean fire pit. The ash from MY hearth, that's slept under nine years of cult-fires and a thousand offerings of fat and bone. There's salt in it, and char, and something my mother called the \"long savor.\" I rub the shoulder, wrap it in nettle leaves wet with cold milk, and bury it in the warm coals at the edge of the fire overnight. By dawn the flesh has gone the color of dark honey and falls apart under a wooden spoon. No knife touches my stew. Iron sours the omens.\n\nThe third secret is the broth itself. I crack the leg-bones lengthwise and roast them open-faced over <span style=\"BandItPlus.Place\">Black Stag Ridge</span> charcoal, then I quench them, still smoking, in a brine I've kept living for eleven years. I top it up, I never empty it. Every batch carries a spoonful of the last, the way a hearth carries every fire that came before. There's barley malt in there from the brewer at <span style=\"BandItPlus.Place\">Tan-Brae</span>, sea-salt I trade for with the smugglers, and the ground hip-bones of a stag my brother <span style=\"BandItPlus.Name\">Cathal</span> brought down the winter he didn't come home from. I won't pretend the grief doesn't season it. Some folk taste it and weep without knowing why.\n\nSo when you sit at my fire and the bowl warms your hands, understand you're not eating soup. You're eating nine years of smoke, eleven years of brine, and one brother's last hunt. The omens I read in the ash afterward? They're truer for the eating. The hearth knows what's been fed to it, stranger, and so do I."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_223", "The Hearth Took Me In"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_224", "Sit. The pot is warm and the smoke is honest, which is more than most men can say of their kin. My mother kept a bread-oven in a hamlet two days' walk from <span style=\"BandItPlus.Place\">Pen Cannoc</span>, and before I could lift a paddle she had me reading the ash — the way a curl of soot lifts off the stone when the loaves are right, the way it cakes flat when the gods are sour. She said the hearth speaks first and the priests speak after, and the priests only get coin for it.\n\nI was meant for the druid-grove at <span style=\"BandItPlus.Place\">Dunglanys</span>. I walked the road one autumn with a sack of barley meal and a wheel of goat-cheese tied at my belt, and a column of <span style=\"BandItPlus.Name\">Lord Caradros</span>'s riders cut the hamlet open behind me — burned the oven, scattered the millstone, salted the well so nothing would grow. When I came back the ash was cold and there was nothing in it to read. A man learns quickly that the gods will not feed him out of pity.\n\nI took to the smoke-trails after that. Three winters on a fish-curer's punt in the lochs above <span style=\"BandItPlus.Place\">Car Banseth</span>, hanging eels in juniper smoke until my hands stank so badly the dogs would not come near. Then a season on the salt-roads south, hauling crusted slabs from the pans for <span style=\"BandItPlus.Coin\">six denars</span> a load, eating dried mutton so hard it had to be chewed soft against the cheek before it would swallow. Trade keeps a man alive, but it does not keep him whole.\n\nThe camp found me, not the other way. I was reading the ash of a roadside fire — only a habit by then, mind, not a prayer — and a hooded woman sat across from it and named what I saw before I spoke it. She brought me up the gully with a sack of barley and a haunch of smoked boar and said the cult-pot wanted a hand that knew flour from filler. That was nine winters ago. The pot has not gone cold since.\n\nSo that is what pays a man into this trade. A burnt oven, a salt-road that took the feeling out of my fingers, and a hearth that still speaks when I am quiet enough to listen. Eat slow. The stew is venison and last-summer's roots and a handful of dulse from the coast, and the ash above the coals is reading well for you tonight — which is more than I can say for the next three I will serve."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_225", "What The Ash Whispers"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_226", "The hearth spoke loud last moon, and the road confirms it. A grain factor out of <span style=\"BandItPlus.Place\">Omor</span> is paying nine <span style=\"BandItPlus.Coin\">denars</span> the bushel for any rye that hasn't seen mould — twice the harvest price. The southron towns burnt their stubble too early and the seed-rats finished what the fire missed. If a brother of ours has rye buried, now is the season to dig it up.\n\nSalt-news from the long road: <span style=\"BandItPlus.Name\">Lord Caradoc</span>'s reavers turned over three pack-trains between <span style=\"BandItPlus.Place\">Car Banseth</span> and the coast, so the salt-houses there are holding stock and the price has crept. The cult's smokehouse will run thin by the next dark moon unless we trade for it inland. I told the headman to send a wain to <span style=\"BandItPlus.Place\">Pen Cannoc</span> instead — their priests still owe us a kindness from the drought-year, and they salt their pork heavy.\n\nSweetwine word is grim and good both. A Khuzait caravan-master, a fat one called <span style=\"BandItPlus.Name\">Demir of Quyaz</span>, lost two amphora-carts to a river-crossing near <span style=\"BandItPlus.Place\">Akkalat</span>; he is selling the surviving cargo at twenty <span style=\"BandItPlus.Coin\">dinars</span> the jar just to be rid of the wagon weight before the snows. A runner ought to meet him at the ford ere a townsman beats us to it.\n\nThe ash showed me cattle dying westward, and the drovers confirm it — a murrain creeps through the herds around <span style=\"BandItPlus.Place\">Pravend</span>, and the slaughter-yards are burning carcasses rather than selling meat. Dried venison and goat will fetch twice their weight there inside two moons. Tell <span style=\"BandItPlus.Name\">Old Cethyn</span> at the drying-racks to push the autumn cull early; we will eat well off other men's hunger.\n\nLast and least pleasant: a thin-faced grain-broker has been asking after our cookfires by name, in the inns near <span style=\"BandItPlus.Place\">Revyl</span>. He calls himself a chandler but he wears a town-guard's boots. Eat your stew tonight, brother, and say nothing of our routes to any traveller who asks too softly. The hearth knows a wolf-tongue before the lips have closed."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_227", "Acolyte Brennyn"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_228", "Hearth-Reader"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_229", "Tends the cult's offering-bowls and the goats they're filled from. Reads luck in spilled milk; serves it after, regardless of the reading. Says the bowl tells him who deserves the second cup."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_230", "Acolyte Brennyn, traveler. The bones called you a not-yet-friend on your last passage — that's Crone Vael's reading. Mine's in the milk-bowl. Bring me {BP_VENDOR_QUEST_DESC} for the offerings, and the bowl will read you fairer next pour."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_231", "The cult's offering-bowl reads luck, traveler — milk spills tell you who deserves second pour. The trick is the goat: same goat, three milkings per day, never the morning milk. Morning milk lies. Noon milk reads true. Empire would call it superstition; the bowl doesn't argue."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_232", "Name an offering, traveler — wedding-feast, name-day, mourner's pour. Three denars on the bowl, the goat does the rest. A milk-cup for tonight, no charge. The bowl says you've a name worth pouring for."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_233", "Mother was a hearth-reader before me — read luck for the Battanian lower-villages until the lord burned the hearth and the reader with it. I took the bowl from the ash; it still pours straight, against the wind. She'd be eighty winters now, if the lord hadn't done what he did. The bowl remembers her name."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_234", "Old Brigh keeps a bowl-shrine at the Battanian wood-line — same milk-trick, half the cult. Tell her Brennyn pours noon-milk still; she'll lift the wood-shrine's outer hide. Coin for her offering.")
        };
        private static readonly VendorProfile _cultGear = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_235", "Carver's hands hear what merchant tongues hide. A bone-knife trader from <span style=\"BandItPlus.Place\">Epicrotea</span> sat at my flensing-board last new moon and let slip that <span style=\"BandItPlus.Name\">Lord Vermion</span> of the southern marches is bleeding silver — his levy hasn't been paid in two seasons and he's quietly pawning his late wife's silver to a Khuzait pawn-broker for <span style=\"BandItPlus.Coin\">eighteen denars on the mark</span>. A lord that hungry sells safe-passage cheap. I traded the knapper a thumb-bone amulet for that, and I'd say I got the better end.\n\nThe steel-billet road through <span style=\"BandItPlus.Place\">Sanala</span> pass is running thin escorts this moon — six spears for forty mules, because the caravan master <span style=\"BandItPlus.Name\">Erkhan the Stout</span> bid the contract too low and can't afford proper outriders. Vlandian billets, Aserai pig-iron, fresh-folded steel meant for <span style=\"BandItPlus.Place\">Quyaz</span> smiths. The dead would furnish that road with little trouble, and the living would furnish themselves with enough iron to keep us in arrowheads through winter. I tell you this because antler runs short and good steel runs shorter.\n\nLeather, though — leather is glutted. Three tanner-caravans out of <span style=\"BandItPlus.Place\">Marunath</span> last fortnight, all begging coin at half the spring price because the Battanian hide-buyers cancelled their orders when the weaving-houses went bankrupt. A clever merchant in <span style=\"BandItPlus.Name\">Tovios of Pen Cannoc</span>'s pay is overpaying for raw oxhide at <span style=\"BandItPlus.Coin\">twelve denars the stack</span> — he means to corner the harness trade before harvest. Sell him yours, or take his. Either way the bones agree it's coin worth bleeding for.\n\nThe salt-routes I leave to you, but mark this: the smokehouses at <span style=\"BandItPlus.Place\">Phycaon</span> have run dry of barrel-salt and the grain barges out of <span style=\"BandItPlus.Place\">Charas</span> are sitting at quay because no lord will pay the toll. A man who moves salt north and grain south right now eats well till midwinter. The carrion-crow knows which field the plough turned last; I know which road the coin walks. Buy me a horn of mead and I'll mark them on the dirt for you."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_236", "Antler is patient where bone is proud. I learned this the hard way as a girl in <span style=\"BandItPlus.Place\">Hollow Bracken</span>, when my first knife shattered against a boar's shoulder and the boar nearly took my throat in return. The old knapper-priest who saved me, <span style=\"BandItPlus.Name\">Maerwynn</span>, made me sit three nights with the broken pieces before she would teach me anything. \"Listen to what it told you,\" she said. Bone tells you it is hard. Antler tells you it will bend before it breaks. The trick is knowing which lie to trust.\n\nSo I quarter every piece by season first. Winter-shed antler from a stag past his fourth rut — that is my blade stock, and I will not cut a single notch into it until the moon has waxed once after I bring it home. The marrow has to dry slow, in a clay jar packed with wood-ash and a fistful of rendered tallow at the bottom. Six weeks, sometimes eight. Cheaper smiths boil their antler to soften it for shaping; you can spot their work because the tines go grey and chalky inside a year. Mine stays the color of old honey. That alone is worth the extra <span style=\"BandItPlus.Coin\">eighty denars</span> on every dagger.\n\nThe edge geometry is where the rite enters the work. I rough the bevel against river-sandstone, but the final edge I bring up on the femur of whatever beast the blade is meant to kill — boar against boar, wolf against wolf, man against man. I keep a rack of them behind the curing jars. The grain of the polishing bone matches the grain of the killing bone, and the cut goes truer because of it. Whether you believe the dead furnish the living or you call it superstition, the arrows fly straighter from a quiver fletched on a deer's own shinbone. I have tested it across enough seasons to stake my name on it.\n\nWhat I will not sell, at any price, is the resin I bed the tang in. It is rendered down from three things: pine pitch from the <span style=\"BandItPlus.Place\">Iron Grove</span>, beeswax I take myself from a hive I have kept for nineteen years, and a small measure of ash from the pyre of every kinsman I have buried. <span style=\"BandItPlus.Name\">Maerwynn</span> went into the last batch four winters ago. When a hunter buys a blade from me, he is carrying a piece of my household into the wood. That is the price of the work — not the <span style=\"BandItPlus.Coin\">denars</span>, which are only how we keep score. The price is that the dead come with you, and they expect you to use what they have given."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_237", "The Dead Pay In Bone"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_238", "My first knife was my grandmother's shin. She bid me take it from her cairn the winter I turned ten — said her walking-bones owed me a trade, since she'd no milk to give when I was a babe. I knapped that shin into a skinning blade by the river behind <span style=\"BandItPlus.Place\">Pen Cannoc</span>, and when I drew it across a hare's belly I heard her humming. That was the day I knew the dead were not gone — only quieter, and willing.\n\nI was a fletcher's apprentice in the lowland villages for a span, gluing goose-quill to ash-shaft for two <span style=\"BandItPlus.Coin\">denars</span> the dozen. But the goose dies dumb, and the ash splinters under a wet bowstring, and my master beat me for praying over the offcuts. I left him in the night and walked the moor-paths until I found a barrow no plough had touched. I slept inside it three days. When I came out my hands knew the grain of antler the way a midwife knows a belly.\n\n<span style=\"BandItPlus.Name\">Lord Caradoc</span> of the moor-holds wanted me for his hall — offered a roof, a wife, a chair by the long-fire. I told him bone-work is no parlour craft. The bone must be raised where the rite is kept, and the rite is kept here, in the camp under the standing stones. So I walked out of his gate with my satchel of marrow-files, and I have not slept under a roof of sawn timber since.\n\nThe pagan-folk gathered me in because I asked nothing they could not give. Antler from their hunt, rib from their feasts, finger-knuckles from the elders who died well — these are my forge and my anvil both. I shape arrowheads that whistle the names of their ancestors as they fly. I shape ritual blades that cut clean because the bone remembers what it was for. Every edge I sell carries a debt to the one who wore it first.\n\nSo when you ask what pays a man into this trade, hunter, the answer is plain. The dead pay. They pay in their leavings, and they pay in their patience, and they ask only that I do not waste them. You will pay in <span style=\"BandItPlus.Coin\">denars</span>, because that is the living's currency — but mark me, the bone you carry from my mat will outlast your name, and one day some knapper will lift it from your cairn and owe you a knife in turn."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_239", "Bones Speak, Roads Listen"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_240", "The crow-roads are thick with news, friend, if you have an ear for it. A wright out of <span style=\"BandItPlus.Place\">Marunath</span> is buying every length of seasoned yew and ash he can lay hand to — fletching shafts for some southern lord who wants a thousand arrows by the wolf-moon. His runner offered me forty <span style=\"BandItPlus.Coin\">denars</span> the bundle for antler nocks. I told him sixty. He'll be back.\n\nThere is a smith-train moving up the old salt-track toward <span style=\"BandItPlus.Place\">Pen Cannoc</span> — three wagons of bog-iron blooms and a Vlandian master under guard. <span style=\"BandItPlus.Name\">Lord Caradoc</span> has emptied his coffers for new shield-bosses and spearheads, they say, because his housecarls grumble that their gear is older than they are. If you have a fast horse and quiet hands, that train sleeps light but drinks heavy.\n\nThe Battanian holdfasts in the high glens are taking on knappers again — bone, flint, antler, anything that does not sing under a hammer. The forest-lords learned that a bone arrowhead breaks off inside a man and the surgeons curse for a week. They pay in salt and silver both, and they ask no questions about where the marrow came from.\n\nWord from a peddler last quarter-moon: a caravan out of <span style=\"BandItPlus.Place\">Quyaz</span> is moving good steel-stock — wootz billets and Aserai files — bound for some merchant in <span style=\"BandItPlus.Place\">Pravend</span> who pretends he does not know the buyer. Forty <span style=\"BandItPlus.Coin\">denars</span> a billet on the open road, three hundred behind that merchant's door. The dead are patient. So am I.\n\nAnd one last thing, since you bought drink for the asking. There is a hedge-knight near the <span style=\"BandItPlus.Place\">Ortongard</span> woods who lost his saddle-bow and three good blades to a flooded ford, and he is offering coin to the first crafter who will ride out to fit him. I would go myself, but the bones in my pack have not finished speaking. Take it if you like — tell him Cadwen sent you, and he will not haggle past fifty."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_241", "Bone-Smith Cadwen"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_242", "Knapper-Priest"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_243", "Fashions the cult's ritual blades from elk-antler and meteoric iron. Says the bones tell him which strike-pattern each blade prefers; the ones he sells outside the cult are quieter, but they still listen."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_244", "Bone-Smith Cadwen. The mask told Vael you'd come; the bones told me what you'd ask. Bring me {BP_VENDOR_QUEST_DESC} for the next casting, and I'll knap you a blade the antler chose for your hand specifically."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_245", "Elk-antler doesn't flake like steel, traveler — you read the curl of the grain and knap with it, not against. Meteoric iron takes the bone-pattern; bone takes the iron-pattern. Both listen if you cast the bones first. Imperial smiths laugh. The Empire's mail still gets through the cult's antler-blades."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_246", "Bring me the bone you took yourself, traveler — elk, deer, mountain-cat — and an iron-bar. Six denars on the casting, the work's free. The bones'll tell me which strike-pattern. A small antler-spike for your belt tonight."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_247", "Daughter ran north at twelve to the imperial mission-schools — said the bowls were 'old foolishness.' I cast the bones over her name-day every year; the bones say she's alive, somewhere east. I forge a small antler-blade each casting. They're stacked in the back-shed. She'll come back for one. The bones don't lie."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_248", "Old Branwen at the Pictish bone-yard still knaps elk-antler the way her mother did. She remembers my mother's bowl; her bones cast the same pattern. Tell her Cadwen still listens to the iron; she'll show you the back-yard. Coin for the woman who carries you north.")
        };

        // ===== LOOTERS (Boll the Eldest's band) =====
        private static readonly VendorProfile _lootersFood = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_249", "A salt-mule out of <span style=\"BandItPlus.Place\">Zeonica</span> stopped here yestereve, mouth loose as a torn flour-sack once I'd wet his throat. Says the granaries in <span style=\"BandItPlus.Place\">Pravend</span> are half-empty — weevils in the winter store, and the bakers' guild paying <span style=\"BandItPlus.Coin\">38 denars</span> a bushel where it should be twelve. Twelve! My old master, may his ghost choke on chaff, used to flog 'prentices for buying at fifteen. There's a southbound grain train leaving <span style=\"BandItPlus.Place\">Sanala</span> on the new moon, oxen so weak the carter's walking beside 'em with a switch. Two guards. Two.\n\n<span style=\"BandItPlus.Name\">Hagan of Tyal</span> is the lord to watch — coffers dry as a summer well, I hear it from three separate tongues now. He's borrowed against next year's harvest twice already, and the wheat ain't even sown. Means his garrisons go thin, means his patrols sleep in, means the road from <span style=\"BandItPlus.Place\">Tyal</span> to <span style=\"BandItPlus.Place\">Ortongard</span> is a long quiet stretch of nothing 'til harvest-tide. And there's a fool merchant out of <span style=\"BandItPlus.Place\">Diathma</span>, calls himself <span style=\"BandItPlus.Name\">Kelben the Plump</span>, paying <span style=\"BandItPlus.Coin\">60 denars</span> a sack for fine-milled flour. Sixty! He thinks the famine's coming and he's hoarding for the spike. He'll be hoarding for nothing if we meet his cart first.\n\nSmokehouses are the other thing — three of 'em burned out west of <span style=\"BandItPlus.Place\">Marunath</span>, lightning the priests say, but I say a man with a grudge and a torch. Salt-pork's gone scarce, prices doubled, and the smugglers running barrels of cured ham up the <span style=\"BandItPlus.Place\">Vlandian</span> coast road are charging <span style=\"BandItPlus.Coin\">95 denars</span> a barrel and getting it. There's a thin-escort run of twelve barrels coming through the marsh-track next week. I'll sell you the bread to wrap 'em in when you're done.\n\nOne last morsel, since you're paying. Grain prices in the <span style=\"BandItPlus.Place\">Battanian</span> hills have collapsed — too good a harvest, nowhere to send it. Means the carters are running half-full back east, desperate for any cargo, taking on contracts they shouldn't. A desperate carter takes a desperate road. A desperate road takes a desperate guard. You see where I'm pointing? Good. Now buy a loaf or move along, I've a queue forming behind you."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_250", "Right. You want the secret? Lean in, then. The crust. It's all in the crust. Master <span style=\"BandItPlus.Name\">Halvad</span> back in <span style=\"BandItPlus.Place\">Pravend</span> — Reaper rest his throat — he taught me the dough but he never taught me the crust, that he kept locked behind his teeth like a coin. So I worked it out myself, after. After.\n\nTwice-bake is the trick of it. First bake is the loaf, proper, in a hot oven till the crumb sets. Then you pull it, slice it thick as your thumb, and back it goes onto the stones at half-heat for an hour, maybe two. Drives every drop of wet clean out. What you've got at the end ain't bread no more — it's hardtack, but better. Soaks up broth without turning to slop. Lasts a season in oiled cloth. A looter on the move can't carry soft bread, see. Soft bread moulds in three days and then you're chewing on green sorrow.\n\nThe other half is the dust. I keep a little crock of it — rye flour scorched black on a skillet, mixed with crushed juniper and a pinch of coarse salt. Roll the twice-baked rounds in it while they're still warm and the oils take the dust in. Tastes of woodsmoke and forest floor. The boys say it tastes of <span style=\"BandItPlus.Place\">Battania</span>, though half of them never been past the <span style=\"BandItPlus.Place\">Vlandian</span> tollgates. Charge eight <span style=\"BandItPlus.Coin\">denars</span> a round for the dusted, four for the plain.\n\nAnd no, I won't write it down. <span style=\"BandItPlus.Name\">Halvad</span> wrote his recipes down. Look how that went. A boy with a sharp paring knife found the page and then found the man, and now the boy sells bread in a wood with no master over him. Some lessons you only learn the once."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_251", "The Cedar Key, The Cut Thong"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_252", "Pravend smelled of yeast and piss the year I turned thirteen. I was apprenticed to a fat hog called Halver who beat me with the peel-handle every dawn for the crime of being slow with the kindling. He kept his flour locked in a cedar chest and slept with the key on a thong round his neck — which, looking back, was less precaution and more invitation. One night I cut the thong. I cut a little deeper than the thong required. I walked out of that bakery with a sack of milled white over my shoulder and the price of his life drying brown on my knuckles.\n\nI sold the flour by the cupful on the <span style=\"BandItPlus.Place\">Pravend</span>–<span style=\"BandItPlus.Place\">Lageta</span> road for a fortnight, until a constable's boy recognized the apron-stitch. Then I ran east, then south, then nowhere in particular. A man who has killed his master finds every honest hearth shut to him. I lived on stolen eels and fen-grain and the charity of women who didn't ask questions. Eventually you stop looking for an honest hearth. You look for a hearth that doesn't care.\n\nThis camp didn't care. The old Bread-Reeve before me was a Vlandian deserter with a bad lung, and when he coughed himself dead I stepped over the body and lit his oven before sundown. The boys ate that night, and the next, and that was the whole interview. I've been keeping the smokehouse since — salt-pork hung high, hearth-loaves down low, the dried river-eel for the lads riding the long patrols.\n\nI buy grain off whoever drives a cart down the wrong track. Sometimes it's <span style=\"BandItPlus.Name\">Lord Tomas</span>'s tithe-wagon, sometimes a miller's widow who knows better than to count the <span style=\"BandItPlus.Coin\">denars</span> twice. I pay fair and I pay quick, and I never ask where the sacks were stamped. That's the trade. That's the whole of it.\n\nWhat pays a man into this? A locked chest, a cedar key, and a master who didn't think the kindling-boy could lift a knife. The rest is just bread."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_253", "Word From the Crust"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_254", "Coin first, then the news. I keep two ears on every wagon that scrapes past the gully, and right now both of them are full. <span style=\"BandItPlus.Place\">Pravend</span> granaries are running thin — the reeves there are paying <span style=\"BandItPlus.Coin\">eighty denars</span> the sack for clean rye, and they aren't asking where it came from. A man with three sacks and a quiet mouth could ride home rich, or ride home dead. I've seen both, and the dead one usually had a louder mouth.\n\nThere's a salt train coming down from the lakes north of <span style=\"BandItPlus.Place\">Epicrotea</span>, six mules deep, run by an old Vlandian called <span style=\"BandItPlus.Name\">Girard of Three Fingers</span>. He doesn't pay tolls and he doesn't pay tribute, which means he pays in salt when somebody catches him — and somebody always catches him. If you're moving east, time your road to his. Salt keeps better than gold out here, and the cooks in this camp would slit a throat for a fistful.\n\n<span style=\"BandItPlus.Place\">Pen Cannoc</span> had a wet spring and the wheat is lying down in the fields. Word is the granary is going to come up short by harvest, and <span style=\"BandItPlus.Name\">Lord Caladog</span>'s bailiff has been quietly bidding on grain three valleys over. Famine before the snows, mark me. Buy your barley now, sell it to him in autumn at triple, and pretend you never heard a thing about where it sat in between.\n\nSweetwine caravan out of <span style=\"BandItPlus.Place\">Quyaz</span> turned west instead of east last fortnight — fat amphorae, southern stuff, the kind that makes a man honest before its time. Their guards are sellsword Aserai, six of them, and the lead drinks more of the cargo than he sells. I won't say more than that. I'm a baker, not a planner. But if a man with my flour came back with a jar of that wine, I wouldn't ask questions.\n\nLast bit. There's a smokehouse outside <span style=\"BandItPlus.Place\">Revyl</span> that lost its keeper to the bloody cough — sides of mutton hanging unsold, the widow taking <span style=\"BandItPlus.Coin\">half a denar</span> the pound just to be rid of it before it spoils. That's a week of camp suppers for the price of a bad meal in town. Someone with a cart and no conscience should be on that road tomorrow. Coin first, though. Always coin first."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_255", "Marn the Crust-Cutter"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_256", "Bread-Reeve"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_257", "Bakes from whatever flour the band's stolen that week. The crust is hard, the inside is grey, and Marn shares it with whoever sits at the fire — even Vlandian outriders who killed his last apprentice."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_258", "Marn the Crust-Cutter, friend. Boll lets you walk because Boll's afraid — that's an honest welcome. Mine's hungrier. Bring me {BP_VENDOR_QUEST_DESC} and the band eats once. That's all I can promise, traveler — but it'll be a meal."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_259", "Whatever flour the band's stolen, friend, you mix grey-wheat with brown-rye at three-to-two; the loaf rises against the odds. Imperial bakers refuse to mix the grades. That's why their bread goes hard by the second day, and ours feeds the band into the third."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_260", "Tell me what the band needs, friend — a wedding loaf, a fire-night feast, a death-watch. Two denars on the flour, a half-day on the rise. Crust off the morning loaf, no charge. We don't get many askers."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_261", "Had an apprentice — Beli, twelve winters when the Vlandian outriders ran the camp and took him for sport. They killed him, and I shared bread with one of them three weeks later because the band was hungry. I haven't slept right since. The bread still rises. That's the part I can't square."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_262", "Old Ulla bakes at the Pravend back-quarter under a butcher's sign — band-baker before the Reeve hired the column. Tell her Marn still mixes grey and brown; she'll seat you at the back-oven. Coin for her quiet.")
        };
        private static readonly VendorProfile _lootersGear = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_263", "Caravan out of <span style=\"BandItPlus.Place\">Battanian</span> hills come through last sevenday, axle groaning, escort thin as a beggar's broth. Three guards. Three. For sixty stone of <span style=\"BandItPlus.Place\">Battanian</span> billet-iron bound for <span style=\"BandItPlus.Place\">Pen Cannoc</span>. Driver tried to bribe me with a wineskin to look the other way — I took the skin AND the consignment manifest. Smith in <span style=\"BandItPlus.Place\">Dunglanys</span> is paying <span style=\"BandItPlus.Coin\">forty-two denars</span> a stone right now, up from twenty-eight last moon. Some lord's hoarding for a war nobody's announced yet.\n\nWord from the salt-road runners — <span style=\"BandItPlus.Name\">Lord Caladog</span> is short. Properly short. Garrison hasn't been paid in two moons and he's pawning his late wife's clasps to a fence in <span style=\"BandItPlus.Place\">Marunath</span>. His patrol pattern's gone ragged because he can't afford the oats. That stretch between the river-ford and the hill-shrine? Empty most dawns now. I don't say this twice, and I don't say it sober.\n\nLeather glut's the other thing. Some fool over in <span style=\"BandItPlus.Place\">Sanala</span> bought up three caravans of <span style=\"BandItPlus.Place\">Aserai</span> camel-hide thinking the price would climb — it crashed instead. He's offloading at <span style=\"BandItPlus.Coin\">eleven denars</span> a bale, hot and desperate. I traded him a salvaged khergit saber for two bales of grip-wrap last tenday. Came out ahead by a long stride. The patches I'm binding right now? Half of them are wrapped in his ruin.\n\nAnd grain. Don't get me started on grain. Smokehouse outside <span style=\"BandItPlus.Place\">Vostrum</span> burned to its stones — lightning, they say, but I know <span style=\"BandItPlus.Name\">Olek the Render</span>'s torch when I smell it — and now every smoked-pork merchant from here to the coast is overpaying for salt-cure to make up the loss. If you're moving south and you've got a barrel of rock-salt nobody's claimed, you bring it to me first. I'll route it through a man who'll pay double, and I'll only take a third for the knowing."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_264", "You want to know my trick? Fine. Costs you nothing, costs me nothing, because nobody else has the stomach for it. Most smiths quench in oil, or water, or fancy folk in <span style=\"BandItPlus.Place\">Sturgia</span> use brine they've blessed with some saint's name. Me? I quench in piss. Old piss. Three weeks in a covered crock under the forge, until it stinks like the devil's armpit and the salts have settled into a yellow sludge at the bottom. That sludge is what does it. The ammonia bites into the steel as it cools and leaves a skin on the blade harder than the heart of it. Brittle, sure. But these aren't blades meant to last. They're meant to last one swing longer than the poor sod swinging back.\n\nThe other half of the trick is the bind itself. I never forge-weld. Forge-welding takes a clean fire and patience and I have neither. What I do is I scarf the two pieces — say, a broken Vlandian arming sword tang and the snapped-off blade of some Battanian falx — and I peg them with a soft iron rivet through the joint. Then I wrap the seam in wet rawhide and let it dry tight. Looks like garbage. Holds for about forty good hits. After that, whoever's wielding it is either rich enough to buy a real one or dead enough not to need one. Either way, not my problem, eh?\n\nI learned the piss-quench from my da. He ran a back-alley forge in <span style=\"BandItPlus.Place\">Pravend</span> doing repair work for the city guard, except half the \"repairs\" were him melting down stolen guard kit and selling it back to them with a new pommel. Caught him at it eventually. Hanged him on a Tuesday. I was twelve. Took his tongs, took his apron, walked out the south gate, and I haven't slept under a roof I owned since. The piss-quench was the last thing he showed me, the night before the watch came. Said it was the secret that fed three generations of Patch-Irons. Said anyone who paid more than fifteen <span style=\"BandItPlus.Coin\">denars</span> for one of our blades was a fool and anyone who paid less was a friend, and we didn't have friends.\n\nSo there. That's the secret. Piss, rawhide, and a rivet. You want one? Twelve denars, no questions, no warranty, and if it breaks in your hand don't come crying — come bleeding, and I'll patch you together same as I patch the swords. <span style=\"BandItPlus.Name\">Grem</span> Patch-Iron doesn't turn away repeat customers. Living or otherwise."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_265", "Iron Remembers Every Owner"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_266", "What pays a man into this trade? Hunger, friend, and a steady hand for breaking other men's work apart. I was apprenticed once, proper-like, to a smith out past the back-lanes of <span style=\"BandItPlus.Place\">Pravend</span> — old fellow, hands like roots, taught me to read a blade by the singing it made on the anvil. He died owing rent. The guild took the forge, the tools, the door I'd carried coal through since I was nine. Left me the apron and a hammer with a cracked head.\n\nI went tinkering after that. Village to village, mending pot-bottoms and rivets for a bowl of stew. But there's no honest <span style=\"BandItPlus.Coin\">denars</span> in pot-mending when the harvest's thin and the lords are pressing tax. So I started buying broken from the carrion-boys — a snapped sabre here, a holed mail-skirt there — and learning to braid them back into something that could still take a throat. Patch-Iron, they called me on the road to <span style=\"BandItPlus.Place\">Quyaz</span>. Wasn't a compliment then. It is now.\n\nThe camp found me, not the other way round. I was sleeping in a culvert outside <span style=\"BandItPlus.Place\">Pen Cannoc</span> with two mauls and a sack of arrowheads when their scout-lad kicked my boot and asked could I mend a spear-haft by dawn. I mended six. They fed me. Next week I mended twelve, and the week after they brought me a wagon of dead men's belts and asked me to make them fit live men. I haven't slept in a culvert since.\n\nI'll tell you the truth of what I do, since you asked plain. None of this is mine — not the iron, not the leather, not the edge. Every piece on this rack walked off a body. I file the nicks out, re-strap the hafts, sand the blood out of the grain, and bind the bits that wandered apart back into something a man can swing. The forge spirits don't sing here like they did for the old master. But the blades still cut. That's all a fighting man needs, and that's all a fighting man can afford.\n\nSo that's what pays me in. Hunger first, then habit, then the quiet pleasure of work that nobody else will touch. Pick what suits your reach, hand me the <span style=\"BandItPlus.Coin\">denars</span>, and don't ask whose grip wore the leather smooth before yours. The iron remembers every owner. The smith forgets on purpose."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_267", "Word From The Ditches"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_268", "Word travels slow when you live in a ditch, but it travels. A pack-train rolled out of <span style=\"BandItPlus.Place\">Pravend</span> three nights back hauling bar-iron south — proper stock, not the rust I usually rivet. Outriders were thin. The lads who saw it counted six guards for twelve mules. Somebody is going to eat that caravan, and somebody after that is going to sell me the cut-offs for forty <span style=\"BandItPlus.Coin\">denars</span> a bundle.\n\n<span style=\"BandItPlus.Name\">Lord Galosh</span> out near <span style=\"BandItPlus.Place\">Car Banseth</span> paid a forge full of coin for new kite-shields last moon — boiled hide over green pine, painted before the glue set. Half of them will split by harvest. His sergeants already started buying replacements quiet-like, off-roster, off-ledger. That means battered shields walking back through the hills with no paperwork on them, and battered shields are my bread.\n\nThe <span style=\"BandItPlus.Place\">Quyaz</span> bowyers are short on horn again. Some southern war ate their supply, and now every steppe rider west of the river is paying double for a half-decent recurve. If you've got a stave that isn't cracked through the belly, drag it here before the next snow — I'll pay you better than a clan trader and ask half the questions.\n\nA scrap-runner came through yesterday whispering that <span style=\"BandItPlus.Place\">Revyl</span> is recruiting smiths. Real smiths, with their own tongs, for the lord's own armoury. <span style=\"BandItPlus.Name\">Old Hessa</span> the file-cutter packed up and went. Good for her. Bad for me — she was the only one nearby who could re-temper a sword spring without snapping it, and now every busted longblade in three valleys ends up on my anvil instead of hers.\n\nLast bit. There's a thief-camp two ridges east trying to move a crate of <span style=\"BandItPlus.Place\">Pen Cannoc</span> mail — proper riveted, lord's-mark stamped right on the collar. They want eighty <span style=\"BandItPlus.Coin\">denars</span> a shirt and they're nervous about it. Nervous sellers drop their price by sundown. If you're buying mail this season, wait two days and walk east. Tell them Grem sent you and they'll knock ten off just to be rid of the smell."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_269", "Grem Patch-Iron"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_270", "Bind-Smith"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_271", "Hammers broken farm-tools into knife-shapes by a fire that's barely a fire. His blades chip on the second cut, but they'll get you through the first — and Grem says that's all most fights need anyway."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_272", "Grem Patch-Iron, blade-bender. Boll's mercy got you in; my anvil's slower. Bring me {BP_VENDOR_QUEST_DESC}, and I'll bind you a blade that holds the first cut and prays through the second."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_273", "Farm-iron's brittle past the second cut, friend — the smelt was cold, the temper was a hope. I draw the blade thin at the spine, thick at the cutting-edge: the spine flexes instead of breaking. Holds the first cut. The second's a prayer. Most fights are first-cut anyway."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_274", "Bring me a broken plough-share or a snapped scythe, friend, and a name. I'll patch you a knife by next pass. One denar on the heat, nothing on the iron — you're bringing it. Here's a spare patch-blade for the road."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_275", "Wife and boy went into a Vlandian outrider's pyre — winter raid, the band scattered, they didn't run fast enough. I forge knives now and the knives know it. Each blade I bend bends a little for them. The band eats once. That's all I can promise. It used to be everything."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_276", "Old Hroth bends iron at the Pravend low-quarter back-alley — apprentice of mine before the band scattered. Tell him Grem still draws thin at the spine; he'll set up his anvil for you. Coin for his hammer.")
        };

        // ===== MOUNTAIN BANDITS (Skarvac's clan) =====
        private static readonly VendorProfile _mountainFood = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_277", "Aye, sit down on that barrel — careful, it leaks brine. The cellar's cool, the hams are hanging, and old Pavlos has a tongue loosened by his own smoke. You want gossip? I've got gossip salted and stacked like cordwood. A grain factor out of <span style=\"BandItPlus.Place\">Epicrotea</span> came through last sevenday, mule-thin and twitchy, paying me three times the going rate for a side of smoked pork because his master's larders are bare. Bare, mind you — in harvest month. That tells you the lord up there has spent his coin on something he shouldn't have, and the steward's covering with caravan-purchases at any price. If you've a wagon of barley sitting idle, point it at <span style=\"BandItPlus.Place\">Epicrotea</span> before the month turns. They'll pay <span style=\"BandItPlus.Coin\">eighty denars</span> a sack and not blink.\n\nSalt's the other story, and a worse one. The pans down at <span style=\"BandItPlus.Place\">Pen Cannoc</span> have been short three caravans running — bandits, weather, who knows, but the smokehouses from here to <span style=\"BandItPlus.Place\">Marunath</span> are sweating. I've had two cellar-masters write me begging for the rind-cuts I usually toss to the dogs. <span style=\"BandItPlus.Name\">Yorek of the Northvale</span>, the one with the cleft lip, told me over a cup that he paid <span style=\"BandItPlus.Coin\">forty denars</span> a measure for grey table-salt — grey, mind, the cheap stuff — and counted himself lucky. If a wagon of clean white salt rolled through the pass right now, the driver could name his price and three towns would fight him for it. Which means, of course, somebody's going to try moving one. And somebody else is going to try meeting that somebody on a quiet stretch of road.\n\nSpeaking of quiet stretches — the river-track between <span style=\"BandItPlus.Place\">Zeonica</span> and the lowland ferries is running with two guards per wagon. Two. I had it from a caravan-cook who shared my fire and my wine and didn't ask why I was asking. Their factor cut the escort because the season's been peaceful and the men cost <span style=\"BandItPlus.Coin\">twelve denars</span> a day. Smoked hams, oil, jarred fish, and — this is the part — a strongbox of trade silver for the lowland buyers. Two guards. Against whatever the woods decide to send. I'm not telling you what to do with that, friend. I'm a cellar-master. I smoke meat. But if a man wanted to know which road was thin this season, that'd be the road.\n\nLast thing, and then I'll let you eat. <span style=\"BandItPlus.Name\">Athas the Pedlar</span> — fat man, bad teeth, drives a green wagon — has been overpaying for any smoked goods he can find, and he's working a circuit through the high villages. He's got a contract with someone in the south, I'd wager a tournament-town caterer, and he's desperate enough that he doesn't haggle. If you bring me a clean piglet by week's end I'll smoke it for shares, and we'll sell it to <span style=\"BandItPlus.Name\">Athas</span> at his asking price, and he'll thank us with that ugly smile of his. The rock makes the meat better, I always say. The rock, and a cellar-master who keeps his ears open."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_278", "My grandfather dug this cellar with his own hands, you know. Forty paces into the limestone, where <span style=\"BandItPlus.Place\">the Spine</span> breathes cold even in high summer. The rock here — it sweats. Not water, exactly. Something else. A mineral breath that settles on the hams and pulls the moisture out slow, slow, the way a patient man pulls a secret from his wife.\n\nThe trick is the salt-pack, three layers. First, coarse rock-salt from the <span style=\"BandItPlus.Place\">Karod Pans</span> — the gray kind, never the white, never. Then crushed juniper berry and a fistful of dried bilberry leaf, which is my own addition; my grandfather used only juniper, but I caught a Battanian girl chewing the leaves once for her belly and thought, why not the meat? Then a second coat of salt, fine this time, ground in a hand-quern I keep oiled with sheep tallow. Forty days the ham sleeps in that pack. Not thirty-eight. Not forty-two. Forty. The cellar tells me when.\n\nAfter the salt, the smoke. Beech for the first three days — sweet, almost like honey at the back of your throat. Then I switch to mountain pine, but only the heartwood, never the resinous outer rings or the ham will taste like a torch. Six days of pine. Then one final day with a handful of dried mountain thyme thrown on the embers, which my mother taught me before the fever took her. That thyme day is what makes a buyer pay <span style=\"BandItPlus.Coin\">forty-two denars</span> for a hock when the lowlanders sell theirs for twelve.\n\nPeople ask me why I do not move down to <span style=\"BandItPlus.Place\">Ortongard</span> where the markets are richer. I tell them: the rock makes the meat. You cannot carry the rock. <span style=\"BandItPlus.Name\">Pavlos</span> stays where the cellar is, and the cellar stays where my grandfather put it, and that is the end of that conversation."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_279", "The Rock Remembers Salt"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_280", "My grandfather was a charcoal-burner above the pass at <span style=\"BandItPlus.Place\">Tyal</span>, and when the lowlanders burned his kiln he dug a cellar instead. Said the mountain owed him a roof if it would not give him trees. I was a boy with a clay lamp and a hand axe, and I helped him scrape the chamber wide enough to hang four hams from the rock.\n\nThe salt came up from <span style=\"BandItPlus.Place\">Pen Cannoc</span> by mule, twelve <span style=\"BandItPlus.Coin\">denars</span> a sack when I was small, thirty now if the trader is honest, sixty if he's not. I learned to read a ham the way a scribe reads a seal — by smell, by weight, by the way the rind hardens against the thumb. Mountain stone keeps the cold in summer and the damp out in winter, and that is half of curing. The other half is patience, which the lowlands do not teach.\n\nI came down once. Took service in a kitchen at <span style=\"BandItPlus.Place\">Ortongard</span> under a steward named <span style=\"BandItPlus.Name\">Cuno of the Three Knives</span>, who paid in coppers and beatings. When his lord lost a feud, the household scattered, and I walked back up the old goat-path with a sack of juniper berries and a head full of grudges. The cellar was still there. The rock remembers what men forget.\n\nThese boys here — they ride down, they ride up, sometimes they come back lighter than they went. They want meat that travels. I give them ham wrapped in birch-bark, hard cheese rolled in ash, a flask of pine spirit for the cold nights. They pay in <span style=\"BandItPlus.Coin\">denars</span> when they have them and in promises when they don't, and the promises mostly hold because a man who lies to the cellar-master eats badly all winter.\n\nSo sit. The grandfather's stone is under your boots and the hams are over your head, and that is what pays a man into this trade — a hole in the mountain, and the sense not to leave it twice."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_281", "Word From The High Passes"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_282", "Word on the road? Aye, sit closer — the wind eats half a man's voice up here. The mountain caravans out of <span style=\"BandItPlus.Place\">Epicrotea</span> have been hauling rock-salt south again, two wagons a fortnight, and the merchants there are paying near <span style=\"BandItPlus.Coin\">forty denars</span> a sack to anyone who can get it past the slopes. If you've got mules and a quiet route, that's silver waiting on a hook.\n\nThe hill-folk around <span style=\"BandItPlus.Place\">Pen Cannoc</span> are buying smoked mutton like a famine's coming — and one is, mark me. <span style=\"BandItPlus.Name\">Lord Caladog</span>'s levy stripped three valleys of breeding ewes for his winter march, and the shepherds left behind have nothing to lamb come spring. Grain'll spike by harvest-end, and the man with a full cellar will be a small king.\n\nThere's a Vlandian sweetwine train moving up through <span style=\"BandItPlus.Place\">Jaculan</span> — barrels marked with the <span style=\"BandItPlus.Name\">Hawcaster</span> seal, bound for some inland keep that pays in foreign coin. I've a cousin who watches that pass for the toll, and he says the guard is thin after the third bridge. A thirsty cellar-master would pay <span style=\"BandItPlus.Coin\">eighty dinars</span> a cask, no questions, no seal-marks read.\n\nAnd listen — the eel-smokers down at <span style=\"BandItPlus.Place\">Ortongard</span> have lost their hearth-master to the bloody flux, and their stock is rotting on the racks. Anyone who can ride down with cold-cured salt before the autumn fairs will buy three winters of meat for the price of one. My grandfather dug this cellar through living rock so the hams would hang sweet — I know spoilage when I smell it on the wind.\n\nThat's the word. Drink your cup, friend. The mountain keeps its own time, and the roads will still be there when you've eaten."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_283", "Pavlos Mountain-Tongue"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_284", "Cellar-Master"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_285", "Salts the venison the Pass-Lord's hunters bring in. Knows which slope yields the saltiest deer. Has never come down from the pass; says the mountain feeds him better than the lowland did when he was a boy."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_286", "Pavlos Mountain-Tongue. Skarvac took your toll-discount, traveler — the Pass-Lord's mood was generous today. The cellar's mood isn't. Bring me {BP_VENDOR_QUEST_DESC} and I'll salt you a haunch the imperial governor's table never tasted."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_287", "Mountain venison salts different than lowland, traveler — the salt sets in three days where the lowland needs five. The trick's the slope: north-face deer, never south. South-face flesh holds the heat too long; the salt walks the wrong way. The pass-lord eats only north-face."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_288", "Tell me the feast-night and the count, traveler — pass-toll wedding, name-day, governor's table. Three denars on the cellar-stock, sample haunch for tonight. The mountain doesn't furnish small quantities."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_289", "Came up from the lowland fifty winters back as a boy — left a younger sister at the foot of the pass, never went down for her. She'd be sixty now, if winters keep her. The mountain feeds me better than the lowland did. I tell myself she'd say the same. The cellar doesn't argue."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_290", "Old Spyros runs the foot-of-pass inn — keeps the mountain-salt trick for travelers willing to coin twice. He's my sister's son, by what the inn-folk say. Tell him Pavlos still salts north-face; he'll seat you at the back-table. Coin for the climb back up.")
        };
        private static readonly VendorProfile _mountainGear = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_291", "Caravan out of <span style=\"BandItPlus.Place\">Epicrotea</span> rolled through last week with three mules of half-finished steel billets bound for the lowland forges — escort? Four boys with spears and one drunk sergeant. I traded a sack of horseshoe nails for a sniff of what they carried, and let me tell you, the man fronting that shipment, a Vlandian factor named <span style=\"BandItPlus.Name\">Geirhard the Stout</span>, is overpaying by near forty percent. Word is he lost his last two convoys on the <span style=\"BandItPlus.Place\">Battanian foothills road</span> and now he panics, pays whatever the smelters ask. Anyone with a mule and a hammer could undercut him.\n\nIron stock is thin everywhere south of the pass — the <span style=\"BandItPlus.Place\">Sturgian mines at Revyl</span> sent only one wagon down this season instead of the usual three, and a smuggler called <span style=\"BandItPlus.Name\">Kettil Squint</span> told me it's because the local lord's debt collectors seized the ore-carts to settle a gambling marker. So if you're sitting on rough pig-iron, hold it. Price will double before the first thaw. The leather, though — gods, the leather. Every tanner from <span style=\"BandItPlus.Place\">Pen Cannoc</span> to the coast is choking on hides after that cattle-plague culled the herds early, and they're dumping cured calfskin for forty <span style=\"BandItPlus.Coin\">denars</span> a bundle.\n\nThere's a lord — won't say the name out loud, but he wears Aserai silks and rides a Vlandian charger, you'll work it out — who's so short on coin his armorer is melting down old tournament prizes to pay the smiths. His paychest is empty by the third week of every month, and his caravans run the <span style=\"BandItPlus.Place\">Onica-to-Hubyar road</span> with one outrider and a prayer. Three of my regulars have already worked out where to sit and wait. I don't ask what they bring back, I just ask what cut of the steel they want forged into billhooks.\n\nLast thing, and this is the one worth a flagon of arak: a Khuzait merchant named <span style=\"BandItPlus.Name\">Bayan Tsetseg</span> is buying salt at twice the going rate out of <span style=\"BandItPlus.Place\">Akkalat</span> — twice, friend — because the smokehouses east of the steppe lost their grain stores to mildew and now they're racing to cure meat before the cold sets in. He pays in raw silver, no haggling, no questions. If you can move salt and you don't mind a long ride, that's the easiest two hundred <span style=\"BandItPlus.Coin\">denars</span> a load you'll ever earn. Tell him Pass-Smith sent you and he might even throw in a flask of the good stuff."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_292", "Most smiths along the lowlands will tell you a blade wants slow heat and slower cooling. They are fools who have never worked above the snowline. Up here at the <span style=\"BandItPlus.Place\">Stone Shed</span> the air itself drinks the warmth out of the steel before you can blink, and if you temper by the colour of the metal the way the manuals say, you'll pull a brittle stick out of the slack-tub every time. So I read the smoke instead. Pine resin smoke off the forge throat — when it curls left and clings to the rafters, the steel is ready. When it goes straight up, the heart of the iron is still cold and you've got another two breaths to wait.\n\nThe trick I sell my edges on, though, is the quench. I keep two barrels under the bench. One is brine — coarse salt scraped off the goat-hide racks, dissolved in meltwater from the pass. The other is rendered mutton tallow with a fistful of crushed juniper berries stirred through it warm. A bandit blade gets the brine first for three heartbeats, then straight into the tallow until it stops singing. The brine sets the edge hard as glass, the tallow softens the spine just enough that it bends instead of snapping when you hook a shield rim. Old <span style=\"BandItPlus.Name\">Vasily</span>, my master down in <span style=\"BandItPlus.Place\">Rovalt</span>, would have called it heresy. He died of a snapped sword in his own hand, so I think I'll keep being a heretic.\n\nThe geometry I grind is my own as well. Most armourers put a convex bevel on a chopper for strength. Mine are hollow-ground a finger's width back from the edge and then convex behind that — a sort of hidden waist. It bites deeper into a gambeson because the hollow lets the wedge of the blade pass through the cut instead of getting pinched. Costs me an extra hour at the wheel per blade, which is why I charge what I charge. Eighty <span style=\"BandItPlus.Coin\">denars</span> for a hand-axe is highway robbery in <span style=\"BandItPlus.Place\">Epicrotea</span>, but up here a man pays it because the alternative is dying with a dull edge.\n\nI'll tell you the last secret for free, since you've stood through the whole sermon. The iron I use isn't bought. The caravans that come over the pass shed nails, hoop-bands, broken bridle-bits, the occasional snapped sword some fool didn't bother to pick up. My boys scrape the trail every spring melt and bring me the gleanings. I forge-weld it cold-shut in a billet of nine layers, fold it twice, and that's what becomes your axe. So when you swing it, remember — half a hundred merchants and dead men went into that edge before you did. Treat it like it has a memory, because it does."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_293", "What The Road Sheds"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_294", "My da was a wheelwright in a village two passes south of here, and he taught me the truth of iron before he taught me my letters — that a strap pulled cold cracks at the third bend, that a nail set wet rusts the wood around it, that an edge ground thin sings but does not bite. We worked the wagons coming down from the high country, and when the merchants of the lower towns paid us in coppers thinner than birch-bark, my da would smile and say the road still owed us. He died still owed.\n\nI went up to the pass-towns then, looking for honest forge-work, and I found it for a while under a master in a shuttered yard near the market road — a quiet man who let me hammer out the rough billets while he did the finish-edges. When the levies came through and took him for a kingdom-debt I could not name, I took his anvil on my own back down the goat-tracks and kept walking. An anvil weighs what a man weighs. I know, because I carried mine the same distance my master carried his name.\n\nThe camp found me before I found it. I was sleeping in a stone shed where the snow gathers thin, and a rider came up at first light with a broken cheek-strap and a horse going lame, and he asked what I wanted for the fix. I said pass-iron — whatever scrap the caravans had dropped on the switchbacks below, brought up to me by the basket. He laughed, and the next morning there was a basket. The morning after, two.\n\nSo that is the bargain, friend. The riders bring me what the road sheds — broken pot-iron, snapped saddle-buckles, a cracked sword-tang from some boy who thought he was a swordsman down by <span style=\"BandItPlus.Place\">Pravend</span> — and I give them edges that hold and straps that do not crack at the third bend. Coin moves through here too, sure, <span style=\"BandItPlus.Coin\">denars</span> when a man has them, but iron is the older currency and I trust it further.\n\nI am not proud of every blade I have set a handle to. But I am proud of the work. A strap pulled warm, a nail set dry, an edge ground to bite — that much I still owe my da, and I pay it every morning I light the forge."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_295", "Word From The High Pass"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_296", "Caravan-talk drifts up the switchbacks before the snow does, traveller. Word is the garrison at <span style=\"BandItPlus.Place\">Chaikand</span> is buying every shield-blank a smith can hammer flat — <span style=\"BandItPlus.Name\">Lord Ürkhün</span> lost half his round-targes to a steppe skirmish and his armourers can't keep the rivet-line moving. If you've a wagon of poplar boards and rim-iron, that's <span style=\"BandItPlus.Coin\">eighty denars</span> a shield, no questions about where the steel came from.\n\nThere's a steel-stock train climbing the <span style=\"BandItPlus.Place\">Onika</span> road right now, six mules deep, bound for the foundries at <span style=\"BandItPlus.Place\">Quyaz</span>. Imperial ingot, the heavy grey kind that rings clean off the anvil. They march light because the snow's late this year and they think the high passes are quiet. They are wrong about that, but I did not say so.\n\nDown on the lowland circuit, <span style=\"BandItPlus.Name\">Lord Pelle</span> paid out for two hundred kite-shields and a fresh stand of spear-heads — coin came from selling off his late brother's racing string, they say. His smiths at <span style=\"BandItPlus.Place\">Pen Cannoc</span> are turning away apprentices, so any journeyman wandering this way has nowhere honest left to go. Some of them end up at my shed. Some of them end up worse.\n\nA Vlandian buyer was through here a fortnight back hunting for blackened mail and helms of any cut, paying <span style=\"BandItPlus.Coin\">sixty dinars</span> a coat and not haggling. He never said which border lord he served, and I never asked. If you've war-spoil rusting in a saddlebag, you bring it to me before the snow closes the gap — I'll move it down the chain and we both eat.\n\nLast thing, and mark it. The forge-town at <span style=\"BandItPlus.Place\">Revyl</span> is short on charcoal and shorter on hands — old <span style=\"BandItPlus.Name\">Master Hjalmar</span> died at his bellows last month and no one's stepped to the hammer. Anvil-iron's gone scarce all the way to the coast because of it. Pass-iron, pass-price. Both fair. Bring me scrap and I'll cut you a piece worth carrying."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_297", "Kostas Anvil-Hand"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_298", "Pass-Smith"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_299", "Repairs imperial mail with mountain-iron — the kind that takes three more strokes to set right but holds three more strokes longer. His repairs outlast the originals, which Skarvac says is why the imperial patrols keep losing."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_300", "Kostas Anvil-Hand, Pass-Smith. The Pass-Lord lets you walk; the anvil decides whether you carry. Bring me {BP_VENDOR_QUEST_DESC} from the lowland forges, and I'll repair you mountain-mail that holds against three more strokes than imperial issue."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_301", "Mountain-iron takes three more strokes to set than imperial issue, traveler — the ore's tighter, the grain runs wrong, you fight it for the first half-hour. After that it holds three more strokes longer than anything Aserai-side. The patrols keep losing. They don't know the count of strokes."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_302", "Bring me a broken pass-blade, traveler, and a draw — I'll re-temper you mountain-iron the lowland forges don't know how to copy. Six denars on the heat, the iron's already paid. Here, a spare wedge for your belt."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_303", "Father worked the same anvil; grandfather, the same again. Three brothers — two went down for the imperial recruiters' bounty, one stayed. The two never came back; the third drinks too hard now. The anvil's mine because the anvil chose. The lowland chose the others."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_304", "Find Old Theodoros at the Aserai dye-quarter forges — apprentice of mine before the southern war. Tell him Kostas still strikes the mountain-count; he'll show you the back-anvil. Coin for the desert.")
        };

        // ===== STEPPE BANDITS (Ulan Twice-Banished's band) =====
        private static readonly VendorProfile _steppeFood = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_305", "A caravan limped in past dusk with their axles squealing fit to wake the wolves, and the headman, one <span style=\"BandItPlus.Name\">Tariq of the Soft Hands</span>, paid eighteen <span style=\"BandItPlus.Coin\">denars</span> a sack for the mouldy barley I had been feeding the goats. Eighteen! The smokehouses out by <span style=\"BandItPlus.Place\">Quyaz</span> have all gone cold, you see, on account of the salt-train from the southern flats never showing its face this moon. No salt, no smoked mutton; no smoked mutton, and every cook from here to the coast is buying grain like the locusts are due tomorrow.\n\nNow I sat that soft-handed fool down with a bowl of mare's milk and let him talk himself dry. Says the road from <span style=\"BandItPlus.Place\">Sanala</span> to the eastern fords has but four spearmen and a one-eyed crossbowman guarding three wagons of hard cheese and pressed curd. Four! In my grandfather's day you would not move a basket of dung past the cairns with fewer than twenty. And he says <span style=\"BandItPlus.Name\">Lord Vlachus</span> is so short on coin he sold his wife's silver to pay his garrison last fortnight, which means his patrols on the western salt-road will be thin as broth for the next two moons.\n\nThe boy who tends his ponies let slip something even tastier while pretending to admire my cheese-press. A grain factor out of <span style=\"BandItPlus.Place\">Onira</span>, a fat one called <span style=\"BandItPlus.Name\">Eshmun the Weigher</span>, is paying twenty-six <span style=\"BandItPlus.Coin\">denars</span> the bushel for any oats he can get his pudgy fingers on, because his contract with the city watch comes due before the snows. Twenty-six! You could load a string of mules with mouldy fodder from the floor of any abandoned barn and ride home a rich man, if you had the stones to brave the road and the wits not to talk about it in the wrong ger.\n\nSo when you ride out, ride east before the cheese-wagons get to safer country, and ride hard. And mind, when you come back, the salt-prices will only have climbed higher, so save me three handfuls from whatever you cut loose. A man my age cannot eat unsalted curd forever, the steppe was greener once and the cheeses were softer, and Old Ozcin remembers."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_306", "The secret, child? It is the bag. Not the milk, not the mare, not even the season — the bag. Mine is mare-stomach, scraped with a flint not a knife, never washed with water from a running stream. Running water carries spirits that sour the starter. I rinse it only with the rain I catch in <span style=\"BandItPlus.Place\">Sharir's Hollow</span> after the first hard frost. That rain is sweet. River rain is jealous.\n\nFor the kurut — the hard cheese the riders take into the long grass — I press it in a sling of horsehair, not cloth. The hair lets out the whey but keeps the salt-skin tight. I salt twice: once with the rough grey crystal we pick from the lick-stones near <span style=\"BandItPlus.Place\">Tulga's Bend</span>, then again three days later with crushed wild garlic-root burnt black on a flat stone. The second salting is what makes my cheese keep for a year on the saddle. Other women salt once and weep when it moulds by midsummer. I do not weep.\n\nThe mare-milk drink — the koumiss the boys swagger over — I do not stir with wood. Wood drinks the sour. I stir with a horse's rib, dried two winters in the smoke-hole. My mother stirred with her mother's rib for forty years; when she passed, I burned hers proper and started mine fresh from a grey mare I rode as a girl. The rib remembers the rhythm. The bag, the salt, the rib — these are the three things. Anyone who tells you otherwise is selling you a flat sour drink for the price of a fat one.\n\nI will sell you a skin of koumiss for thirty <span style=\"BandItPlus.Coin\">denars</span> and a wedge of kurut for fifteen, and I will not tell <span style=\"BandItPlus.Name\">Bayan-Khor</span> you asked about the rib. He thinks I learned it from a Khuzait trader and it pleases him to think so. Let him think so. The steppe was greener then, and a woman could keep her own secrets without a chief deciding they were his to know."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_307", "Mare-Milk and Long Memory"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_308", "A boy on the long grass learns the herd before he learns his own name. I rode behind the khan's mares before I could grip a bow, counting foals at dawn, salting hides at dusk. My father was no warrior — he was the man who knew which spring still ran in the dry month, and which marmot warren had grown fat. He taught me that a camp dies of empty bellies long before it dies of empty quivers, and that lesson has fed me every winter since.\n\nWhen the old khan fell on the road below <span style=\"BandItPlus.Place\">Quyaz</span>, the herd scattered and the clansmen scattered with it. I drove what mares I could north, traded the lame ones for salt at a Sturgian post, and salt for smoked river-eel from a fenman who owed my father a favor. I have been moving food along that crooked line ever since — grain from <span style=\"BandItPlus.Place\">Pen Cannoc</span> when the borderlords are sleeping, hard cheese off the Khergit shepherds, dried mutton I cure myself in a pit behind the wolves' tents.\n\nThis camp took me in because I knew the old way of the kumis — three days of beating, the right cradle of felt to keep the skin warm, the trick of the second souring that turns mare-milk to a drink that lasts a campaign. I keep the hard cheeses too, pressed between river-stones and salted from the lick-flats out past <span style=\"BandItPlus.Place\">Iuteus</span>. A raider can ride a week on a fistful of that cheese and a strip of dried horse — and the boys here ride hard.\n\nI do not ride out with them. My knees gave up that road long winters ago. But every man in the camp eats from my hand once a day, and pays me in coin or in trade-skins, and that is exchange enough. Steppe gives, steppe takes — and Old Ozcin stands at the gēr-door with a ladle, keeping the balance."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_309", "Word From The Long Grass"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_310", "Sit. The kumis is in the skin by your knee — pour your own, I'm too old to lean. You ask for the word on the road, and the road has been talking. Riders came through three nights back, hooves still hot, and they paid for cheese in <span style=\"BandItPlus.Coin\">dinars</span> minted in <span style=\"BandItPlus.Place\">Quyaz</span>. That tells me the southern khans are flush again, and flush khans buy salt before they buy swords.\n\nSpeaking of salt — <span style=\"BandItPlus.Place\">Odokh</span> market is paying double the spring rate. Their smokehouses ran dry curing horseflesh for the warband <span style=\"BandItPlus.Name\">Urkhun Khergit</span> is pulling together east of the river. If you've got brick-salt to move, take it there before the moon turns, not after. After, every petty trader on the steppe will have heard, and the price will fall like a stone in a well.\n\nA sweetwine caravan out of <span style=\"BandItPlus.Place\">Pravend</span> is wandering the trade-track to <span style=\"BandItPlus.Place\">Pen Cannoc</span> — three wagons, two guards too drunk to count their fingers. The drover is a fat southerner called <span style=\"BandItPlus.Name\">Astrades</span>, and he overpaid for his hires. He'll be on the bend past the salt lake in maybe ten days. I am only telling you what I heard. What you do with hearing is your own steppe.\n\nNow the bad word. Grain is going to bite hard come the cold moons. The <span style=\"BandItPlus.Place\">Quyaz</span> harvest was thin — the millet went brown on the stalk, and the river ran low for the second year. I have seen this before, boy. When the granaries up there start hoarding, the villages down here start eating their seed-stock, and then come spring there is nothing planted and the children start dying. Buy your grain now. Buy more than you think. I am stacking sacks behind the gēr-wall and I do not care who calls me a miser.\n\nLast thing. There is a Vlandian wine-merchant asking after dried mare-meat in <span style=\"BandItPlus.Place\">Onira</span> — he wants it for some lord's hunting feast, will pay in silver and ask no questions about where the horse came from. If you have a string of poor ponies you would rather not explain, that is your road. I'll trade you a wedge of hard cheese for the news of how it goes. Steppe gives, steppe takes. So does Old Ozcin."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_311", "Old Ozcin"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_312", "Gēr-Steward"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_313", "Pitches Ulan's tents, dries his meat, brews his kumis. Has followed Ulan through both banishments and the one return that didn't take. Says the gods sent guests for a reason, and Ozcin has fed every one of them."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_314", "Old Ozcin, gēr-steward to Twice-Banished Ulan since the first banishment. Ulan's hand is open to you, traveler — the gods sent you. The cookpot's fussier. Bring me {BP_VENDOR_QUEST_DESC} and you'll eat at our fire the same as the Khan's branch used to."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_315", "Khuzait kumis ferments three days in the gēr-leather, never the wood barrel, traveler — wood spoils the bite. The leather breathes; the leather knows. Imperial vintners try wood and call it 'kumis-equivalent.' The Khan would spit. Has, twice."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_316", "Tell me the camp-count and the rite, traveler — name-day kumis, wedding-stand, mourner's pour. Three denars on the leather, a fortnight on the ferment. A horn-cup for your road-stew tonight."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_317", "Sons both ride with Ulan — the eldest at the right hand, the youngest at the second-pony. Wife died at the second banishment; the cold took her. The gods sent us guests to feed, so we kept feeding. The hand grew strong from the pour. That's how it goes."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_318", "Khentii Wind-Stand keeps the Khan's-branch yurts — knew Ulan before the striking-off. Tell him Old Ozcin still ferments in leather; he'll set the gēr-flap aside for you. Coin for the long ride.")
        };
        private static readonly VendorProfile _steppeGear = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_319", "A trader out of <span style=\"BandItPlus.Place\">Makeb</span> wintered with us last moon, his cart axle split, his tongue loose from too much fermented mare's milk. He let slip that <span style=\"BandItPlus.Name\">Khuzait noyan Urkhun</span> is hauling a steel-billet caravan up the <span style=\"BandItPlus.Place\">Amitatys</span> trail with only six horse-archers riding flank. Six. For nine hundred weight of Sturgian billet bound for the <span style=\"BandItPlus.Place\">Ortongard</span> smithies. The man practically drew me a map between belches, and I drew my own conclusions while he slept it off.\n\nThe leather glut out west is the other piece worth knowing. <span style=\"BandItPlus.Name\">Tanner Bayazid</span> at <span style=\"BandItPlus.Place\">Quyaz</span> overbought hides after the Aserai cull and now he's dumping cured cow at twelve <span style=\"BandItPlus.Coin\">denars</span> the bundle when last spring it was thirty. Smugglers running south through the <span style=\"BandItPlus.Place\">Dirigh Aboard</span> dunes pay near nothing for it. Means every bow-grip I wrap costs me half what it did, and I'm passing none of that to you, friend. A man has to eat.\n\nBetter piece yet, <span style=\"BandItPlus.Name\">Lord Monchug's</span> bannermen haven't been paid in two market-rounds. Heard it from a salt-runner whose cousin rides with their levy. They're selling sinew and horn off their own remounts to make ends meet, which is how I got my last three bundles of bull-horn for <span style=\"BandItPlus.Coin\">forty denars</span> the lot. If you're hunting a lord who can't keep his retinue's loyalty come winter, that's your man.\n\nGrain's the only sour note. Smokehouse at <span style=\"BandItPlus.Place\">Chaikand</span> burned to the foundation last waning moon, and the caravans that used to glaze their meat there are now overpaying <span style=\"BandItPlus.Name\">Salt-Captain Nogai</span> for preserves out of <span style=\"BandItPlus.Place\">Dunglanys</span>. Grain followed the salt — both up by a third. Tells me the bow trade is steady but I'd not buy bread on credit this season. Now. You want the recurve, or the long-draw?"),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_320", "Hai, you ask the old bow-wright his secret? Sit. The horn is the bone. The sinew is the muscle. The wood is just the spine that holds them quiet between shots. Most fools in the lowlands glue all three with hide-cement and call it done in a moon. The bow splits in a hard winter and they curse the steppe. I cure mine eighteen months, sometimes twenty. Belly of mountain-sheep horn, scraped down with a goat-tooth scraper until it sings flat against my thumb. Back of sinew from the back-strap of a long-running mare, never a stall-fattened beast — a mare who has run knows how to spring back. Core of mulberry from <span style=\"BandItPlus.Place\">the South Bend</span> only. Birch breaks. Maple lies. Mulberry remembers.\n\nThe trick that no Imperial fletcher will ever copy: I boil my fish-glue with crushed millet husk and a pinch of the white salt from <span style=\"BandItPlus.Place\">Lake Vagosh</span>. The husk gives it tooth, the salt keeps it from going soft in summer rain. When I lay the sinew, I chew each strand first — yes, chew — until my own spit softens the bundle. Then it lays flat on the back and dries into the wood like it grew there. The Khergit master who taught me, <span style=\"BandItPlus.Name\">Old Boroldai</span>, said a bow that has not tasted its maker's mouth is just a stick. I was nine years old and I thought he was being cruel. Now I am fifty and three, and I have not made a bow any other way.\n\nThe last secret is the binding. After the sinew sets I wrap the grip in horse-tail wound against the lay of the hair, never with it. Goes on dry, tightens as it cools. Foreign buyers ask why my bows cost three hundred <span style=\"BandItPlus.Coin\">denars</span> when the Vlandian crossbowyer down the road sells for ninety. I tell them: his bow will kill a deer at fifty paces this autumn. Mine will kill a deer at a hundred paces, every autumn, for the next forty winters. My father's bow still hangs in my brother's ger. He died with it across his back at <span style=\"BandItPlus.Place\">Two-Rivers Pass</span> when I was twelve. The horn is yellow now and the sinew has darkened like old honey, but the draw is still thirty-eight pounds at twenty-eight inches. Test it yourself when you ride east. Tell my brother Tergel sent you. He will not weep, but he will pour you the good kumis.\n\nSo. You still want to buy one, or did you only come to learn?"),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_321", "Horn, Sinew, Honest Hands"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_322", "What pays a man into this trade? The bow does, friend. My grandfather bent his first stave when he had no beard, and I bent mine before I had teeth enough to chew dried curd. We are bow-wrights of the eastern grass — no forge, no anvil, no clatter of hammers. A length of mountain-goat horn, the back-strap sinew of an old gelding, a slab of birch for the core, and patience enough to wait through a winter while the glue cures. That is all a man needs to put death at three hundred paces.\n\nI learned the craft in my father's ger, west of <span style=\"BandItPlus.Place\">Quyaz</span>. We rode for old <span style=\"BandItPlus.Name\">Urkhun Khan</span> in those years, and his archers carried our staves into every skirmish along the river road. A good composite takes two summers to finish — horn glued in spring, sinew laid in autumn, the whole thing tillered slow through the cold so the layers learn to breathe as one. Rush it, and the bow blows apart on the third draw and takes a man's eye with it. I have seen that. I do not rush.\n\nThe trade brought me here through a poor bargain. A Vlandian factor out of <span style=\"BandItPlus.Place\">Pravend</span> paid me sixty <span style=\"BandItPlus.Coin\">denars</span> for a dozen finished bows and then sold them on for six hundred to his own knights. I rode after him with a half-strung stave across my saddle. I did not catch him. What I caught was a writ on my head and a long ride east into country where writs do not travel. The chiefs here took me in because every camp needs a man who can fit a string and cut a nock straight.\n\nSo now I bend horn for the riders who shelter under this ridge. I take the sinew they bring me off the steppe ponies, I take the goat-horn from the mountain hunters, and I make bows that throw a heavy arrow through mail at sixty paces. The price is fair if the buyer is fair. I have no use for a man who haggles by lamplight and then says my draw weight is light at noon. Bow shoots true if the buyer is true. Be honest, and you will leave my stall with a stave that outlives your sons."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_323", "Word From The Long Tracks"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_324", "Word came down the Volga track last moon — <span style=\"BandItPlus.Name\">Khuzait Khan Monchug</span>'s outriders are buying every horn bow they can find for the <span style=\"BandItPlus.Place\">Quyaz</span> levies. Pays in fresh <span style=\"BandItPlus.Coin\">denars</span>, not shaved coppers, and asks no questions about the maker's mark. I've sent two dozen east already, and the courier swore the khan's quartermasters wanted twice as many.\n\nThe <span style=\"BandItPlus.Place\">Pen Cannoc</span> woodyard is short on yew this season — frost split half their winter cull, and the Battanian fletchers are sniffing around steppe traders for laminated horn-and-sinew instead. Won't last; their pride won't let them buy \"easterner sticks\" for long. But while the desperation holds, a clever runner moves stock north and comes back with <span style=\"BandItPlus.Coin\">denars</span> heavy enough to drag the saddle down.\n\nA Khergit caravan out of <span style=\"BandItPlus.Place\">Tulga</span> dragged itself in three nights past, all dust and broken axles. They had sinew — good sinew, ox-back, the long stuff — and traded it cheap for water and a dry place to sleep. I bought the lot. So if you're after a stave that won't crack come dry season, you came to the right tent at the right moon.\n\nHear this too — <span style=\"BandItPlus.Name\">Lord Urkhun</span> in the south steppes lost his master bowyer to a cough, and the man's apprentice is too green to draw a war-weight stave. Word is the lord's offering forty <span style=\"BandItPlus.Coin\">denars</span> a day plus quarters for any wright who can fit out his druzhina before the spring raid. I won't go — I've ridden enough lords' camps to know how those tales end — but a younger pair of hands might do well there.\n\nLast bit, no charge: don't take steel-tipped shafts west through the <span style=\"BandItPlus.Place\">Pravend</span> highway. Imperial customs hanged two arrowmongers last month, called them munitions-runners. Take the goat tracks south of the river. Slower, but the buyer is true at the other end."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_325", "Tergel Bow-Wright"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_326", "Bow-Master"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_327", "Strung horsebows for the Khan's branch before the branch struck Ulan's name from its rolls. Strings them now for whoever pays. Khuzait still — you can hear it in the way he flexes the staves before sale."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_328", "Tergel Bow-Wright. Ulan's word is good; my horn-glue is better. Bring me {BP_VENDOR_QUEST_DESC} and I'll string you a bow that makes the imperial recruiter's stomach turn at fifty paces."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_329", "Khuzait horsebow takes the horn-glue at three layers, not the imperial-issue two, traveler — that's why a Khuzait bow holds the draw through a campaign's worth of weather. Imperial recruiters can copy the curve. They can't copy the glue. They've stopped trying."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_330", "Bring me a draw-weight and a horse-height, traveler — I'll string you a bow that turns the imperial recruiter's stomach at fifty paces. Four denars on the horn, a fortnight on the glue. Spare string for your current bow, no charge."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_331", "Father was a bow-wright in the Khan's branch; his name was struck from the rolls the same day Ulan's was. He drank himself into the steppe at sixty-three. I keep his glue-pot on the bench. I haven't used it in twenty winters. I open it once a year on the name-day to check the smell. It still holds."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_332", "Old Erdene strings bows at the Salp river-camp — apprentice of mine before the strikings. Tell her Tergel still lays three layers; she'll show you her glue-stock. Coin for the ferry.")
        };

        // ===== SEA RAIDERS (Bjornulf Salt-Tongue's hall) =====
        private static readonly VendorProfile _seaFood = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_333", "Sit, sit — mind the net, I'm halfway through this knot. You want gossip? I salt fish for a living, friend, and salt is half the news of the coast. Every smuggler what beaches a skiff to refill brine barrels leaves me three rumours for one barrel, and lately the barrels have been thin.\n\nWord off a Vlandian runner two tides back — grain out of <span style=\"BandItPlus.Place\">Pravend</span> is fetching near forty <span style=\"BandItPlus.Coin\">denars</span> the sack inland, on account of the smokehouses at <span style=\"BandItPlus.Place\">Jaculan</span> shutting down. Three of 'em, all at once. Cooper's son took ill, the brine-pits soured, who knows. Point is — no smoked herring moving north, which means salt-pork's gone scarce, which means any caravan dragging barrels of cured anything is worth twice what its escort's paid to guard it. And the escorts? Thin. <span style=\"BandItPlus.Name\">Lord Derthert</span>'s pulled half his hearthmen east for the border, so the coast road between <span style=\"BandItPlus.Place\">Sargot</span> and the bay's running with four spears where it used to run with twelve.\n\nThere's a fat <span style=\"BandItPlus.Name\">grain-factor named Olbas</span> overpaying for anything salt-cured — paid sixty the sack last fortnight, paid eighty this one. He's contracted to feed a garrison and the garrison won't wait. Smugglers say he's holed up at <span style=\"BandItPlus.Place\">Rhotae</span> sweating into his ledger. And — this one's gold — <span style=\"BandItPlus.Name\">Count Laudavix</span> is short on coin. Pawned his wife's gulls-eye brooch, the runner swore on his mother. Means his patrols ain't getting paid, means his patrols ain't patrolling.\n\nSo here's the sea's verdict, friend, and I trust the sea more than I trust any man on it: somewhere between <span style=\"BandItPlus.Place\">Sargot</span> and the smokehouse-empty north, a brine-barrel caravan is rolling toward Olbas's purse with four tired spears around it. I'd not say where exactly. I just knot nets. But the tide goes out tomorrow at the third bell, and a small boat could be at the coast road by dusk."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_334", "The brine I cure my hold-fish in is no secret to any sea-wife who's salted her man's catch — but the second wash is mine, and I'll thank the sea I learned it. After the first three days in heavy salt, I pull the fillets, rinse them in cold seawater drawn three leagues out from any river-mouth, then lay them back in a fresh barrel with the salt cut by a fifth and a fistful of crushed juniper-berry mixed in. The juniper kills the rot that creeps in past day twelve, and it leaves a sharp green smell on the fish that the crew swears keeps the gulls off the rigging when they eat on deck.\n\nThe trick — and this is the part I don't say aloud at <span style=\"BandItPlus.Place\">Sargot</span> market when the fishmongers come sniffing — is that the second-wash brine must sit one full tide-cycle in a copper-bottomed cask before the fish goes back in. Copper, not iron, not wood-lined. The brine goes faintly blue and tastes wrong on the tongue, but it kills whatever sickness the gut-strings leave behind, and a barrel cured that way will feed a long-ship six weeks past landfall without a man taking the shivers. I trade a finished cask for forty <span style=\"BandItPlus.Coin\">denars</span> and the buyers think they're robbing me.\n\nI learned the copper-cask from an old steward called <span style=\"BandItPlus.Name\">Eystein</span> who served three chiefs before mine and lost his right hand to a hauling-rope off the cliffs near <span style=\"BandItPlus.Place\">Omor</span>. He used to say the sea decides who eats and who feeds the gulls, and a steward's only job is to make sure the answer comes out right for his own crew. He showed me the trick the winter before he died — one-handed, mind you, scooping juniper from a clay pot while I stirred — and made me promise I'd never sell the method to a shore-man. I haven't. Not in eleven seasons.\n\nThe nets I knot are a separate matter and any rope-hand can copy them, but the cure goes with me to whatever cold strand the sea picks. If a man asks me sweetly and pays for two casks at once I might let slip that copper matters, but I won't say why, and I won't say how long. <span style=\"BandItPlus.Name\">Eystein</span>'s ghost can keep that much for himself."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_335", "Knots, Salt, and Debt"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_336", "A man pays himself into this trade with cold hands and colder patience. I learned the knots on my father's smack out of <span style=\"BandItPlus.Place\">Rivacheg</span>, mending herring-nets by lamp-oil before I could swing an oar. When the ice-wind took him over the gunwale one black October, the boat went to his brother and the debt came to me — eight <span style=\"BandItPlus.Coin\">denars</span> a week to a salt-factor who smiled like a gutted cod.\n\nI tried the honest run for three winters. Hauled barreled cod down to <span style=\"BandItPlus.Place\">Revyl</span>, sold smoked eel at the quay-markets, kissed the boots of every customs-clerk who'd take a bribe in fish instead of coin. Then <span style=\"BandItPlus.Name\">Lord Hrothgyr</span> raised his levy-tax on small craft and the salt-factor doubled his cut, and one morning I stood on my own dock owing more than the timbers were worth.\n\nThe longships came through in spring. Their steersman wanted a man who could read a net's bellyful at a glance, salt a hold so the catch held three months, and keep his mouth stitched about where the cargo came from. I weighed honest starvation against dishonest supper and chose the supper. Been salting their hold-fish ever since.\n\nI don't ask whose village the grain came from. I count barrels, I rub salt into the cracks, I knot the boarding-nets so they don't fray when a man's life hangs in them. The sea decides who eats out there — I just make sure the eating lasts till the next landing. Pay fair and you'll get a fair weight; cheat the scale and you'll find a hook in your bread."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_337", "Word From The Tides"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_338", "The fjord-towns of <span style=\"BandItPlus.Place\">Omor</span> and <span style=\"BandItPlus.Place\">Rissun</span> are paying double for salt-pork this season — the herring runs failed twice off the cold shoals, and the smokehouses sit empty. A barrel that fetched eighty <span style=\"BandItPlus.Coin\">denars</span> last winter moves for one-sixty at the wharf, no haggle, no questions asked of the seller. If you've a hold of cured meat and a stomach for the run past <span style=\"BandItPlus.Place\">Revyl</span>, that's coin worth wetting your boots for.\n\nWord came down from a gull-eyed runner two tides back — <span style=\"BandItPlus.Name\">Raganvad</span>'s steward is buying every grain-sack between here and the Sturgian shore. They mean to victual a long campaign, or feed a fleet, or both. He pays in struck silver, not promises, which is more than I can say for the southern lords. The price won't hold past midsummer, mind.\n\nSweetwine's gone scarce as a calm sea. The Vlandian galley that used to call at <span style=\"BandItPlus.Place\">Pen Cannoc</span> with casks from <span style=\"BandItPlus.Place\">Sargot</span> hasn't shown her sail in three turnings — coast watchers say she was taken near the Battanian rocks, hull and all. What stock remains, the <span style=\"BandItPlus.Place\">Quyaz</span> caravans are running overland through Khuzait country, and they ask their weight in <span style=\"BandItPlus.Coin\">dinars</span> for it.\n\nThere's a famine coming to the eastern villages, mark me. The locusts hit the rye-fields outside <span style=\"BandItPlus.Place\">Pravend</span>, and the river barges aren't moving relief fast enough. Dried eel and twice-baked ship-bread will trade for amber, for iron, for whatever a desperate man has left to give. <span style=\"BandItPlus.Name\">Mira Salt-Hand</span> at the Vlandian harbor told me as much when she ran a load past us last fortnight, and she's never wrong about a hungry market.\n\nLast bit — the smokehouse at <span style=\"BandItPlus.Place\">Omor</span> burned. Cooking-grease fire, the whole rig down to char and nails. Any cured fish you can put on the dock there before the lord rebuilds, you'll be the only seller standing. The sea decides who eats, aye, but a man with salt and a fast keel decides who eats *well*."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_339", "Holvar Net-Master"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_340", "Sail-Steward"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_341", "Mended longship sails for two captains who drowned and one who didn't. Now mends Bjornulf's. Doesn't speak much about the drowned ones — though the third's hall sits just up the coast and Holvar knows the way."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_342", "Holvar Net-Master, traveler. Bjornulf shouts you in; the longhall's another matter. The captain's mead is his to pour; my cured fish is mine to grant. Bring me {BP_VENDOR_QUEST_DESC} and I'll fill your sack from Bjornulf's own stores."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_343", "Cure fish in three rinses of saltwater, not the river-rinse the southerners use, traveler — saltwater bites the rot before it sets. The third rinse is the slow one; one breath per fish, no more. Bjornulf's hall eats through the winter on the third rinse. The southern halls don't get past the second."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_344", "Tell me the longship and the crew-count, traveler — fortnight at sea, full ration. Two denars on the salt, a sample on the saddle tonight. The cured fish'll hold to the third coast if the bag's tight."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_345", "First captain drowned with my brother aboard — Ari, eighteen winters at the oar. Second captain drowned with Bjornulf's father. The third's still going. Brother was the better fisherman. The sea takes the wrong ones first; that's the cure I learned. I rinse three times now, every fish, no exception."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_346", "Yngvar Cold-Hand keeps a longhall up the coast under the third captain's old banner — knew my brother. Tell him Holvar still rinses three; he'll seat you at the back-fire. Coin for the longship passage.")
        };
        private static readonly VendorProfile _seaGear = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_347", "Crew rowed in last sundown with a strake full of bent anchor-iron and a story worth more than the metal. Says they shadowed a billet-caravan three days out of <span style=\"BandItPlus.Place\">Pravend</span>, plate-stock bound for some hungry lord's smith. Six guards. Six. For a wagon worth eighteen thousand <span style=\"BandItPlus.Coin\">denars</span> if the steel grades clean. Whoever hired that escort is pinching coppers, and pinched coppers make a forge-smith like me very interested in where his road bends next.\n\nThe talkative one was a tin-peddler we let drink instead of drown. He swears <span style=\"BandItPlus.Name\">Lord Unwalin</span> is two months behind on his garrison's iron account and paying his armourer in promises and salt-cod. Salt-cod, brother. A vassal that can't settle a smith-bill won't settle a ransom either, so if his outriders come sniffing the cove, we hold him cheap and let the crew vote. I'd take half-price in good billet over full-price in his rusty <span style=\"BandItPlus.Coin\">denars</span>.\n\nSmugglers out of <span style=\"BandItPlus.Place\">Ortongard</span> told the cook there's a leather glut south — three tanneries dumped hides at four <span style=\"BandItPlus.Coin\">denars</span> the bundle because a southern army cancelled its order. Means scabbards and grips cost me nothing this season. Means I can wrap every axe-haft in doubled hide and still undercut the inland forges. Means, also, that anybody trying to sell us leather at the old price is robbing us, and I'll know the face when I see it.\n\nAnd one last thing the tide brought in — a grain-hoy out of <span style=\"BandItPlus.Place\">Epicrotea</span> is overpaying for pig-iron, twenty over market, because their own foundry cracked its bloomery wall. <span style=\"BandItPlus.Name\">Halvar</span> heard it twice in two different taverns, so it's true enough to act on. Bring me scrap. Bring me wrecked plate, broken cleavers, snapped anchor-flukes — anything ferrous, I'll forge it into trade-billets and we'll sail them north before their masons finish the patch. The sea gives the metal, the gossip tells us where to spend it."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_348", "Anchor-iron. That's the secret nobody west of <span style=\"BandItPlus.Place\">Jaculan</span> wants to hear, but it's the truth of every axe I hang on this rack. The crew drags up flukes and shanks from wrecks off the skerries — old <span style=\"BandItPlus.Place\">Vlandian</span> patrol-galley anchors mostly, the four-armed kind with the crown forge-welded thick — and I cut them down at the throat. The iron's been soaking brine for forty, sixty, a hundred winters. It comes out of the salt slow and stubborn and a little bit angry, and that anger is what I want in a war-axe.\n\nThe trick is the fold. Bog-iron a smith will fold seven times, eight, to chase the slag out. Anchor-iron I fold only three. Any more and you cook the sea out of it. You want to leave the salt-ghosts trapped in the grain — little black streaks you can see on the etch if you polish it right. That's where the edge lives. When you hew a shield-rim, the ghosts catch and tear instead of skidding off clean. Old <span style=\"BandItPlus.Name\">Hroar Two-Tongues</span> down at <span style=\"BandItPlus.Place\">Omor</span> calls it dirty work and charges three hundred <span style=\"BandItPlus.Coin\">denars</span> for a smooth blade. Mine go for one-twenty and bite twice as deep. Let him keep his clean steel.\n\nI quench in seawater too, not the rain barrel. Has to be drawn fresh that morning, west side of the headland where the current pulls strong — I won't use harbor water, harbor water's tired. The hiss when I drop a hot blade in is different. Sharper. My father taught me to listen for it. He was anchorsmith on a <span style=\"BandItPlus.Place\">Sturgian</span> longship before the wreck at Sigil Reef, and when they hauled him out of the surf three days later the only thing still on him was the hammer at his belt. That hammer's the one I'm holding now. He used to say all metal comes from the sea anyway — ore was just sea that forgot how to flow. I didn't understand him till I started forging from anchors. Now I think he might have been the only honest smith I ever knew.\n\nSo when you swing one of mine, you're swinging something that already drowned once and came back meaner. Keep it oiled with seal-fat, not olive — olive goes rancid and the ghosts hate the smell. And if she ever sings to you in a storm, don't be frightened. That's just the salt remembering."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_349", "Sea-Iron Paid Me In"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_350", "My da' was a wrecker on the cliffs north of <span style=\"BandItPlus.Place\">Rhotae</span>, and the sea paid him in iron more often than fish. Every storm scattered Imperial galleys on his rocks, and every dawn we'd walk the shingle pulling anchors, chain, sword-shards, broken cleats — anything the salt hadn't eaten through. He taught me to read a beach the way a townsmith reads a billet, and he taught me the only honest creed I've kept: all metal comes from the sea anyway, boy. The mines just borrowed it first.\n\nI served my apprentice years under a Vlandian smith in <span style=\"BandItPlus.Place\">Sargot</span>, hammering horseshoes for <span style=\"BandItPlus.Name\">Lord Tythos</span>'s riders until the man caught me filing down a captured corsair-axe for a dock-hand who'd paid me three <span style=\"BandItPlus.Coin\">denars</span> in copper. He called it theft of forge-time. I called it side-trade. The magistrate sided with him, and I lost the right hand at the wrist for it — not the whole hand, mind, just the four fingers and a thumb that mattered. Anchor-Hand they call me now, because what they fit me with after is a bent iron hook a Nord smith brazed onto the stump in <span style=\"BandItPlus.Place\">Omor</span>, and it grips a tong-handle better than the meat ever did.\n\nThe crew picked me up off a beached longship two winters back, half-starved and bartering my hammer for hardtack. The boys had hauled a whole Imperial bow-anchor up the strand and didn't know what to do with three hundred-weight of soft iron. I showed them. One anchor becomes eleven axes, fourteen sax-knives, and enough nails to re-strake a hull, if you know the heats. They've kept me in coal and quenching-oil ever since, and I've kept their edges honest.\n\nI don't forge for kings here, and I don't forge pretty. What I make has to bite through mail in one swing and not snap when it hits a shield-rim, because if a brother goes down for a bad weld, that's my name on the cairn. So when you bring me <span style=\"BandItPlus.Coin\">denars</span>, I weigh them against the iron the same way the sea weighs everything — slow, fair, and without flattery. Sea-iron, sea-price. That's the trade that paid me into this camp, and it's the trade that'll bury me out of it."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_351", "Sea-Iron, Sea-Word"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_352", "Word came down from <span style=\"BandItPlus.Place\">Rissal</span> last fortnight — the lord there is paying double for arrowheads, three hundred per gross. Some Vlandian dog kicked over a hornet's nest on his eastern march and now he wants every smith from here to <span style=\"BandItPlus.Place\">Ortongard</span> bent over an anvil. Won't pay sea-rates, mind. Inland coin always smells of fear and tries to haggle.\n\nThere's a steel-stock caravan coming down the coast from <span style=\"BandItPlus.Place\">Omor</span>, heading for the Vlandian markets. Three wagons, Battanian guards, moves slow on the headland road past the white cliffs. I'm not telling you what to do with that. I'm telling you what's on the road. <span style=\"BandItPlus.Name\">Eirik Stormcrow</span> over in the next bay already knows. He pays his crew in <span style=\"BandItPlus.Coin\">denars</span> now, not shares — make of that what you will.\n\n<span style=\"BandItPlus.Name\">Lord Caladog</span> commissioned a hundred shields out of <span style=\"BandItPlus.Place\">Pen Cannoc</span> — limewood, iron rims, his clan-knot pressed in the leather. The smiths there are turning away apprentices and the price of rivet-stock has gone stupid. If you've got a sack of bog-iron lying somewhere you forgot about, take it inland. You'll come back rich enough to drink for a season.\n\nSaddle-trade is dying on the steppe road. Khuzait riders aren't buying — something's stirring out past <span style=\"BandItPlus.Place\">Quyaz</span> and they're making their own gear, fast and rough. The leather-cutter in <span style=\"BandItPlus.Place\">Revyl</span> told me he hasn't sold a war-saddle in two moons. Bad sign for him. Good sign for whoever buys his stock cheap before he packs it in.\n\nLast word — and this one's worth the listening. A Sturgian smith called <span style=\"BandItPlus.Name\">Vasili Greybeard</span> died at his forge last month, left a workshop full of half-finished pattern-welded blades and nobody to claim them. His widow's selling the lot for under two thousand <span style=\"BandItPlus.Coin\">denars</span> just to clear the floor. That's anchor-iron prices for sword-steel. Somebody's going to walk into <span style=\"BandItPlus.Place\">Revyl</span> and walk out a rich man. Might as well be someone who knows how to listen."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_353", "Snorri Anchor-Hand"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_354", "Forge-Smith"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_355", "Forged longship anchors and sword-edges for three crews before settling under Bjornulf's hall. Salt-bleached like everything else here. Says the salt makes his steel sing different — \"Sturgian-deep,\" he calls it."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_356", "Snorri Anchor-Hand, salt-smith. Bjornulf laughs you in — that's the captain. The forge takes its measure slower. Bring me {BP_VENDOR_QUEST_DESC} and I'll edge you a blade the longhall posts will remember the day you walked out with it."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_357", "Salt-bleached steel sings different, traveler — the brine bites the grain, the edge takes the bite. Imperial smiths fresh-water their tempers and wonder why their blades chip on the third strike. Sturgian-deep, I call it. The longhall posts still bear my anchor-marks where they bit on the first cut."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_358", "Bring me a steel-bar and a longship-deck, traveler — I'll edge you a blade the longhall'll remember. Five denars on the heat, the brine's already drawn. Here, a wedge for your belt while it cools."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_359", "Wife drowned at the first cure — Helga, twenty winters at the smithy. She'd boil the brine while I struck. The longhall keeps her name in the rafter beam, third post from the door. I run the blade across the post every new moon, just to listen. The wood still answers."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_360", "Old Sigurd forges at the Sturgian dock-quarter under the old longhall's stamp — Helga's brother by oath. Tell him Snorri still brines deep; he'll show you the anchor-mark anvil. Coin for the longship passage.")
        };

        // ===== DESERT BANDITS (Hakkun the Sand-Reader's band) =====
        private static readonly VendorProfile _desertFood = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_361", "Sit, sit. The clay pot does not boil faster for staring at it, and old Kareem has tongues to wag while the dates soften. You smell that? Cardamom from a caravan that limped through here three sunrises ago, paid me in spice because their coin-purse was already light. They came down from <span style=\"BandItPlus.Place\">Husn Fulan</span> talking like men who had seen ghosts. Said the granaries up that way are half-empty, that the steward there is buying wheat at near a denar a measure when last moon it was selling for sixty. Someone, somewhere, has held back his harvest, and the price climbs each week the wind blows wrong.\n\nNow, here is the meat in the broth. The salt road that bends past the dry wadis, the one the caravan-masters call the Long Tongue, it carries only six spears with it now. Six. For wagons hauling rock-salt and dried fish out toward <span style=\"BandItPlus.Place\">Quyaz</span>. The merchant <span style=\"BandItPlus.Name\">Habib al-Mu'allim</span> is the one paying for the escort, and his guards grumble he has stopped buying them new boots. A man who saves on his guards' boots saves on his guards' loyalty, you understand me? Six spears, fat sacks, and a master whose purse-strings are knotted twice. I do not say it is an invitation, brother. I only say the soup notices when meat falls in.\n\nThe cook before me, may his soul digest gently, told me always: listen for which lord borrows from which merchant. Word from the cousin of my brother-in-law, a fig-hauler, is that the lord at <span style=\"BandItPlus.Place\">Bilghar</span> is so short on <span style=\"BandItPlus.Coin\">denars</span> he sold his own wife's cookware to settle a debt with the spice guild. When a noble pawns the pots, he soon pawns the patrols. Mark which villages near his lands lose their riders first. That is where the smokehouses will go quiet, that is where the salted goat will stop reaching market, and that is where a hungry caravan will pay double for what we can supply.\n\nOne more thing, then I must turn the dates before they weep. There is a fool of a grain-buyer working the eastern oases, a fat-faced southerner named <span style=\"BandItPlus.Name\">Yusuf bin Tareeq</span>, who pays seventy <span style=\"BandItPlus.Coin\">denars</span> the measure for barley he could get for forty if he only haggled. The boys say he is buying for some northern lord's army and does not care what it costs, only that the sacks arrive. If you happen to come into barley, by whatever wind blows it your way, ride east, find the fat-face, and let him empty his purse into yours. Now go. The dates are calling, and old Kareem does not let dates wait on gossip."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_362", "Most folk think a date is a date. Squeeze it, sniff it, pop it in the mouth — sweet is sweet, yes? No. A date sings, friend. Press your thumb against the skin and listen with your fingers. The <span style=\"BandItPlus.Place\">Nahasa</span> khalas hums low and oily, made for slow stewing. The amber ajwa from the high palms snaps like dry parchment — that one you crush into the salt jar, never the pot. I learned this from my mother in a caravanserai outside <span style=\"BandItPlus.Place\">Quyaz</span>, before the soldiers came and the well went bitter. She would not let me touch the cooking fire until I could tell her, blindfolded, which of seven dates came from which oasis. Took me until I was eleven summers.\n\nSo here is the secret of my pot, and I tell it because you have paid in good <span style=\"BandItPlus.Coin\">denars</span> and because old men grow tired of hoarding. I cook lamb in three layers. The bottom: green dates, the under-ripe ones the merchants throw out — these I pound with cumin seed and the rendered tail-fat of the fat-tailed sheep, and I press it into the clay before any meat touches it. This is the foundation. The middle: the meat itself, rubbed only with sour camel-yogurt and a black salt I cure myself from the flats near <span style=\"BandItPlus.Place\">Husn Fulq</span>. No spice. Spice in the middle is a coward's trick. The top: a crown of fully-ripe medjool, split and seeded, laid skin-down like little boats. Sealed with a paste of flour and water around the lid. Six hours in the coals. The green ones below give the bite, the medjool above weep their honey down through the meat. By the time you break the seal, the lamb has eaten the dates and the dates have eaten the lamb, and you cannot tell where one ends.\n\nThe trick, the real trick — lean closer, I will not shout it — is the black salt. Every cook claims a salt blend. Mine is roasted in a sealed pot with a single handful of dried pomegranate skin and three locust husks. Yes, locusts. The husks burn to a bitter ash that pulls the sweetness of the date sideways into something the tongue cannot name. <span style=\"BandItPlus.Name\">Yusuf the Lame</span> tried to steal the recipe by watching me through a tent-slit in <span style=\"BandItPlus.Place\">Iqbayl</span>; he got the pomegranate but missed the locusts, and now his stew tastes like a sad woman's apology. I do not laugh at him. Much.\n\nI have not cooked at a proper hearth in eleven years. The caravan moves, the pots travel rolled in felt, and I read the dates by torchlight while younger men watch the dunes for riders. Sometimes I think of my mother's kitchen, the blue tiles, the smell of cardamom at dawn. Then I taste a khalas, and I know which oasis it grew in, and I know I am still her son. Eat slowly, friend. A date that took seven months to ripen deserves more than two bites."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_363", "A Pot, A Palm, A Patience"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_364", "My father kept a date-grove outside <span style=\"BandItPlus.Place\">Quyaz</span>, and before I could lift a basket he taught me to listen to the fruit. A date talks, friend — the thin-skinned ones whisper of too much sun, the heavy ones grunt of a slow autumn, and the sweet-bellied khalas hum like a woman who knows she is loved. I read them the way the qadi reads scripture, and by my twelfth season my father charged the caravans an extra <span style=\"BandItPlus.Coin\">dinar</span> a sack because the boy could pick out the bitter ones blind.\n\nThen came the tax-year <span style=\"BandItPlus.Name\">Emir Unqid</span> doubled the salt levy, and the grove went to his bailiff for a debt my father did not owe. I walked west with a clay pot, a handful of pits, and the clothes the bailiff did not bother to take. For a long season I cooked for a spice train running between <span style=\"BandItPlus.Place\">Iqbayl</span> and the southern wells — millet porridge in the mornings, mutton and dates stewed slow at night, the kind of food that keeps a man upright in a saddle for sixteen hours.\n\nA raid finished the spice train south of the salt pans. The drivers ran, the camels scattered, and I sat down beside my pot because a man my age does not outrun horses. The chief of that raiding band lifted the lid, tasted the stew, and laughed — said any cook who could keep a stew sweet through a fight was worth more than the silver in the saddlebags. So he kept me, the pot, and the last of my dates, and rode me here.\n\nThat was eleven seasons ago. The boys bring me grain stolen off the <span style=\"BandItPlus.Place\">Pravend</span> road, salt prised from southern flats, smoked goat from the high pens, and I turn it into something that tastes like a man still has a home. I keep my own date-palms now, in pots beside the cistern — three of them, grown from the pits I carried out of <span style=\"BandItPlus.Place\">Quyaz</span>. They fruit thin and bitter, but they fruit.\n\nSo that is what pays a man into this trade — a stolen grove, a slow kettle, and the simple truth that hungry men do not care whose flag flies over the cook. Patience opens the date. Coin opens the pot. Sit, and I will open both."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_365", "Word From The Dune-Tracks"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_366", "Sit, sit. The clay pot keeps its heat better than my old bones, so lean close. Word came in two nights past with the salt-runners out of <span style=\"BandItPlus.Place\">Quyaz</span> — the granaries there have cracked open at last, and the steward is paying eighty <span style=\"BandItPlus.Coin\">dinars</span> the sack for any clean barley that still smells of the field. If you carry grain south, do not waste it on the coastal towns. Quyaz hungers louder.\n\nThere is a sweetwine caravan crawling up from <span style=\"BandItPlus.Place\">Iyakis</span> — six camels, two of them limping, and the master is a Vlandian called <span style=\"BandItPlus.Name\">Tomas of the Vine</span> who tips his guards in copper and his cook in nothing at all. They take the long western track to avoid the toll-fort. If you have honey or pressed dates to trade, his hands are loose by the third cup of his own cargo. I would know. I taught the boy who pours for him.\n\nBad news rides faster than good. The southern oases between <span style=\"BandItPlus.Place\">Ar-Razir</span> and the salt-flats have gone bitter — three wells in a row, all fouled, and the goat-herds are already burning their dead kids. A thin year is coming for that whole stretch. Buy your dried meat now, before the harvest-towns hear and the price jumps. Salt too. Always salt.\n\nA merchant out of <span style=\"BandItPlus.Place\">Husn Fulq</span> rode through yesterday looking for cinnamon and saffron at any price — some Aserai emir is marrying his third daughter and the kitchens are panicking. Spice that cost you forty <span style=\"BandItPlus.Coin\">dinars</span> last moon will fetch a hundred and twenty if you reach the wedding gate before the feast. Ride hard, or do not bother.\n\nAnd one whisper, friend, because you bought the date and not just the talk. <span style=\"BandItPlus.Name\">Sister Halima</span> who keeps the smokehouse at the second waterhole has begun salting twice what she sold last season. She does not salt for nothing. Either she knows a famine I have only smelled, or a war-band is paying her in advance. Either way — fill your saddlebags with hearth-bread and dried lamb before you ride west. The pots here will still be warm when you return. If you return."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_367", "Old Kareem Date-Reader"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_368", "Caravan-Cook"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_369", "Read sand for caravans before the dunes claimed his last wife. Now reads it for Hakkun's fires; the cookpot fills the same. Says the sand told him three winters back that you'd come — but the sand says that to everyone."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_370", "Old Kareem Date-Reader. The sand spoke your name three days running, traveler — Hakkun's reading. The cookpot heard it once. Bring me {BP_VENDOR_QUEST_DESC} from the road, and the dunes will speak it fairer come morning."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_371", "Sand-cured dates take the four-day tent, not the three the Quyaz merchants rush, traveler. Fourth day's the bite — the sun pulls the last water and leaves the sugar in long strands. The dunes know the count. The merchants don't ask the dunes."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_372", "Tell me the caravan and the rite, traveler — wedding-night, name-day, mourner's pour. Three denars on the tent, a fortnight on the cure. A date for tonight's road-ration."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_373", "Wife went under to the dunes — sand-storm, the long crossing, the third caravan I lost. The sand said her name back to me the next dawn; said it three days running. I read sand for Hakkun's fires now and the sand still says her name some nights. I keep listening because she's still saying it."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_374", "Old Yusra reads sand at the Quyaz market-edge under a date-stall awning — knew my wife. Tell her Kareem still cures four days; she'll show you the back-tent. Coin for the desert crossing.")
        };
        private static readonly VendorProfile _desertGear = new VendorProfile {
            T2RoadGossipBody = BandItPlus.Localization.Get("bp_vendorprofiles_375", "Sit. The coals are hot and so is the tongue today. A salt-trader out of <span style=\"BandItPlus.Place\">Quyaz</span> staggered in at dawn looking for a re-shod camel and a man to listen, and I am both. He says <span style=\"BandItPlus.Name\">Emir Unqid</span> is bleeding silver — three caravans gone to our cousins this season, and his clan-coffers down to whispers. The emir's quartermaster was at <span style=\"BandItPlus.Place\">Iqbayl</span> last week offering <span style=\"BandItPlus.Coin\">240 denars</span> a head for any veteran who could ride a sand-mare. That is the price of a desperate man, friend. A lord who pays 240 today pays nothing next month, because his caravans will be lighter still.\n\nNow lean closer — this is the part worth the visit. The <span style=\"BandItPlus.Place\">Husn Fulq</span> road, the long crooked one that hugs the dry wadi, is running with two-spear escorts. Two. For caravans hauling steel billets out of the northern foundries. I have seen the wagons myself, axles dragging, and the guards are boys with their fathers' helmets sliding into their eyes. Whoever owns those billets — and a smuggler hinted it is a factor working for <span style=\"BandItPlus.Name\">Hakim al-Sarraj</span> — has bet on speed over swords. Steel-billet caravans, my friend. The kind a forge would weep for. The kind a clever cousin would meet at the third bend past the dry well, where the cliffs throw a shadow at second prayer.\n\nThe grain news is uglier and that is why I am pricing scimitars at a discount this fortnight. <span style=\"BandItPlus.Place\">Razih</span>'s smokehouses burned in the dry-wind storms — three of them, the big ones — so cured meat is gone from every market between here and the coast and salt has tripled. The caravans coming up from the southern salt-pans are guarded like queens. Do not touch them. But the GRAIN going DOWN to feed those same salt-pans is barely watched, because nobody guards what nobody robs. <span style=\"BandItPlus.Name\">Merchant Yusra bint Tahir</span> is overpaying — <span style=\"BandItPlus.Coin\">85 denars</span> a sack at <span style=\"BandItPlus.Place\">Mughar</span>, which is twice the honest price — because her ovens go cold without it. A wagon of her grain re-sold to her own factor at a different gate would be tidy work.\n\nOne last thing, and then I want to see coin on the anvil. There is a leather glut. A tannery upriver miscounted its herds and the hides are piling up — three caravans came through last week with bundled hides nobody wants, sold at thirty a stack and the owners glad to be rid of them. I bought what I could for grips and scabbards, which is why these curved blades on the rack are cheaper than last moon. The desert heat does half the work; a cousin's whisper does the other half. So — are you buying a sword, or buying a map? I sell both, and the second one costs more."),
            T2CraftSecretBody = BandItPlus.Localization.Get("bp_vendorprofiles_376", "The desert is half the work. People hear me say it and laugh, but I mean it the way a man means his own name. The forge gives me the first heat — the sand gives me the second. When I draw a blade from the coals and lay it on the long iron tray sunk into the floor, the sand under it is already eighty degrees from noon. It does not steal the warmth back the way a stone slab would. The steel cools the way a man falls asleep in shade — slow, even, no flinch in the grain. That is half my temper, and I never paid a copper for it.\n\nThe other half is the curve. Every Sand-Smith out here forges curved, and every fool thinks the curve is for looking pretty on a hip. It is not. A curve cuts longer because the edge meets the meat at a slipping angle, the way a reed knife peels a date. I draw mine with a fuller no thicker than a thumb-bone, set high on the spine, and I never grind the belly symmetrical — the underside of the curve gets a finer bevel than the top, because the underside is what does the work in the downstroke from a camel. A straight-ground blade chips on the third fight. Mine come back to me after twenty, and the owners want them re-polished, not re-edged. That is the difference, and I charge eight hundred <span style=\"BandItPlus.Coin\">denars</span> for it without blinking.\n\nThe quench is where I lose apprentices. I do not use water and I do not use oil — I use brine drawn from the salt-pans south of <span style=\"BandItPlus.Place\">Quyaz</span>, three jugs a season, hauled in by a cousin who owes me his teeth. The salt bites the surface faster than oil and leaves a skin on the steel that takes rust the way a tortoise takes rain — it just shrugs. You can leave one of my blades on a saddle for a week of sandstorm and the edge will still shave. Try that with a <span style=\"BandItPlus.Place\">Sturgian</span> longsword and you will be filing red dust off it by the second night.\n\nI learned all of this from my father, who learned it from his, and his hammer is the one on the second peg — the short one with the cracked haft I will not replace. He worked this same floor when the gang here was only six men and a goat, and when <span style=\"BandItPlus.Name\">Sariq</span>'s grandfather was still raiding caravans on foot. I tell the young ones who come to buy that they are not paying for the steel. They are paying for four generations of men who learned that the desert is a partner, not an enemy, and that a smith who fights his climate dies poor. I have never been poor. Look at the rings."),
            SelfStoryTitle = BandItPlus.Localization.Get("bp_vendorprofiles_377", "Heat, Hammer, And A Debt"),
            SelfStoryBody = BandItPlus.Localization.Get("bp_vendorprofiles_378", "My father was a knife-grinder in <span style=\"BandItPlus.Place\">Quyaz</span>, and his father a horseshoer before him. I learned the bellows before I learned my letters. By twelve I could draw a tang true; by sixteen I could fold a billet seven times without a single grey seam. The trade was honest then, and the sand was just sand.\n\nI set up my own forge along the caravan road south of <span style=\"BandItPlus.Place\">Iqbayl</span>. Curved blades, mostly — a desert man wants a sword that draws clean from the saddle and clears the scabbard before his horse takes a second step. <span style=\"BandItPlus.Name\">Emir Unqid</span>'s outriders bought from me, and so did the spice-guards bound for <span style=\"BandItPlus.Place\">Pen Cannoc</span>. Three hundred <span style=\"BandItPlus.Coin\">dinars</span> for a good shamshir, more if the customer wanted gold wire down the fuller. I was not rich, but I slept on a proper rope-bed.\n\nThe debt is what brought me here. A caravan-master fronted me ore from <span style=\"BandItPlus.Place\">Husn Fulq</span> on credit, and his caravan never came back from the dunes. His brother wanted blood or coin, and I had neither in the quantity he preferred. The camp's quartermaster heard of my trouble and made me an offer — work the forge here, the debt becomes his problem, and a man stops looking over his shoulder for the brother's knife.\n\nSo now I forge in a sand-floored shop with the desert pressing against my back. The heat is half the work, you understand — the sun softens the steel before the coals ever touch it, and a smith who knows the trick saves a third of his charcoal. My blades go out on the saddles of men who do not always come back, but the steel does not care who carries it. Steel only cares that it was made true.\n\nI do not call this a fall. I call it a season. The forge is hot, the coin is honest, and the brother of that caravan-master is two provinces away. A man can live a long while on less."),
            NewsRumorsTitle = BandItPlus.Localization.Get("bp_vendorprofiles_379", "Words From the Bellows"),
            NewsRumorsBody = BandItPlus.Localization.Get("bp_vendorprofiles_380", "Aye, sit close to the bellows — the wind eats words out there. The road's been busy this moon, and a man who hammers steel hears more than a man who carries it. Caravans stop here for water, and water loosens tongues better than wine. Listen.\n\nA long string of Aserai pack-camels is creeping up from the southern wastes toward <span style=\"BandItPlus.Place\">Quyaz</span>, hauling Khuzait raw iron through a back-trail their guides swear no patrol uses. Twenty bars per beast, near forty beasts. If it arrives, every smith from here to the dune-line drops their price on billet. If it doesn't arrive — well, then I get rich, and somebody's bones bleach a little whiter.\n\n<span style=\"BandItPlus.Name\">Emir Tamar</span> is paying real coin at <span style=\"BandItPlus.Place\">Sanala</span> for any smith who can hammer mamluke sabres to the old curve — eight <span style=\"BandItPlus.Coin\">dinars</span> a blade, lodging thrown in, and he asks no questions about the man's last forge. Half the journeymen out of <span style=\"BandItPlus.Place\">Iqbayl</span> have already walked there. I'd go myself if I hadn't sworn off cities that hang their smiths when the war turns.\n\nA noble's quartermaster came through three nights past, looking to buy four hundred leather-faced shields before the dry season breaks. He flashed a purse of <span style=\"BandItPlus.Coin\">dinars</span> stamped with the Banu Hilal seal, which means somebody in the deep south is preparing to march and doesn't want it known yet. Watch the southern trade roads close — when shields move in bulk, blood follows within two moons.\n\nLast bit, friend, and worth the listening. The old salt-and-iron caravan that links <span style=\"BandItPlus.Place\">Bilegan</span> to <span style=\"BandItPlus.Place\">Quyaz</span> has lost two runs in a row to no bandit I know of — clean ambushes, no bodies, just empty wagons. Somebody's hoarding steel-stock and doesn't want the market to figure it out. If you've a strong arm and a quiet horse, there's coin to be made escorting the next run. Or taking it."),
            Name = BandItPlus.Localization.Get("bp_vendorprofiles_381", "Zafir of the Forge"),
            Title = BandItPlus.Localization.Get("bp_vendorprofiles_382", "Sand-Smith"),
            Backstory = BandItPlus.Localization.Get("bp_vendorprofiles_383", "Forges in the dunes the way other smiths forge in towns — slower, by sun-heat as much as charcoal. The blades he tempers cool blue under the desert moon, which Hakkun says is the dunes' approval."),
            GateSpeech = BandItPlus.Localization.Get("bp_vendorprofiles_384", "Zafir of the Forge. Hakkun reads sand; I read steel. The Sand-Reader's word is good. Mine's slower — sun-heat takes its time. Bring me {BP_VENDOR_QUEST_DESC} and I'll cool you a blade as blue as the noon sky over the dunes."),
            T2CraftDetail = BandItPlus.Localization.Get("bp_vendorprofiles_385", "Sun-heat tempers different than charcoal, traveler — slower bite, longer hold. The blade cools blue under the desert moon, not the imperial grey. Hakkun says it's the dunes' approval. I think it's the patience. Either way the blade holds three campaigns where the Quyaz issue gives up at one."),
            T2CustomOrderTease = BandItPlus.Localization.Get("bp_vendorprofiles_386", "Bring me a steel-bar, a draw-weight, and a noon-time, traveler. I'll temper you a blade the dunes've signed. Six denars on the sun-heat, the brine's the desert's. A small spike for your belt tonight."),
            T3FamilyBeat = BandItPlus.Localization.Get("bp_vendorprofiles_387", "Son apprenticed under me — twelve summers at the bellows. The desert took him at the fifth crossing; not the sand, the heat. Stuck at the high noon when I told him to rest. The forge was his first word. He'd be twenty-five now. I temper at noon still, the way he wanted."),
            T3ContactName = BandItPlus.Localization.Get("bp_vendorprofiles_388", "Old Hassan forges at the Quyaz inner-quarter — sun-heat trade by the same dunes. Tell him Zafir still cools blue; he'll show you the back-anvil. Coin for the desert crossing.")
        };
    }
}
